import { CreatureType, Entity, GameState, GameStatus, Particle, PlayerState } from './types';

// Helper for unique IDs
const uuid = () => Math.random().toString(36).substr(2, 9);

// Distance helper
const dist = (e1: {x: number, y: number}, e2: {x: number, y: number}) => 
  Math.hypot(e1.x - e2.x, e1.y - e2.y);

// Create Entity
export const createEntity = (type: CreatureType, x: number, y: number): Entity => {
  const config = CREATURES[type];
  return {
    id: uuid(),
    type,
    x,
    y,
    vx: (Math.random() - 0.5) * config.speed,
    vy: (Math.random() - 0.5) * config.speed,
    radius: config.baseRadius,
    angle: Math.random() * Math.PI * 2,
    health: config.health,
    maxHealth: config.health,
    speed: config.speed,
    config
  };
};

export const createParticle = (x: number, y: number, color: string): Particle => ({
  id: uuid(),
  x,
  y,
  vx: (Math.random() - 0.5) * 4,
  vy: (Math.random() - 0.5) * 4,
  life: 1.0,
  maxLife: 1.0,
  color,
  size: Math.random() * 3 + 2
});

// AI Behavior Logic
const updateAI = (entity: Entity, player: PlayerState, entities: Entity[], worldW: number, worldH: number) => {
  let tx = entity.x + entity.vx * 20; // Default: Keep moving
  let ty = entity.y + entity.vy * 20;

  const distToPlayer = dist(entity, player);
  const detectionRange = 400 * (entity.config.tier === 4 ? 3 : 1); // Bosses see further

  // 1. Boundary Avoidance
  const margin = 200;
  if (entity.x < margin) tx += 100;
  if (entity.x > worldW - margin) tx -= 100;
  if (entity.y < margin) ty += 100;
  if (entity.y > worldH - margin) ty -= 100;

  // 2. Player Interaction
  if (distToPlayer < detectionRange) {
    if (entity.config.behavior === 'AGGRESSIVE' || entity.config.behavior === 'BOSS') {
      // Chase player if bigger or roughly same size
      if (entity.radius > player.radius * 0.8) {
        tx = player.x;
        ty = player.y;
      } else {
        // Flee if smaller aggressive
        tx = entity.x - (player.x - entity.x);
        ty = entity.y - (player.y - entity.y);
      }
    } else if (entity.config.behavior === 'FLEE') {
      // Run away
      tx = entity.x - (player.x - entity.x);
      ty = entity.y - (player.y - entity.y);
    }
  }

  // 3. Move towards target
  const angleToTarget = Math.atan2(ty - entity.y, tx - entity.x);

  // Smooth rotation
  let angleDiff = angleToTarget - entity.angle;
  while (angleDiff > Math.PI) angleDiff -= Math.PI * 2;
  while (angleDiff < -Math.PI) angleDiff += Math.PI * 2;
  entity.angle += angleDiff * 0.05;

  entity.vx = Math.cos(entity.angle) * entity.speed;
  entity.vy = Math.sin(entity.angle) * entity.speed;

  entity.x += entity.vx;
  entity.y += entity.vy;
};

// Spawning Logic
const spawnEntities = (state: GameState) => {
  if (state.entities.length >= MAX_ENTITIES) return;

  // Chance to spawn based on player level/size
  // Biome simulation: 
  // Small player -> Shallow water (Tier 1 & 2)
  // Medium player -> Coral/Open (Tier 2 & 3)
  // Large player -> Deep (Tier 3 & 4)

  const r = Math.random();
  let type: CreatureType = CreatureType.PLANKTON;

  const tier1Prob = state.player.level === 1 ? 0.8 : state.player.level === 2 ? 0.4 : 0.2;
  const tier2Prob = state.player.level === 1 ? 0.15 : state.player.level === 2 ? 0.4 : 0.3;
  // Remaining probability goes to higher tiers

  if (r < tier1Prob) {
    const subR = Math.random();
    type = subR < 0.5 ? CreatureType.PLANKTON : subR < 0.8 ? CreatureType.ALGAE_FISH : CreatureType.JELLYFISH;
  } else if (r < tier1Prob + tier2Prob) {
    const subR = Math.random();
    type = subR < 0.4 ? CreatureType.NEEDLE_FISH : subR < 0.7 ? CreatureType.ARMOR_FISH : CreatureType.POISON_FISH;
  } else {
    // High tier
    const subR = Math.random();
    if (state.player.level >= 4 && Math.random() < 0.01 && !state.entities.find(e => e.type === CreatureType.LEVIATHAN)) {
      type = CreatureType.LEVIATHAN; // Boss spawn rare
    } else {
      type = subR < 0.4 ? CreatureType.SWORD_FISH : subR < 0.7 ? CreatureType.EEL : CreatureType.MEGA_MOUTH;
    }
  }

  // Spawn away from player
  let sx, sy;
  do {
    sx = Math.random() * WORLD_SIZE;
    sy = Math.random() * WORLD_SIZE;
  } while (dist({x: sx, y: sy}, state.player) < 800); // Don't spawn on screen

  state.entities.push(createEntity(type, sx, sy));
};

export const updateGame = (state: GameState, mouse: {x: number, y: number}, screenW: number, screenH: number): GameState => {
  if (state.status !== GameStatus.PLAYING) return state;

  const { player } = state;

  // --- Player Movement ---
  // Mouse is relative to screen center (0,0 is center) in input handling usually, 
  // but let's assume mouse is screen coordinates.
  // We need to translate screen mouse pos to world angle relative to player
  const screenCenterX = screenW / 2;
  const screenCenterY = screenH / 2;

  const dx = mouse.x - screenCenterX;
  const dy = mouse.y - screenCenterY;

  const targetAngle = Math.atan2(dy, dx);

  // Physics: Smooth turn
  let angleDiff = targetAngle - player.angle;
  while (angleDiff > Math.PI) angleDiff -= Math.PI * 2;
  while (angleDiff < -Math.PI) angleDiff += Math.PI * 2;

  // Turn speed decreases as size increases (Newtonian-ish)
  const turnSpeed = 0.15 / player.stats.sizeMult; 
  player.angle += angleDiff * turnSpeed;

  const currentSpeed = player.speed * player.stats.speedMult;
  player.vx = Math.cos(player.angle) * currentSpeed;
  player.vy = Math.sin(player.angle) * currentSpeed;

  player.x = Math.max(player.radius, Math.min(WORLD_SIZE - player.radius, player.x + player.vx));
  player.y = Math.max(player.radius, Math.min(WORLD_SIZE - player.radius, player.y + player.vy));

  // --- Entities Update ---
  state.entities.forEach(entity => {
    updateAI(entity, player, state.entities, WORLD_SIZE, WORLD_SIZE);
  });

  // --- Collision & Eating ---
  const newParticles: Particle[] = [];
  const entitiesKeep: Entity[] = [];

  for (const entity of state.entities) {
    const d = dist(player, entity);
    const minDistance = player.radius + entity.radius;

    if (d < minDistance) {
      // Collision occurred

      // EATING LOGIC: Size >= 1.2x to eat comfortably
      // If smaller, take damage

      const canEat = player.radius >= entity.radius * 1.1; // Slightly easier than 1.2
      const isDangerous = entity.config.behavior === 'AGGRESSIVE' || entity.config.behavior === 'BOSS' || entity.config.special === 'SPIKE';

      if (canEat) {
        // Eat Success
        player.xp += entity.config.xpValue;

        // Track history for evolution
        player.eatenHistory[entity.type] = (player.eatenHistory[entity.type] || 0) + 1;

        // Effects
        // Special interactions
        if (entity.config.special === 'POISON' && !player.traits.includes('POISON_IMMUNITY')) {
          player.health -= 10;
          newParticles.push(createParticle(player.x, player.y, '#a3e635'));
        }
        if (entity.config.special === 'SHOCK' && !player.traits.includes('SHOCK_RESIST')) {
          player.health -= 5;
           // Stun mechanic could go here (reduce speed briefly)
        }

        // Heal slightly on eat
        player.health = Math.min(player.maxHealth, player.health + entity.config.health * 0.2);

        // Visuals
        for(let i=0; i<5; i++) newParticles.push(createParticle(entity.x, entity.y, entity.config.color));
        continue; // Remove entity
      } else {
        // Can't eat. 
        if (isDangerous || player.radius < entity.radius) {
          // Take damage
          // Bounce back slightly
          player.x -= player.vx * 2;
          player.y -= player.vy * 2;

          let dmg = entity.config.damage > 0 ? entity.config.damage : 5;

          // Defense mitigation
          dmg = Math.max(1, dmg / player.stats.defenseMult);

          player.health -= dmg;
          newParticles.push(createParticle(player.x, player.y, '#ef4444')); // Blood
        }
        entitiesKeep.push(entity);
      }
    } else {
      entitiesKeep.push(entity);
    }
  }
  state.entities = entitiesKeep;

  // --- Level Up Check ---
  const nextLevelXp = LEVEL_THRESHOLDS[player.level] || 999999;
  if (player.xp >= nextLevelXp) {
    player.level++;
    player.evolutionPoints++;
    player.radius *= 1.1; // Grow size naturally on level up
    player.maxHealth += 20;
    player.health = player.maxHealth;
    state.status = GameStatus.EVOLVING; // Trigger pause/menu
  }

  // --- Particle Update ---
  state.particles = state.particles.map(p => ({
    ...p,
    x: p.x + p.vx,
