  const [uiState, setUiState] = useState<GameState>(gameStateRef.current);

  const mouseRef = useRef({ x: 0, y: 0 });
  const frameIdRef = useRef<number>(0);

  // Sync state for UI updates (throttled)
  useEffect(() => {
    const interval = setInterval(() => {
      // Only update React state if something relevant to UI changed
      const currentState = gameStateRef.current;
      setUiState({ ...currentState });
    }, 100); // 10 FPS UI updates are enough
    return () => clearInterval(interval);
  }, []);

  const startGame = () => {
    gameStateRef.current = createInitialState();
    gameStateRef.current.status = GameStatus.PLAYING;

    // Initial Spawn
    for(let i=0; i<20; i++) {
        const x = Math.random() * WORLD_SIZE;
        const y = Math.random() * WORLD_SIZE;
        gameStateRef.current.entities.push(
