        gameStateRef.current,
        mouseRef.current,
        window.innerWidth,
        window.innerHeight
      );
      gameStateRef.current.score += 0.05; // Survival points
    }
    frameIdRef.current = requestAnimationFrame(gameLoop);
  }, []);

  useEffect(() => {
    frameIdRef.current = requestAnimationFrame(gameLoop);
    return () => cancelAnimationFrame(frameIdRef.current);
  }, [gameLoop]);

