        gameState={gameStateRef.current} 
        onMouseMove={handleMouseMove} 
      />

      <UIOverlay 
        gameState={uiState} // UI needs to be reactive
        onStart={startGame}
        onEvolve={handleEvolve}
        onRestart={startGame}
      />
    </div>
  );
};

