      x = Math.random() * WORLD_SIZE;
      y = Math.random() * WORLD_SIZE;
    } while (dist({x, y}, {x: WORLD_SIZE/2, y: WORLD_SIZE/2}) < 500);

    obstacles.push({
      id: uuid(),
      x,
      y,
      radius,
      type
    });
  }
