    const minDistance = player.radius + entity.radius;

    if (d < minDistance) {
      // STRICT SAFE ZONE: If either is hidden, no interaction happens.
      if (player.isHidden || entity.isHidden) {
        entitiesKeep.push(entity);
        continue;
      }

      const canEat = player.radius >= entity.radius * 1.1; 
      const isDangerous = entity.config.behavior === 'AGGRESSIVE' || entity.config.behavior === 'BOSS' || entity.config.special === 'SPIKE';

      if (canEat) {
        // Eat Success
        player.xp += entity.config.xpValue;
        player.eatenHistory[entity.type] = (player.eatenHistory[entity.type] || 0) + 1;

        // Effects
        if (entity.config.special === 'POISON' && !player.traits.includes('POISON_IMMUNITY')) {
          player.health -= 10;
          newParticles.push(createParticle(player.x, player.y, '#a3e635'));
        }
        if (entity.config.special === 'SHOCK' && !player.traits.includes('SHOCK_RESIST')) {
          player.health -= 5;
        }

        player.health = Math.min(player.maxHealth, player.health + entity.config.health * 0.2);
        for(let i=0; i<5; i++) newParticles.push(createParticle(entity.x, entity.y, entity.config.color));
