      x,
      y,
      radius,
      type
    });
  }
  return obstacles;
};

export const createParticle = (x: number, y: number, color: string): Particle => ({
  id: uuid(),
  x,
  y,
  vx: (Math.random() - 0.5) * 4,
  vy: (Math.random() - 0.5) * 4,
  life: 1.0,
  maxLife: 1.0,
  color,
  size: Math.random() * 3 + 2
});

// Helper: Check if entity is inside an obstacle
const checkHiding = (entity: Entity, obstacles: Obstacle[]) => {
  entity.isHidden = false;
  for (const obs of obstacles) {
    const d = dist(entity, obs);
    if (d < obs.radius - entity.radius * 0.5) {
       if (entity.radius < obs.radius * 0.7) {
         entity.isHidden = true;
         return; // Found a hiding spot
       }
    }
  }
};

// AI Behavior Logic (Smart Survival)
const updateAI = (entity: Entity, player: PlayerState, entities: Entity[], worldW: number, worldH: number) => {
  // Plankton drifts
  if (entity.type === CreatureType.PLANKTON) {
    entity.x += entity.vx * 0.5;
    entity.y += entity.vy * 0.5;
    // Wrap around
    if (entity.x < 0) entity.x = worldW;
    if (entity.x > worldW) entity.x = 0;
    if (entity.y < 0) entity.y = worldH;
    if (entity.y > worldH) entity.y = 0;
    return;
  }

  // Forces
  let fx = 0;
  let fy = 0;

  const detectionRange = 350 * (entity.config.tier >= 3 ? 1.5 : 1); 
  const viewX = entity.x + Math.cos(entity.angle) * detectionRange * 0.5; // Offset view forward
  const viewY = entity.y + Math.sin(entity.angle) * detectionRange * 0.5;

  let fearFactor = 0;
  let hungerFactor = 0;
  let nearestFoodDist = Infinity;
  let nearestFood: {x: number, y: number} | null = null;

  // 1. Analyze Neighbors (Player + Entities)
  const neighbors = [...entities, player]; // Include player in scan

  // Optimization: Scan a subset or just limit reaction count? 
  // For 800 entities, we need to be careful. But standard loop is usually fine for < 1000 in JS V8.

  for (const other of neighbors) {
    if (other.id === entity.id || other.isHidden) continue;

    // Quick dist check
    const dx = other.x - entity.x;
    const dy = other.y - entity.y;
    const dSq = dx*dx + dy*dy;

    if (dSq > detectionRange * detectionRange) continue;

    const d = Math.sqrt(dSq);
    const dirX = dx / d;
    const dirY = dy / d;

    const isThreat = other.radius > entity.radius * 1.1; // Bigger things are threats
    const isFood = entity.radius >= other.radius * 1.1; // Smaller things are food

    // Special case: Player God Mode is always a threat
    const realThreat = isThreat || (other.id === 'player' && (other as PlayerState).isGodMode);

    if (realThreat) {
       // FLEE: Push away strongly based on proximity
       const weight = 2000 / (d + 1);
       fx -= dirX * weight;
       fy -= dirY * weight;
       fearFactor += weight;
    } else if (isFood) {
       // CHASE: Pull towards food, but only if not terrified
       // Only chase if matching behavior preference
       const aggressive = entity.config.behavior === 'AGGRESSIVE' || entity.config.behavior === 'BOSS';
       const planktonEater = entity.config.behavior === 'PASSIVE' || entity.config.behavior === 'FLEE';

       let wantsIt = false;
       if (aggressive) wantsIt = true;
       if (planktonEater && other.type === CreatureType.PLANKTON) wantsIt = true;

       if (wantsIt) {
         if (d < nearestFoodDist) {
           nearestFoodDist = d;
           nearestFood = other;
         }
       }
    }
  }

  // 2. Apply Hunger (Vector towards nearest food)
  // Fear overrides hunger. If fearFactor is high, ignore food.
  if (nearestFood && fearFactor < 5) {
     const dx = nearestFood.x - entity.x;
     const dy = nearestFood.y - entity.y;
     const d = Math.hypot(dx, dy);
     fx += (dx / d) * 1.5; // Hunger pull
     fy += (dy / d) * 1.5;
     hungerFactor = 1;
  }

  // 3. Wander / Momentum (Keep moving forward)
  fx += Math.cos(entity.angle) * 0.5;
  fy += Math.sin(entity.angle) * 0.5;

  // 4. Boundary Avoidance (Strong Push)
  const margin = 150;
  if (entity.x < margin) fx += 2;
  if (entity.x > worldW - margin) fx -= 2;
  if (entity.y < margin) fy += 2;
  if (entity.y > worldH - margin) fy -= 2;

  // Apply Forces to Angle
  // Calculate target angle based on net force
  if (Math.abs(fx) > 0.1 || Math.abs(fy) > 0.1) {
    const targetAngle = Math.atan2(fy, fx);
    let angleDiff = targetAngle - entity.angle;
    while (angleDiff > Math.PI) angleDiff -= Math.PI * 2;
    while (angleDiff < -Math.PI) angleDiff += Math.PI * 2;

    // Turn speed depends on size (bigger = slower turn)
    const turnSpeed = 0.1 / (entity.radius * 0.05); 
    entity.angle += angleDiff * Math.min(0.2, turnSpeed);
  }

  // Move
  const finalSpeed = entity.speed * (fearFactor > 1 ? 1.5 : 1.0); // Sprint if scared
  entity.vx = Math.cos(entity.angle) * finalSpeed;
  entity.vy = Math.sin(entity.angle) * finalSpeed;

  entity.x += entity.vx;
  entity.y += entity.vy;

  // Update Render Scale Decay
  if (entity.renderScale > 1.0) {
     entity.renderScale += (1.0 - entity.renderScale) * 0.1;
  }
};

// Spawning Logic
const spawnEntities = (state: GameState) => {
  if (state.entities.length >= MAX_ENTITIES) return;

  // --- POPULATION CONTROL ---
  const smallCreaturesCount = state.entities.filter(e => 
    e.type === CreatureType.PLANKTON || e.type === CreatureType.ALGAE_FISH
  ).length;

  let type: CreatureType = CreatureType.PLANKTON;

  if (smallCreaturesCount < 400) { 
    type = Math.random() < 0.7 ? CreatureType.PLANKTON : CreatureType.ALGAE_FISH;
  } else {
    const r = Math.random();
    const tier1Prob = state.player.level === 1 ? 0.7 : state.player.level === 2 ? 0.3 : 0.1;
    const tier2Prob = state.player.level === 1 ? 0.25 : state.player.level === 2 ? 0.5 : 0.3;

    if (r < tier1Prob) {
      const subR = Math.random();
      type = subR < 0.6 ? CreatureType.PLANKTON : subR < 0.8 ? CreatureType.ALGAE_FISH : CreatureType.JELLYFISH;
    } else if (r < tier1Prob + tier2Prob) {
      const subR = Math.random();
      type = subR < 0.2 ? CreatureType.WORKER : subR < 0.5 ? CreatureType.NEEDLE_FISH : subR < 0.8 ? CreatureType.ARMOR_FISH : CreatureType.POISON_FISH;
    } else {
      const subR = Math.random();
      if (state.player.level >= 4 && Math.random() < 0.05) {
        type = Math.random() > 0.5 ? CreatureType.LEVIATHAN : CreatureType.MUTANT;
      } else {
        type = subR < 0.3 ? CreatureType.GHOST : subR < 0.6 ? CreatureType.SWORD_FISH : subR < 0.8 ? CreatureType.EEL : CreatureType.MEGA_MOUTH;
      }
    }
  }

  let sx, sy;
  do {
    sx = Math.random() * WORLD_SIZE;
    sy = Math.random() * WORLD_SIZE;
  } while (dist({x: sx, y: sy}, state.player) < 800); 

  state.entities.push(createEntity(type, sx, sy));
};

export const updateGame = (state: GameState, mouse: {x: number, y: number}, boostActive: boolean, screenW: number, screenH: number): GameState => {
  if (state.status !== GameStatus.PLAYING) return state;

  state.time += 1; // Increment global tick
  const { player, obstacles } = state;
  const newParticles: Particle[] = [];

  // --- Pre-Evolution Invincibility Logic ---
  const nextLevelXp = LEVEL_THRESHOLDS[player.level] || 999999;
  // If player is 90% way to next level, they become invincible
  if (player.xp >= nextLevelXp * 0.9 && player.level < LEVEL_THRESHOLDS.length) {
    player.isInvulnerable = true;
  } else {
    player.isInvulnerable = false;
  }

  // --- Player Boost Logic ---
  let speedMult = player.stats.speedMult;

  if (!boostActive && player.boost.current < player.boost.max) {
    player.boost.current = Math.min(player.boost.max, player.boost.current + BOOST_CONFIG.REGEN_RATE);
  }

  if (boostActive && player.boost.current > 0) {
    player.boost.current = Math.max(0, player.boost.current - BOOST_CONFIG.DRAIN_RATE);
    speedMult *= BOOST_CONFIG.SPEED_MULTIPLIER;
    if (state.time % 5 === 0) {
       const bx = player.x - Math.cos(player.angle) * player.radius;
       const by = player.y - Math.sin(player.angle) * player.radius;
       newParticles.push(createParticle(bx, by, 'rgba(255, 255, 255, 0.5)'));
    }
  }

  // --- Player Movement ---
  const screenCenterX = screenW / 2;
  const screenCenterY = screenH / 2;

  const dx = mouse.x - screenCenterX;
  const dy = mouse.y - screenCenterY;

  const targetAngle = Math.atan2(dy, dx);

  let angleDiff = targetAngle - player.angle;
  while (angleDiff > Math.PI) angleDiff -= Math.PI * 2;
  while (angleDiff < -Math.PI) angleDiff += Math.PI * 2;

  const turnSpeed = 0.15 / player.stats.sizeMult; 
  player.angle += angleDiff * turnSpeed;

  const currentSpeed = player.speed * speedMult;
  player.vx = Math.cos(player.angle) * currentSpeed;
  player.vy = Math.sin(player.angle) * currentSpeed;

  player.x = Math.max(player.radius, Math.min(WORLD_SIZE - player.radius, player.x + player.vx));
  player.y = Math.max(player.radius, Math.min(WORLD_SIZE - player.radius, player.y + player.vy));

  // Player render scale decay
  if (player.renderScale > 1.0) {
    player.renderScale += (1.0 - player.renderScale) * 0.1;
  }

  // --- Hiding Status Check ---
  checkHiding(player, obstacles);
  state.entities.forEach(e => checkHiding(e, obstacles));

  // --- Player Mouth Animation ---
  let nearestEdible = Infinity;
  for (const e of state.entities) {
    if (e.isHidden) continue; 
    const d = dist(player, e);
    if (player.isGodMode || player.radius >= e.radius * 1.1) {
      if (d < nearestEdible) nearestEdible = d;
    }
  }

  if (nearestEdible < player.radius + 150) {
     player.mouthOpenValue = 0.5 + 0.5 * Math.sin(state.time * 0.6);
  } else {
     player.mouthOpenValue = Math.max(0, player.mouthOpenValue - 0.1);
  }

  // --- Entities Update & Inter-Entity Predation ---
  const deadEntityIds = new Set<string>();

  // 1. Movement AI
  state.entities.forEach(entity => {
    updateAI(entity, player, state.entities, WORLD_SIZE, WORLD_SIZE);
  });

  // 2. Entity vs Entity Interactions
  for (let i = 0; i < state.entities.length; i++) {
    const predator = state.entities[i];
    if (deadEntityIds.has(predator.id)) continue;
    if (predator.isHidden) continue;

    for (let j = 0; j < state.entities.length; j++) {
      if (i === j) continue;
      const prey = state.entities[j];
      if (deadEntityIds.has(prey.id)) continue;
      if (prey.isHidden) continue;

      const d = dist(predator, prey);

      // Eating Logic
      if (d < predator.radius + prey.radius * 0.5) { 
          const canEat = predator.radius >= prey.radius * 1.1; 

          if (canEat) {
             const isAggressive = predator.config.behavior === 'AGGRESSIVE' || predator.config.behavior === 'BOSS';
             const isPlankton = prey.type === CreatureType.PLANKTON;
             if (!isAggressive && !isPlankton) continue;

             deadEntityIds.add(prey.id);
             predator.health = Math.min(predator.maxHealth, predator.health + prey.config.health * 0.5);
