      const canEat = player.isGodMode || player.radius >= entity.radius * 1.1; 
      const isDangerous = !player.isGodMode && (entity.config.behavior === 'AGGRESSIVE' || entity.config.behavior === 'BOSS' || entity.config.special === 'SPIKE');

      if (canEat) {
