          player.y -= player.vy * 2;

          let dmg = entity.config.damage > 0 ? entity.config.damage : 5;
          dmg = Math.max(1, dmg / player.stats.defenseMult);

          // God/Invulnerable Mode Check
          if (!player.isGodMode && !player.isInvulnerable) {
