export const createEntity = (type: CreatureType, x: number, y: number): Entity => {
  const config = CREATURES[type];
  return {
    id: uuid(),
    type,
    x,
    y,
    vx: (Math.random() - 0.5) * config.speed,
    vy: (Math.random() - 0.5) * config.speed,
    radius: config.baseRadius,
    angle: Math.random() * Math.PI * 2,
    health: config.health,
    maxHealth: config.health,
    speed: config.speed,
    config,
    mouthOpenValue: 0,
    isHidden: false,
    animOffset: Math.random() * 100, // Randomize animation phase
    renderScale: 1.0,
    isInvulnerable: false,
    aggroTimer: 0
  };
};

export const createObstacles = (): Obstacle[] => {
  const obstacles: Obstacle[] = [];
  for (let i = 0; i < MAX_OBSTACLES; i++) {
    const type = Math.random() > 0.5 ? 'ROCK' : 'CORAL';
    const radius = 50 + Math.random() * 200; // Size 50 to 250
    // Keep obstacles away from center spawn initially to avoid trapping player immediately
    let x, y;
    do {
      x = Math.random() * WORLD_SIZE;
      y = Math.random() * WORLD_SIZE;
    } while (dist({x, y}, {x: WORLD_SIZE/2, y: WORLD_SIZE/2}) < 500);

    obstacles.push({
      id: uuid(),
      x,
      y,
      radius,
      type
    });
  }
  return obstacles;
};

export const createParticle = (x: number, y: number, color: string): Particle => ({
  id: uuid(),
  x,
  y,
  vx: (Math.random() - 0.5) * 4,
  vy: (Math.random() - 0.5) * 4,
  life: 1.0,
  maxLife: 1.0,
  color,
  size: Math.random() * 3 + 2
});

// Helper: Check if entity is inside an obstacle
const checkHiding = (entity: Entity, obstacles: Obstacle[]) => {
  entity.isHidden = false;
  for (const obs of obstacles) {
    const d = dist(entity, obs);
    if (d < obs.radius - entity.radius * 0.5) {
       if (entity.radius < obs.radius * 0.7) {
         entity.isHidden = true;
         return; // Found a hiding spot
       }
    }
  }
};

// AI Behavior Logic (Smart Survival)
const updateAI = (entity: Entity, player: PlayerState, entities: Entity[], worldW: number, worldH: number) => {
  // Update aggro timer
  if (entity.aggroTimer && entity.aggroTimer > 0) {
    entity.aggroTimer--;
    if (entity.aggroTimer <= 0) {
      entity.targetId = null; // Lose interest
    }
  }

  // Plankton Optimization: Minimal logic
  if (entity.type === CreatureType.PLANKTON) {
    entity.x += entity.vx * 0.5;
    entity.y += entity.vy * 0.5;

    // Simple Boundary Wrap for Plankton
    if (entity.x < 0) entity.x = worldW;
    if (entity.x > worldW) entity.x = 0;
    if (entity.y < 0) entity.y = worldH;
    if (entity.y > worldH) entity.y = 0;
    return; // Stop here, save CPU
  }

  // Forces
  let fx = 0;
  let fy = 0;

  const detectionRange = 350 * (entity.config.tier >= 3 ? 1.5 : 1); 

  let fearFactor = 0;
  let hungerFactor = 0;
  let nearestFoodDist = Infinity;
  let nearestFood: {x: number, y: number} | null = null;

  const myTier = getEffectiveTier(entity);

  // AGGRO LOGIC: If I have a target (e.g., player bumped me), chase them regardless of normal behavior
  if (entity.targetId === 'player') {
    const dx = player.x - entity.x;
    const dy = player.y - entity.y;
    const d = Math.hypot(dx, dy);

    // Sprint towards target
    fx += (dx / d) * 3.5; 
    fy += (dy / d) * 3.5;
    hungerFactor = 3; // Aggro overrides mostly everything
  }

  // 1. Analyze Neighbors (Player + Entities)
  const neighbors = [...entities, player]; // Include player in scan

  for (const other of neighbors) {
    if (other.id === entity.id) continue;
    if (other.isHidden) continue; 

    const dx = other.x - entity.x;
    const dy = other.y - entity.y;
    const dSq = dx*dx + dy*dy;

    if (dSq > detectionRange * detectionRange) continue;

    const d = Math.sqrt(dSq);
    const dirX = dx / d;
    const dirY = dy / d;

    const otherTier = getEffectiveTier(other as Entity | PlayerState);

    // Threat: Higher tier than me
    const isThreat = otherTier > myTier; 

    // Food: Lower tier than me (or Plankton)
    const isFood = (myTier > otherTier) || ((other as Entity).type === CreatureType.PLANKTON);

    const realThreat = isThreat || (other.id === 'player' && (other as PlayerState).isGodMode);

    if (realThreat) {
       // FLEE
       const weight = 2000 / (d + 1);
       fx -= dirX * weight;
       fy -= dirY * weight;

       const dot = (other.vx * -dx) + (other.vy * -dy);
       if (dot > 0) {
          fearFactor += weight * 5.0; 
       } else {
          fearFactor += weight;
       }

    } else if (isFood) {
       // CHASE
       const aggressive = entity.config.behavior === 'AGGRESSIVE' || entity.config.behavior === 'BOSS';
       const planktonEater = entity.config.behavior === 'PASSIVE' || entity.config.behavior === 'FLEE';

       let wantsIt = false;
       if (aggressive) wantsIt = true;
       // Passive/Flee types only eat plankton
       if (planktonEater && (other as Entity).type === CreatureType.PLANKTON) wantsIt = true;

       if (wantsIt) {
         if (d < nearestFoodDist) {
           nearestFoodDist = d;
           nearestFood = other;
         }
       }
    }
  }

  // 2. Apply Hunger
  if (nearestFood && fearFactor < 5 && !entity.targetId) {
     const dx = nearestFood.x - entity.x;
     const dy = nearestFood.y - entity.y;
     const d = Math.hypot(dx, dy);
     fx += (dx / d) * 1.5; // Hunger pull
     fy += (dy / d) * 1.5;
     hungerFactor = 1;
  }

  // 3. Wander
  fx += Math.cos(entity.angle) * 0.5;
  fy += Math.sin(entity.angle) * 0.5;

  // 4. Boundary Avoidance
  const margin = 150;
  if (entity.x < margin) fx += 2;
  if (entity.x > worldW - margin) fx -= 2;
  if (entity.y < margin) fy += 2;
  if (entity.y > worldH - margin) fy -= 2;

  // Apply Forces
  if (Math.abs(fx) > 0.1 || Math.abs(fy) > 0.1) {
    const targetAngle = Math.atan2(fy, fx);
    let angleDiff = targetAngle - entity.angle;
    while (angleDiff > Math.PI) angleDiff -= Math.PI * 2;
    while (angleDiff < -Math.PI) angleDiff += Math.PI * 2;

    let turnRate = 0.1 / (entity.radius * 0.05); 

    if (!entity.targetId && fearFactor < 1 && !nearestFood) {
       turnRate *= 0.3;
    }

    entity.angle += angleDiff * Math.min(0.2, turnRate);
  }

  // Move Speed
  let speedMult = 0.35; 

  if (entity.targetId) {
    speedMult = 1.6; // Chasing Fast!
  } else if (fearFactor > 50) {
    speedMult = 2.5; 
  } else if (fearFactor > 10) {
    speedMult = 1.8; 
  } else if (fearFactor > 1) {
    speedMult = 1.2; 
  } else if (nearestFood) {
    speedMult = 0.8; 
  }

  let finalSpeed = entity.speed * speedMult;

  entity.vx = Math.cos(entity.angle) * finalSpeed;
  entity.vy = Math.sin(entity.angle) * finalSpeed;

  entity.x += entity.vx;
  entity.y += entity.vy;

  if (entity.renderScale > 1.0) {
     entity.renderScale += (1.0 - entity.renderScale) * 0.1;
  }
};

// Spawning Logic
const spawnEntities = (state: GameState) => {
  if (state.entities.length >= MAX_ENTITIES) return;

  const planktonCount = state.entities.filter(e => e.type === CreatureType.PLANKTON).length;
  const smallFishCount = state.entities.filter(e => e.type === CreatureType.ALGAE_FISH).length;

  let type: CreatureType = CreatureType.PLANKTON;

  // Priority: Fill with small stuff first
  if (planktonCount < 150) { 
    type = CreatureType.PLANKTON;
  } else if (smallFishCount < 30) {
    type = CreatureType.ALGAE_FISH;
  } else {
    // Reduce Big Fish Probability significantly
    const r = Math.random();

    if (r < 0.6) {
      type = Math.random() < 0.7 ? CreatureType.PLANKTON : CreatureType.ALGAE_FISH;
    } else if (r < 0.9) {
      // Tier 1/2
      type = Math.random() < 0.5 ? CreatureType.JELLYFISH : CreatureType.WORKER;
    } else if (r < 0.98) {
      // Tier 2 Rare
      type = Math.random() < 0.5 ? CreatureType.NEEDLE_FISH : CreatureType.POISON_FISH;
    } else {
      // Tier 3 Very Rare
      const subR = Math.random();
      type = subR < 0.3 ? CreatureType.SWORD_FISH : subR < 0.6 ? CreatureType.EEL : CreatureType.MEGA_MOUTH;
    }
  }

  let sx, sy;
  if (type === CreatureType.PLANKTON) {
    sx = Math.random() * WORLD_SIZE;
    sy = Math.random() * WORLD_SIZE;
  } else {
    do {
      sx = Math.random() * WORLD_SIZE;
      sy = Math.random() * WORLD_SIZE;
    } while (dist({x: sx, y: sy}, state.player) < 800); 
  }

  state.entities.push(createEntity(type, sx, sy));
};

export const updateGame = (state: GameState, mouse: {x: number, y: number}, boostActive: boolean, screenW: number, screenH: number): GameState => {
  if (state.status !== GameStatus.PLAYING) return state;

  state.time += 1;
  const { player, obstacles } = state;
  const newParticles: Particle[] = [];

  const nextLevelXp = LEVEL_THRESHOLDS[player.level] || 9999999;

  if (player.xp >= nextLevelXp * 0.9 && player.level < LEVEL_THRESHOLDS.length) {
    player.isInvulnerable = true;
  } else {
    player.isInvulnerable = false;
  }

  // --- Player Boost Logic ---
  let speedMult = player.stats.speedMult;
  if (!boostActive && player.boost.current < player.boost.max) {
    player.boost.current = Math.min(player.boost.max, player.boost.current + BOOST_CONFIG.REGEN_RATE);
  }
  if (boostActive && player.boost.current > 0) {
    player.boost.current = Math.max(0, player.boost.current - BOOST_CONFIG.DRAIN_RATE);
    speedMult *= BOOST_CONFIG.SPEED_MULTIPLIER;
    if (state.time % 5 === 0) {
       const bx = player.x - Math.cos(player.angle) * player.radius;
       const by = player.y - Math.sin(player.angle) * player.radius;
       newParticles.push(createParticle(bx, by, 'rgba(255, 255, 255, 0.5)'));
    }
  }

  // --- Player Movement ---
  const screenCenterX = screenW / 2;
  const screenCenterY = screenH / 2;
  const dx = mouse.x - screenCenterX;
  const dy = mouse.y - screenCenterY;
  const targetAngle = Math.atan2(dy, dx);
  let angleDiff = targetAngle - player.angle;
  while (angleDiff > Math.PI) angleDiff -= Math.PI * 2;
  while (angleDiff < -Math.PI) angleDiff += Math.PI * 2;

  const turnSpeed = 0.15 / player.stats.sizeMult; 
  player.angle += angleDiff * turnSpeed;

  const currentSpeed = player.speed * speedMult;
  player.vx = Math.cos(player.angle) * currentSpeed;
  player.vy = Math.sin(player.angle) * currentSpeed;

  player.x = Math.max(player.radius, Math.min(WORLD_SIZE - player.radius, player.x + player.vx));
  player.y = Math.max(player.radius, Math.min(WORLD_SIZE - player.radius, player.y + player.vy));

  if (player.renderScale > 1.0) {
    player.renderScale += (1.0 - player.renderScale) * 0.1;
  }

