    if (e.isHidden && !isPlankton) continue; 
    const d = dist(player, e);
    const eTier = getEffectiveTier(e);
    // Visual logic: Mouth opens if we can eat it (Tier >= or Plankton)
    const canEat = (playerTier >= eTier || isPlankton) && player.radius >= e.radius;

    if (canEat) {
      if (d < nearestEdible) nearestEdible = d;
    }
  }

  if (nearestEdible < player.radius + 150) {
