  for (let i = 0; i < state.entities.length; i++) {
    const predator = state.entities[i];
    if (predator.type === CreatureType.PLANKTON) continue;
    if (deadEntityIds.has(predator.id)) continue;
    if (predator.isHidden) continue;

    const predTier = getEffectiveTier(predator);

    for (let j = 0; j < state.entities.length; j++) {
      if (i === j) continue;
      const prey = state.entities[j];
      if (deadEntityIds.has(prey.id)) continue;

      const isPlankton = prey.type === CreatureType.PLANKTON;
      if (prey.isHidden && !isPlankton) continue;

      const d = dist(predator, prey);
      const preyTier = getEffectiveTier(prey);

      if (d < predator.radius + prey.radius * 0.5) { 
          const canEat = (predTier > preyTier) || isPlankton;
          const sizeCheck = predator.radius >= prey.radius * 1.1;

          if (canEat && sizeCheck) {
             const isAggressive = predator.config.behavior === 'AGGRESSIVE' || predator.config.behavior === 'BOSS';
             if (!isAggressive && !isPlankton) continue;

             deadEntityIds.add(prey.id);
             predator.health = Math.min(predator.maxHealth, predator.health + prey.config.health * 0.5);
             predator.renderScale = 1.4; 
             for(let k=0; k<3; k++) newParticles.push(createParticle(prey.x, prey.y, prey.config.color));
          }
      }
    }
  }

  // --- Player Collision & Eating ---
  const entitiesKeep: Entity[] = [];

  for (const entity of state.entities) {
