      // 2. Must be physically larger (Radius check), relaxed to >=
      const canEat = (playerTier >= entityTier || isPlankton) && (player.radius >= entity.radius || player.isGodMode);

      const isDangerous = entityTier > playerTier && !player.isGodMode;

      if (canEat) {
