        }
        entitiesKeep.push(entity);
      }
    } else {
      entitiesKeep.push(entity);
    }
  }
  state.entities = entitiesKeep;

  // --- Automatic Evolution & Level Up ---
  if (player.xp >= nextLevelXp) {
    player.level++;

    // Check Evolution
    const nextType = getNextEvolution(player.type, player.eatenHistory, player.level);

    if (nextType !== player.type) {
        // EVOLVE!
        player.type = nextType;
        const newConfig = CREATURES[nextType];
        player.config = newConfig;

        // Stats Boost
        player.maxHealth += 80; // More health on evolution
        player.health = player.maxHealth;
        player.radius = newConfig.baseRadius * player.stats.sizeMult;
        player.speed = newConfig.speed * 1.2 * player.stats.speedMult; // Keep player faster

        // Visual Explosion
        for(let i=0; i<20; i++) {
             newParticles.push(createParticle(player.x, player.y, '#fbbf24'));
        }
        player.renderScale = 2.0;
    } else {
        // Standard Level Up (Growth)
