        player.health = player.maxHealth;

        // Add visual effect for standard level ups ("Upgrade Transformation" feel)
        player.renderScale = 1.5; 
        for(let i=0; i<10; i++) {
             newParticles.push(createParticle(player.x, player.y, '#fcd34d'));
        }
    }

    player.isInvulnerable = true; 
    setTimeout(() => { player.isInvulnerable = false; }, 3000); // 3s safety after level up
  }

  // --- Particle Update ---
  state.particles = state.particles.map(p => ({
    ...p,
    x: p.x + p.vx,
    y: p.y + p.vy,
    life: p.life - 0.05
  })).filter(p => p.life > 0).concat(newParticles);

  // --- Spawning ---
  spawnEntities(state);

  // --- Game Over Check ---
  if (player.health <= 0) {
    state.status = GameStatus.GAME_OVER;
  }

  // --- Camera Update ---
  const targetZoom = Math.max(0.4, 1.5 - (player.level * 0.08) - (player.radius / 500));
  state.camera.zoom = state.camera.zoom + (targetZoom - state.camera.zoom) * 0.05;
  state.camera.x = player.x; 
  state.camera.y = player.y;

  return state;
