","cMarkNode":{}},"createdTimestamp":{"seconds":1768530058,"nanos":490000000},"doneTimestamp":{"seconds":1768530058,"nanos":541000000}},{"id":183,"author":"model","payload":{"type":"generationTable","entries":[{"path":"components/GameCanvas.tsx","generationType":1,"isDone":true,"description":"Update teeth to be more cartoonish (large, white, rounded). Add taunt visual support.","diffs":[{"target":"","replacement":"import React, { useRef, useEffect } from 'react';
import { GameState, Entity, Particle, CreatureType, Obstacle, PlayerState } from '../types';
import { WORLD_SIZE } from '../constants';

interface GameCanvasProps {
  gameState: GameState;
  onMouseMove: (x: number, y: number) => void;
  onMouseDown: () => void;
  onMouseUp: () => void;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ gameState, onMouseMove, onMouseDown, onMouseUp }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // --- CUTE & FUNNY FISH DRAWING ---

  const drawCuteFish = (ctx: CanvasRenderingContext2D, entity: Entity, time: number, isPlayer: boolean) => {
    const { type, radius, animOffset, mouthOpenValue, renderScale, isInvulnerable } = entity;

    // Safety check for scale to prevent crashes
    const safeScale = Number.isFinite(renderScale) ? renderScale : 1;

    ctx.save();
    ctx.translate(entity.x, entity.y);

    // Scale Effect (Eating Pop)
    ctx.scale(safeScale, safeScale);

    // Rotation
    ctx.rotate(entity.angle);

    // Invulnerability Aura
    if (isInvulnerable || (isPlayer && (entity as PlayerState).isGodMode)) {
      ctx.save();
      ctx.rotate(time * 0.1);
      ctx.beginPath();
      ctx.strokeStyle = `hsl(${(time * 5) % 360}, 100%, 70%)`;
      ctx.lineWidth = 4;
      ctx.setLineDash([10, 10]);
      ctx.arc(0, 0, radius * 1.5, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
    }

    // Ghost Effect
    if (entity.isHidden) ctx.globalAlpha = 0.5;

    // Body Animation (Wobble)
    const wobble = Math.sin(time * 0.3 + animOffset) * 0.05;
    const bodyStretch = 1 + wobble;

    // --- DRAW FINS (Flappy) ---
    if (type !== CreatureType.PLANKTON && type !== CreatureType.JELLYFISH) {
      const finFlap = Math.sin(time * 0.8 + animOffset) * 0.4;
      ctx.fillStyle = entity.config.color;
      ctx.strokeStyle = 'rgba(0,0,0,0.2)';
      ctx.lineWidth = 2;

      // Right Fin
      ctx.save();
      ctx.translate(radius * 0.3, radius * 0.6);
      ctx.rotate(Math.PI / 3 + finFlap);
      ctx.beginPath();
      ctx.ellipse(0, 0, radius * 0.4, radius * 0.2, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
      ctx.restore();

      // Left Fin
      ctx.save();
      ctx.translate(radius * 0.3, -radius * 0.6);
      ctx.rotate(-Math.PI / 3 - finFlap);
      ctx.beginPath();
      ctx.ellipse(0, 0, radius * 0.4, radius * 0.2, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
      ctx.restore();
    }

    // --- DRAW BODY ---
    ctx.lineWidth = 3; // Thicker cartoon lines
    ctx.strokeStyle = 'rgba(0,0,0,0.2)'; // Darker outline for cartoon style

    ctx.fillStyle = entity.config.color;

    if (type === CreatureType.JELLYFISH) {
       // Jellyfish Dome
       ctx.beginPath();
       ctx.arc(0, 0, radius, Math.PI, 0); 
       ctx.lineTo(radius, radius * 0.5);
       ctx.lineTo(-radius, radius * 0.5);
       ctx.fill();
       ctx.stroke();
       // Tentacles
       ctx.strokeStyle = entity.config.color;
       for(let i=-2; i<=2; i++) {
         ctx.beginPath();
         ctx.moveTo(i * radius * 0.3, radius * 0.5);
         const sway = Math.sin(time * 0.2 + i + animOffset) * radius;
         ctx.quadraticCurveTo(i * radius * 0.3 + sway, radius * 1.5, i * radius * 0.1, radius * 2.5);
         ctx.stroke();
       }
    } else if (type === CreatureType.PLANKTON) {
       // Just a cute dot
       ctx.beginPath();
       ctx.arc(0, 0, radius, 0, Math.PI * 2);
       ctx.fill();
    } else {
       // Standard "Derpy Fish" Body
       ctx.beginPath();
       // Teardrop shape but rounder
       ctx.ellipse(0, 0, radius * bodyStretch, radius * 0.85, 0, 0, Math.PI * 2);
       ctx.fill();
       ctx.stroke(); 

       // Tail
       const tailWag = Math.sin(time * 0.4 + animOffset) * 0.3;
       ctx.save();
       ctx.translate(-radius, 0);
       ctx.rotate(tailWag);
       ctx.beginPath();
       ctx.moveTo(0, 0);
       ctx.lineTo(-radius * 0.6, -radius * 0.5);
       ctx.lineTo(-radius * 0.6, radius * 0.5);
       ctx.closePath();
       ctx.fill();
       ctx.stroke();
       ctx.restore();
    }

    // --- GOOGLY EYES (Asymmetric for cartoon look) ---
    if (type !== CreatureType.PLANKTON && type !== CreatureType.JELLYFISH) {
      const eyeSizeBase = radius * 0.35;
      const eyeX = radius * 0.3;
      const eyeYOffset = radius * 0.35;

      // Asymmetric sizes (one big, one small)
      const leftEyeSize = eyeSizeBase * 1.1;
      const rightEyeSize = eyeSizeBase * 0.8;

      ctx.lineWidth = 1;
      ctx.strokeStyle = 'black';

      // Left Eye (Top)
      ctx.fillStyle = 'white';
      ctx.beginPath();
      ctx.arc(eyeX, -eyeYOffset, leftEyeSize, 0, Math.PI * 2); 
      ctx.fill();
      ctx.stroke();

      // Right Eye (Bottom)
      ctx.beginPath();
      ctx.arc(eyeX, eyeYOffset, rightEyeSize, 0, Math.PI * 2); 
      ctx.fill();
      ctx.stroke();

      // Pupils (Independent wobble)
      const lookX = Math.cos(time * 0.1 + animOffset) * leftEyeSize * 0.2;
      const lookY = Math.sin(time * 0.2 + animOffset) * leftEyeSize * 0.2;

      ctx.fillStyle = 'black';

      // Left Pupil
      ctx.beginPath();
      ctx.arc(eyeX + lookX, -eyeYOffset + lookY, leftEyeSize * 0.3, 0, Math.PI * 2);
      ctx.fill();

      // Right Pupil (Cross-eyed offset)
      ctx.beginPath();
      ctx.arc(eyeX - lookY, eyeYOffset + lookX, rightEyeSize * 0.3, 0, Math.PI * 2);
      ctx.fill();
    }

    // --- MOUTH & TEETH (CARTOON STYLE) ---
    if (type !== CreatureType.PLANKTON) {
       ctx.save();
       ctx.translate(radius * 0.6, 0); // Front of face

       // Mouth Breathing
       const breath = 0.4 + 0.1 * Math.sin(time * 0.2 + animOffset);
       const effectiveOpen = Math.max(breath, mouthOpenValue);

       const openW = radius * 0.5; 
       const openH = effectiveOpen * radius * 0.8;

       // Mouth Void
       ctx.fillStyle = '#450a0a'; // Dark Red
       ctx.beginPath();
       ctx.ellipse(0, 0, openW, openH, 0, 0, Math.PI * 2);
       ctx.fill();
       ctx.lineWidth = 2;
       ctx.strokeStyle = 'rgba(0,0,0,0.5)';
       ctx.stroke();

       // --- CARTOON TEETH ---
       // Big, white, rounded triangles. slightly irregular.

       const toothColor = '#ffffff';
       const toothStroke = '#000000';
       ctx.fillStyle = toothColor;
       ctx.strokeStyle = toothStroke;
       ctx.lineWidth = 2;
       ctx.lineJoin = 'round'; // ROUND JOINS for cartoon feel

       // Seed for deterministic irregularity
       const seed = Math.floor(animOffset * 100);
       const rnd = (i: number) => {
         const x = Math.sin(seed + i * 132.1);
         return x * x; // 0..1
       };

       const drawTeethRow = (isTop: boolean) => {
          const numTeeth = 3; // Fewer, bigger teeth
          const rowY = isTop ? -openH : openH;
          const dir = isTop ? 1 : -1;
          const totalW = openW * 1.6;
          const startX = -totalW / 2 + openW * 0.2;
          const step = totalW / numTeeth;

          ctx.beginPath();
          for(let i=0; i<numTeeth; i++) {
             const tX = startX + i * step;
             const tH = (openH * 0.6) + (openH * 0.6 * rnd(i + (isTop?0:10))); // Random height

             // Base points
             const x1 = tX;
             const x2 = tX + step;
             const yBase = rowY;
             // Tip point
             const tipX = tX + step * 0.5;
             const tipY = rowY + (tH * dir);

             ctx.moveTo(x1, yBase);
             // Curved tooth
             ctx.quadraticCurveTo(tipX, tipY * 1.2, x2, yBase); 
          }
          ctx.fill();
          ctx.stroke();
       };

       drawTeethRow(true); // Top
       drawTeethRow(false); // Bottom

       ctx.restore();
    }

    // --- AGGRO / TAUNT INDICATOR ---
    if (entity.aggroTimer && entity.aggroTimer > 0 && !isPlayer) {
      // Angry symbol
      ctx.save();
      ctx.translate(0, -radius * 1.5);
      ctx.fillStyle = '#ef4444';
      ctx.font = "bold 24px sans-serif";
      ctx.fillText("💢", 0, 0);
      ctx.restore();
    }

    // --- SPECIAL MARKINGS ---
    if (type === CreatureType.WORKER) {
      // Tie
      ctx.fillStyle = "red";
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.lineTo(radius * 0.2, radius * 0.1);
      ctx.lineTo(radius * 0.2, -radius * 0.1);
      ctx.fill();
    }

    ctx.restore();
  };

  const drawObstacle = (ctx: CanvasRenderingContext2D, obs: Obstacle) => {
    ctx.save();
    ctx.translate(obs.x, obs.y);

    // Cartoon Rock/Coral
    ctx.lineWidth = 3;
    ctx.strokeStyle = 'rgba(0,0,0,0.3)';

    if (obs.type === 'ROCK') {
      ctx.fillStyle = '#64748b';
      ctx.beginPath();
      ctx.arc(0, 0, obs.radius, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      // Highlights
      ctx.fillStyle = '#94a3b8';
      ctx.beginPath();
      ctx.arc(-obs.radius*0.3, -obs.radius*0.3, obs.radius*0.2, 0, Math.PI*2);
      ctx.fill();
    } else if (obs.type === 'CORAL') {
      ctx.fillStyle = '#db2777';
      ctx.beginPath();
      const spikes = 8;
      for (let i = 0; i < spikes * 2; i++) {
         const r = obs.radius + (i % 2 === 0 ? 0 : 20);
         const a = (Math.PI * 2 * i) / (spikes * 2);
         ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
      }
      ctx.closePath();
      ctx.fill();
      ctx.stroke();

      ctx.fillStyle = '#fce7f3';
      ctx.beginPath(); ctx.arc(0,0, obs.radius*0.3, 0, Math.PI*2); ctx.fill();
    }

    ctx.restore();
  };

  // ... (drawIndicators, drawGrid same as before but ensured cleanliness)

  const drawIndicators = (ctx: CanvasRenderingContext2D, entity: Entity, player: PlayerState) => {
    if (entity.isHidden || entity.id === player.id || entity.type === CreatureType.PLANKTON) return;

    const canEat = player.radius >= entity.radius * 1.1;
    const isDangerous = player.radius < entity.radius;

    if (canEat || player.isGodMode) {
      // Green Arrow
      ctx.save();
      ctx.translate(entity.x, entity.y - entity.radius - 25);
      ctx.fillStyle = '#4ade80'; 
      ctx.beginPath();
      ctx.moveTo(-6, -12);
      ctx.lineTo(6, -12);
      ctx.lineTo(0, 0); 
      ctx.fill();
      ctx.restore();
    } else if (isDangerous && !player.isGodMode && !player.isInvulnerable) {
      // Red Exclamation
      ctx.save();
      ctx.translate(entity.x, entity.y - entity.radius - 25);
      ctx.fillStyle = '#ef4444'; 
      ctx.font = "bold 20px sans-serif";
      ctx.textAlign = "center";
      ctx.fillText("!", 0, 0);
      ctx.restore();
    }
  };

  const drawGrid = (ctx: CanvasRenderingContext2D, camX: number, camY: number, width: number, height: number, zoom: number) => {
    const gridSize = 100;
    ctx.strokeStyle = '#ef4444';
    ctx.lineWidth = 5;
    ctx.strokeRect(0, 0, WORLD_SIZE, WORLD_SIZE);

    ctx.strokeStyle = '#1e293b'; 
    ctx.lineWidth = 1;

    const viewW = width / zoom;
    const viewH = height / zoom;
    const startX = Math.max(0, camX - viewW/2);
    const startY = Math.max(0, camY - viewH/2);
    const endX = Math.min(WORLD_SIZE, camX + viewW/2);
    const endY = Math.min(WORLD_SIZE, camY + viewH/2);

    const snapStartX = Math.floor(startX / gridSize) * gridSize;
    const snapStartY = Math.floor(startY / gridSize) * gridSize;

    ctx.beginPath();
    for (let x = snapStartX; x <= endX; x += gridSize) {
      ctx.moveTo(x, startY);
      ctx.lineTo(x, endY);
    }
    for (let y = snapStartY; y <= endY; y += gridSize) {
      ctx.moveTo(startX, y);
      ctx.lineTo(endX, y);
    }
    ctx.stroke();
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;

    const render = () => {
      if (canvas.width !== window.innerWidth || canvas.height !== window.innerHeight) {
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
      }

      const { width, height } = canvas;
      const { camera, player, entities, particles, obstacles, time } = gameState;

      // Background
      const gradient = ctx.createLinearGradient(0, 0, 0, height);
      gradient.addColorStop(0, '#0f172a'); 
      gradient.addColorStop(1, '#020617'); 
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, width, height);

      ctx.save();
      ctx.translate(width / 2, height / 2);
      ctx.scale(camera.zoom, camera.zoom);
      ctx.translate(-camera.x, -camera.y);

      drawGrid(ctx, camera.x, camera.y, width, height, camera.zoom);
      obstacles.forEach(o => drawObstacle(ctx, o));

      // Draw Entities
      const sortedEntities = [...entities].sort((a,b) => (a.isHidden ? -1 : 1));

      sortedEntities.forEach(e => {
        drawCuteFish(ctx, e, time, false);
        drawIndicators(ctx, e, player);
      });

      // Draw Player
      if (!player.isHidden) {
         drawCuteFish(ctx, player, time, true);
      } else {
         ctx.globalAlpha = 0.5;
         drawCuteFish(ctx, player, time, true);
         ctx.globalAlpha = 1.0;
      }

      // Particles
      particles.forEach(p => {
        ctx.globalAlpha = p.life;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fill();
        ctx.globalAlpha = 1.0;
      });

      // Name tags
      entities.forEach(e => {
        if (e.radius > 40 && !e.isHidden) {
          ctx.fillStyle = "rgba(255,255,255,0.7)";
          ctx.font = "10px sans-serif";
          ctx.textAlign = "center";
          const textScale = 1 / camera.zoom;
          ctx.save();
          ctx.translate(e.x, e.y - e.radius - 40);
          ctx.scale(textScale, textScale);
          ctx.fillText(e.config.name, 0, 0); 
          ctx.restore();
        }
      });

      ctx.restore();
      animationFrameId = requestAnimationFrame(render);
