const getEffectiveTier = (entity: Entity | PlayerState): number => {
  if ('level' in entity && (entity as PlayerState).id === 'player') {
    const p = entity as PlayerState;
    if (p.isGodMode) return 5;
    if (p.level < 2) return 1; 
