const getNextEvolution = (currentType: CreatureType, history: Record<CreatureType, number>, level: number): CreatureType => {
  if (level < 2) return currentType; 

  let aggressiveScore = (history[CreatureType.ALGAE_FISH] || 0) * 1 + 
                        (history[CreatureType.NEEDLE_FISH] || 0) * 2 + 
                        (history[CreatureType.SWORD_FISH] || 0) * 3;

  let passiveScore = (history[CreatureType.PLANKTON] || 0) * 0.1 + 
                     (history[CreatureType.WORKER] || 0) * 2;

  let weirdScore = (history[CreatureType.JELLYFISH] || 0) * 2 + 
                   (history[CreatureType.POISON_FISH] || 0) * 2 +
                   (history[CreatureType.EEL] || 0) * 3;

  if (level >= 2 && level < 5) {
    if (CREATURES[currentType].tier >= 2) return currentType; 
    if (weirdScore > aggressiveScore && weirdScore > passiveScore) return CreatureType.POISON_FISH;
    if (aggressiveScore > passiveScore) return CreatureType.NEEDLE_FISH;
    return CreatureType.WORKER; 
  }

  if (level >= 5 && level < 8) {
    if (CREATURES[currentType].tier >= 3) return currentType;
    if (currentType === CreatureType.NEEDLE_FISH || aggressiveScore > passiveScore * 2) return CreatureType.SWORD_FISH;
    if (currentType === CreatureType.POISON_FISH || weirdScore > passiveScore) return CreatureType.GHOST;
    return CreatureType.MEGA_MOUTH;
  }

  if (level >= 8) {
    if (CREATURES[currentType].tier >= 4) return currentType;
    if (currentType === CreatureType.SWORD_FISH || currentType === CreatureType.GHOST) return CreatureType.MUTANT;
    return CreatureType.LEVIATHAN;
  }

  return currentType;
};

