    const isFood = (myTier > otherTier) || ((other as Entity).type === CreatureType.PLANKTON);
    const realThreat = isThreat || (other.id === 'player' && (other as PlayerState).isGodMode);

    if (realThreat) {
       const weight = 2000 / (d + 1);
       fx -= dirX * weight;
       fy -= dirY * weight;
