    } else if (isFood) {
       const aggressive = entity.config.behavior === 'AGGRESSIVE' || entity.config.behavior === 'BOSS';
       const planktonEater = entity.config.behavior === 'PASSIVE' || entity.config.behavior === 'FLEE';
       let wantsIt = false;
       if (aggressive) wantsIt = true;
