const getNextEvolution = (currentType: CreatureType, history: Record<CreatureType, number>, level: number): CreatureType => {
  if (level < 2) return currentType; 
  let aggressiveScore = (history[CreatureType.ALGAE_FISH] || 0) * 1 + (history[CreatureType.NEEDLE_FISH] || 0) * 2;
  let weirdScore = (history[CreatureType.JELLYFISH] || 0) * 2 + (history[CreatureType.POISON_FISH] || 0) * 2;

  if (level >= 2 && level < 5) {
     if (CREATURES[currentType].tier >= 2) return currentType;
     if (weirdScore > aggressiveScore) return CreatureType.POISON_FISH;
     return CreatureType.NEEDLE_FISH;
  }
  if (level >= 5 && level < 8) {
    if (CREATURES[currentType].tier >= 3) return currentType;
    if (currentType === CreatureType.POISON_FISH || weirdScore > aggressiveScore) return CreatureType.EEL;
