const spawnHazards = (state: GameState) => {
  // Spawn birds if interval met
  if (state.time % BIRD_CONFIG.INTERVAL === 0) {
    for (let i = 0; i < BIRD_CONFIG.WAVE_COUNT; i++) {
      // Logic: Target player occasionally, or random crowded areas
      let tx, ty;

      const r = Math.random();
      if (r < 0.3) {
        // Target Player
        tx = state.player.x + (Math.random() - 0.5) * 200;
        ty = state.player.y + (Math.random() - 0.5) * 200;
      } else if (state.entities.length > 0) {
        // Target random entity
        const ent = state.entities[Math.floor(Math.random() * state.entities.length)];
        tx = ent.x;
        ty = ent.y;
      } else {
        tx = Math.random() * WORLD_SIZE;
        ty = Math.random() * WORLD_SIZE;
      }

      state.hazards.push({
        id: uuid(),
        x: tx,
        y: ty,
        radius: BIRD_CONFIG.RADIUS,
        type: 'BIRD_STRIKE',
        timer: BIRD_CONFIG.WARNING_TIME + Math.random() * 60, // Stagger slightly
        duration: BIRD_CONFIG.WARNING_TIME + BIRD_CONFIG.STRIKE_TIME,
        stage: 'WARNING'
      });
    }
  }
};

const updateHazards = (state: GameState, particles: Particle[]) => {
  const activeHazards: Hazard[] = [];
  const { player, entities } = state;

  state.hazards.forEach(hazard => {
    hazard.timer--;

    // Update Stage
    if (hazard.timer > BIRD_CONFIG.STRIKE_TIME) {
      hazard.stage = 'WARNING';
    } else if (hazard.timer > 0) {
      // Enter Strike Phase
      if (hazard.stage !== 'STRIKE') {
         hazard.stage = 'STRIKE';
         // Splash particles on strike start
         for(let i=0; i<10; i++) {
            particles.push(createParticle(hazard.x + (Math.random()-0.5)*hazard.radius, hazard.y + (Math.random()-0.5)*hazard.radius, 'white'));
         }
      }

      // --- KILL LOGIC ---
      // 1. Check Player
      if (player.radius < BIRD_CONFIG.SAFE_SIZE && !player.isGodMode && !player.isHidden) {
         if (dist(player, hazard) < hazard.radius) {
            // EATEN BY BIRD!
            player.health = 0;
            state.status = GameStatus.GAME_OVER;
         }
      }

      // 2. Check Entities
      for (const ent of entities) {
         if (ent.radius < BIRD_CONFIG.SAFE_SIZE && !ent.isHidden) {
             if (dist(ent, hazard) < hazard.radius) {
                 ent.health = 0; // Dead
                 // Feather/Splash particles
                 particles.push(createParticle(ent.x, ent.y, '#fca5a5')); 
             }
         }
      }

    } else {
      hazard.stage = 'COOLDOWN';
    }

    if (hazard.timer > -60) { // Keep alive briefly for fade out
      activeHazards.push(hazard);
    }
  });

  state.hazards = activeHazards;
};

const checkHiding = (entity: Entity, obstacles: Obstacle[]) => {
  entity.isHidden = false;
  for (const obs of obstacles) {
    const d = dist(entity, obs);
    const radiusFactor = obs.type === 'SEAWEED' ? 0.8 : 0.7;
    const coverageFactor = obs.type === 'SEAWEED' ? 0.7 : 0.5;

    if (d < obs.radius - entity.radius * coverageFactor) {
       if (entity.radius < obs.radius * radiusFactor) {
         entity.isHidden = true;
         return; 
       }
    }
  }
};

const updateAI = (entity: Entity, player: PlayerState, entities: Entity[], worldW: number, worldH: number) => {
  // Update timers
  if (entity.aggroTimer && entity.aggroTimer > 0) entity.aggroTimer--;
  if (entity.speedBoostTimer && entity.speedBoostTimer > 0) entity.speedBoostTimer--;

  if (entity.type === CreatureType.PLANKTON) {
    entity.x += Math.cos(entity.angle) * 0.5;
    entity.y += Math.sin(entity.angle) * 0.5;
    if (entity.x < 0) entity.x = worldW;
    if (entity.x > worldW) entity.x = 0;
    if (entity.y < 0) entity.y = worldH;
    if (entity.y > worldH) entity.y = 0;
    return; 
  }

  // --- AGILITY PENALTY ---
  // The larger the radius, the slower the turn speed
  const agility = Math.max(0.02, GAME_MECHANICS.BASE_TURN_SPEED - (entity.radius * 0.001));

  let fx = 0;
  let fy = 0;
  const detectionRange = 400 + (entity.radius * 2); 

  let fearFactor = 0;
  let hungerFactor = 0;
  let nearestFoodDist = Infinity;
  let nearestFood: {x: number, y: number} | null = null;

  // AI Target Logic
  if (entity.targetId === 'player') {
    if (player.isHidden) {
      entity.targetId = null;
    } else {
      const dx = player.x - entity.x;
      const dy = player.y - entity.y;
      const d = Math.hypot(dx, dy);
      fx += (dx / d) * 3.0; 
      fy += (dy / d) * 3.0;
      hungerFactor = 3; 
    }
  }

  const neighbors = [...entities, player]; 

  for (const other of neighbors) {
    if (other.id === entity.id) continue;
    if (other.isHidden) continue; 

    // Ignore things that are too small to eat (and are not Plankton which are always food)
    // Plankton radius is 6, MIN_RADIUS is 8. So Plankton is smaller, but Plankton type check handles it below.
    // This logic mainly prevents AI from targeting a "broken" small player or entity.
    if (other.type !== CreatureType.PLANKTON && other.radius <= GAME_MECHANICS.MIN_RADIUS_TO_SURVIVE) continue;

    const dx = other.x - entity.x;
    const dy = other.y - entity.y;
    const dSq = dx*dx + dy*dy;

    if (dSq > detectionRange * detectionRange) continue;

    const d = Math.sqrt(dSq);
    const dirX = dx / d;
    const dirY = dy / d;

    // RULE: Avoid things much bigger than you, OR avoid Bosses
    const isDangerous = other.radius > entity.radius * 1.5 || (other.type === CreatureType.LEVIATHAN && entity.type !== CreatureType.LEVIATHAN);

    // RULE: Eat things smaller than you, OR eat Plankton
    const isFood = (other.radius < entity.radius * 0.9) || ((other as Entity).type === CreatureType.PLANKTON);

    // RULE: Mobbing! If I'm small but aggressive, and target is distracted/taunting, attack even if big
    const isMobbing = entity.targetId === other.id;

    if (isDangerous && !isMobbing) {
       const weight = 2000 / (d + 1);
       fx -= dirX * weight;
       fy -= dirY * weight;
       fearFactor += weight;
    } else if (isFood || isMobbing) {
       const aggressive = entity.config.behavior === 'AGGRESSIVE' || entity.config.behavior === 'BOSS';
       const planktonEater = entity.config.behavior === 'PASSIVE' || entity.config.behavior === 'FLEE';
       let wantsIt = false;

       if (aggressive) wantsIt = true;
       if (planktonEater && (other as Entity).type === CreatureType.PLANKTON) wantsIt = true;
       // If starving (low health/size), desperate to eat
       if (entity.radius < entity.config.baseRadius * 0.8) wantsIt = true;

       if (wantsIt) {
         if (d < nearestFoodDist) {
           nearestFoodDist = d;
           nearestFood = other;
         }
       }
    }
  }

  if (nearestFood && fearFactor < 5 && !entity.targetId) {
     const dx = nearestFood.x - entity.x;
     const dy = nearestFood.y - entity.y;
     const d = Math.hypot(dx, dy);
     fx += (dx / d) * 1.5; 
     fy += (dy / d) * 1.5;
