  if (entity.x > worldW - margin) fx -= 2;
  if (entity.y < margin) fy += 2;
  if (entity.y > worldH - margin) fy -= 2;

  if (Math.abs(fx) > 0.1 || Math.abs(fy) > 0.1) {
    const targetAngle = Math.atan2(fy, fx);
    let angleDiff = targetAngle - entity.angle;
