      speedMult *= GAME_MECHANICS.SPEED_ITEM_MULTIPLIER;
  }

  const finalSpeed = entity.speed * speedMult;
  entity.vx = Math.cos(entity.angle) * finalSpeed;
  entity.vy = Math.sin(entity.angle) * finalSpeed;

  entity.x += entity.vx;
  entity.y += entity.vy;

  if (entity.renderScale > 1.0) {
