      const dy = player.y - entity.y;
      const d = Math.hypot(dx, dy);
      fx += (dx / d) * 3.0; 
      fy += (dy / d) * 3.0;
      hungerFactor = 3; 
    }
  }

  const neighbors = [...entities, player]; 

  for (const other of neighbors) {
    if (other.id === entity.id) continue;
    if (other.isHidden) continue; 

    // Ignore things that are too small to eat (and are not Plankton which are always food)
    // Plankton radius is 6, MIN_RADIUS is 8. So Plankton is smaller, but Plankton type check handles it below.
    // This logic mainly prevents AI from targeting a "broken" small player or entity.
    if (other.type !== CreatureType.PLANKTON && other.radius <= GAME_MECHANICS.MIN_RADIUS_TO_SURVIVE) continue;

    const dx = other.x - entity.x;
    const dy = other.y - entity.y;
    const dSq = dx*dx + dy*dy;

    if (dSq > detectionRange * detectionRange) continue;

    const d = Math.sqrt(dSq);
    const dirX = dx / d;
    const dirY = dy / d;

    // RULE: Avoid things much bigger than you, OR avoid Bosses
    const isDangerous = other.radius > entity.radius * 1.5 || (other.type === CreatureType.LEVIATHAN && entity.type !== CreatureType.LEVIATHAN);

    // RULE: Eat things smaller than you, OR eat Plankton
    const isFood = (other.radius < entity.radius * 0.9) || ((other as Entity).type === CreatureType.PLANKTON);

    // RULE: Mobbing! If I'm small but aggressive, and target is distracted/taunting, attack even if big
    const isMobbing = entity.targetId === other.id;

    if (isDangerous && !isMobbing) {
       const weight = 2000 / (d + 1);
       fx -= dirX * weight;
       fy -= dirY * weight;
       fearFactor += weight;
    } else if (isFood || isMobbing) {
       const aggressive = entity.config.behavior === 'AGGRESSIVE' || entity.config.behavior === 'BOSS';
       const planktonEater = entity.config.behavior === 'PASSIVE' || entity.config.behavior === 'FLEE';
       let wantsIt = false;

       if (aggressive) wantsIt = true;
       if (planktonEater && (other as Entity).type === CreatureType.PLANKTON) wantsIt = true;
       // If starving (low health/size), desperate to eat
       if (entity.radius < entity.config.baseRadius * 0.8) wantsIt = true;

       if (wantsIt) {
         if (d < nearestFoodDist) {
           nearestFoodDist = d;
           nearestFood = other;
         }
       }
    }
  }

  if (nearestFood && fearFactor < 5 && !entity.targetId) {
     const dx = nearestFood.x - entity.x;
     const dy = nearestFood.y - entity.y;
     const d = Math.hypot(dx, dy);
     fx += (dx / d) * 1.5; 
     fy += (dy / d) * 1.5;
     hungerFactor = 1;
  }

  fx += Math.cos(entity.angle) * 0.5;
  fy += Math.sin(entity.angle) * 0.5;

  // Bounds
  const margin = 150;
  if (entity.x < margin) fx += 2;
  if (entity.x > worldW - margin) fx -= 2;
  if (entity.y < margin) fy += 2;
  if (entity.y > worldH - margin) fy -= 2;

  if (Math.abs(fx) > 0.1 || Math.abs(fy) > 0.1) {
    const targetAngle = Math.atan2(fy, fx);
    let angleDiff = targetAngle - entity.angle;
    while (angleDiff > Math.PI) angleDiff -= Math.PI * 2;
    while (angleDiff < -Math.PI) angleDiff += Math.PI * 2;
    entity.angle += angleDiff * agility;
  }

  // Speed Calculation
  let speedMult = 1.0; 
  if (entity.targetId) speedMult = 1.3; 
  else if (fearFactor > 50) speedMult = 1.5; 

  // PowerUp Effect
  if (entity.speedBoostTimer && entity.speedBoostTimer > 0) {
      speedMult *= GAME_MECHANICS.SPEED_ITEM_MULTIPLIER;
  }

  const finalSpeed = entity.speed * speedMult;
  entity.vx = Math.cos(entity.angle) * finalSpeed;
  entity.vy = Math.sin(entity.angle) * finalSpeed;

  entity.x += entity.vx;
  entity.y += entity.vy;

  if (entity.renderScale > 1.0) {
     entity.renderScale += (1.0 - entity.renderScale) * 0.1;
  }
};

const processCollision = (attacker: Entity | PlayerState, victim: Entity | PlayerState, particles: Particle[]) => {
  // Check if attacker is facing victim (Dot product or Angle check)
  const angleToVictim = Math.atan2(victim.y - attacker.y, victim.x - attacker.x);
  let angleDiff = angleToVictim - attacker.angle;
  while (angleDiff > Math.PI) angleDiff -= Math.PI * 2;
  while (angleDiff < -Math.PI) angleDiff += Math.PI * 2;

  // If attacker's mouth is within 60 degrees of the victim, it's a bite
  const isBiting = Math.abs(angleDiff) < Math.PI / 3;

  if (!isBiting) return;

  // --- BITE LOGIC ---

  // 1. Plankton is consumed instantly
  if (victim.type === CreatureType.PLANKTON) {
    // MASS BASED GROWTH: NewRadius = Sqrt(CurrentRadius^2 + MassGained)
    const massGained = GAME_MECHANICS.PLANKTON_MASS;
    const newRadius = Math.sqrt(attacker.radius * attacker.radius + massGained);
    attacker.radius = Math.min(GAME_MECHANICS.MAX_RADIUS, newRadius);

    if ('xp' in attacker) {
       (attacker as PlayerState).xp += victim.config.xpValue;
       (attacker as PlayerState).eatenHistory[victim.type] = ((attacker as PlayerState).eatenHistory[victim.type] || 0) + 1;
    }
    victim.health = 0; // Dead
    attacker.renderScale = 1.1;
    return;
  }

  // PROTECTION: If victim is already at minimum size (and is not Plankton), they cannot be bitten.
  if (victim.radius <= GAME_MECHANICS.MIN_RADIUS_TO_SURVIVE) return;

  // 2. Fish vs Fish (Steal Mass)

  // Calculate Mass to steal based on Attacker's Power (Damage), NOT Attacker's Size
  const damage = attacker.config.damage;
  const desiredMassSteal = damage * GAME_MECHANICS.COMBAT_BITE_MASS_FACTOR;

  // Calculate Victim's available mass above minimum survival size
  const victimCurrentMass = victim.radius * victim.radius; // Using R^2 as proxy for Mass/Area (ignoring PI)
  const victimMinMass = GAME_MECHANICS.MIN_RADIUS_TO_SURVIVE * GAME_MECHANICS.MIN_RADIUS_TO_SURVIVE;
  const availableMass = Math.max(0, victimCurrentMass - victimMinMass);

  const actualMassSteal = Math.min(desiredMassSteal, availableMass);

  // Apply Mass Changes
  // Attacker grows (capped)
  const attackerCurrentMass = attacker.radius * attacker.radius;
  const attackerNewRadius = Math.sqrt(attackerCurrentMass + actualMassSteal);
  attacker.radius = Math.min(GAME_MECHANICS.MAX_RADIUS, attackerNewRadius);

  // Victim shrinks
  const victimNewRadius = Math.sqrt(victimCurrentMass - actualMassSteal);
  victim.radius = Math.max(GAME_MECHANICS.MIN_RADIUS_TO_SURVIVE, victimNewRadius);

  // Visuals
  attacker.renderScale = 1.05;
  victim.renderScale = 0.95;
  particles.push(createParticle(
     (attacker.x + victim.x) / 2,
     (attacker.y + victim.y) / 2,
     victim.config.color
  ));

  // XP for Player
  if ('xp' in attacker) {
      (attacker as PlayerState).xp += 10;
      (attacker as PlayerState).eatenHistory[victim.type] = ((attacker as PlayerState).eatenHistory[victim.type] || 0) + 1;
  }

  // Aggro logic: Victim hates attacker now
  if (!('xp' in victim)) {
     const v = victim as Entity;
     v.targetId = attacker.id;
     v.aggroTimer = 200;
  }

  // Death by shrinking (AI ONLY)
  // If we just drained them to min radius, check if we should kill them (only if they were already small/weak)
  // Actually, min radius logic protects them from death by biting. 
  // AI only dies if damage exceeds health or other mechanics, but here we just transfer mass.
  // We keep the "Death by shrinking" logic for AI clearing if they get stuck at min size too long? 
  // No, let's strictly follow "No death by shrinking" rule for player, and apply similar consistency for AI unless we want to cull population.
  // Let's cull AI if they are tiny and get bitten again at min size?
  // Current logic: `if (victim.radius <= GAME_MECHANICS.MIN_RADIUS_TO_SURVIVE) return;` at top prevents this.
  // So AI never dies from shrinking now. They must be killed by other means (damage?).
  // Wait, `health` is barely used in collision currently, we manipulate radius.
  // Let's add a small health damage too, so AI can eventually die.

  victim.health -= damage;
  if (victim.id !== 'player' && victim.health <= 0) {
      // AI Die
      victim.health = 0; // Ensure dead
      // Bonus XP for kill
      if ('xp' in attacker) (attacker as PlayerState).xp += victim.config.xpValue;
      for(let k=0; k<5; k++) particles.push(createParticle(victim.x, victim.y, victim.config.color));
  }
};

