  if (type === CreatureType.PLANKTON) {
    sx = Math.random() * WORLD_SIZE;
    sy = Math.random() * WORLD_SIZE;
  } else {
    do {
      sx = Math.random() * WORLD_SIZE;
      sy = Math.random() * WORLD_SIZE;
