  spawnEntities(state);

  const targetZoom = Math.max(0.5, 1.4 - (player.radius / 300));
  state.camera.zoom += (targetZoom - state.camera.zoom) * 0.05;
  state.camera.x = player.x; 
  state.camera.y = player.y;

  return state;
};

