        // Damage Player - Check Invulnerability Shield
        const playerInvulnerable = player.isGodMode || player.isInvulnerable || (player.shieldTimer > 0);

        if (dist(player, hazard) < hazard.radius && !playerInvulnerable && !player.isHidden) {
            player.health = 0;
