      if (entity.camoActive) {
        entity.ambushTimer = GAME_MECHANICS.AMBUSH_BONUS_FRAMES;
      }
      entity.camoActive = false;
    }
  }

  if (entity.ambushTimer > 0) entity.ambushTimer--;
