  }

  // Death Check
  if (victim.id !== 'player' && victim.health <= 0) {
      // LAST CHANCE RECRUITMENT (If killed by damage)
      if (attacker.id === 'player' && victim.type !== CreatureType.PLANKTON && !victim.ownerId) {
