          if (e.ownerId === 'player') continue; // Don't shoot squad
          const d = dist(player, e);
          if (d < minThreatDist) {
              // Is it a threat? (Bigger than player)
              if (e.radius > player.radius * 1.1) {
                  minThreatDist = d;
                  nearestThreat = e;
              }
          }
      }

      if (nearestThreat) {
          player.torpedoCount--;
          player.torpedoCooldown = GAME_MECHANICS.TORPEDO_COOLDOWN;
