         const turnNoise = Math.sin(state.time * 0.01 + entity.id.charCodeAt(0));
         entity.angle += turnNoise * 0.01;

         const speed = entity.speed * 0.4; // Slower in menu
         entity.vx = Math.cos(entity.angle) * speed;
         entity.vy = Math.sin(entity.angle) * speed;
         entity.x += entity.vx;
         entity.y += entity.vy;

         // Screen wrapping for menu
         const margin = 100;
         if (entity.x < player.x - screenW/2 - margin) entity.x = player.x + screenW/2 + margin;
         if (entity.x > player.x + screenW/2 + margin) entity.x = player.x - screenW/2 - margin;
         if (entity.y < player.y - screenH/2 - margin) entity.y = player.y + screenH/2 + margin;
         if (entity.y > player.y + screenH/2 + margin) entity.y = player.y - screenH/2 - margin;
     });
     // Slowly pan camera
     state.player.x += 0.5;
     state.player.y += 0.2;
     state.camera.x = state.player.x;
     state.camera.y = state.player.y;
     return state;
  }

