       ctx.ellipse(0, 0, radius * bodyStretch, radius * 0.7, 0, 0, Math.PI * 2);
       ctx.fill();
       ctx.stroke();

       // Hammer Head
       ctx.save();
       ctx.translate(radius * 0.8, 0);
       ctx.fillStyle = entity.config.color;
       ctx.fillRect(-radius * 0.2, -radius * 1.0, radius * 0.5, radius * 2.0);
       ctx.strokeRect(-radius * 0.2, -radius * 1.0, radius * 0.5, radius * 2.0);
       ctx.restore();

       // Tail
       const tailWag = Math.sin(visualTime * 0.4 + animOffset) * 0.3;
       ctx.save();
       ctx.translate(-radius, 0);
       ctx.rotate(tailWag);
       ctx.beginPath();
       ctx.moveTo(0, 0);
       ctx.lineTo(-radius * 0.8, -radius * 0.6);
       ctx.lineTo(-radius * 0.8, radius * 0.6);
       ctx.closePath();
       ctx.fill();
       ctx.stroke();
       ctx.restore();

    } else if (type === CreatureType.NARWHAL) {
       // Body (Chubby)
       ctx.beginPath();
       ctx.ellipse(0, 0, radius * bodyStretch, radius * 0.8, 0, 0, Math.PI * 2);
       ctx.fill();
       ctx.stroke();

       // Tusk
       ctx.fillStyle = '#e2e8f0'; // Light grey horn
       ctx.beginPath();
       ctx.moveTo(radius * 0.9, -radius * 0.2);
       ctx.lineTo(radius * 2.2, 0); // Long spike
       ctx.lineTo(radius * 0.9, radius * 0.2);
       ctx.fill();
       ctx.stroke();

       // Spiral detail on tusk
       ctx.beginPath();
       ctx.moveTo(radius * 1.0, -radius * 0.1);
       ctx.lineTo(radius * 2.0, 0);
       ctx.strokeStyle = '#94a3b8';
       ctx.stroke();

       // Tail
       const tailWag = Math.sin(visualTime * 0.4 + animOffset) * 0.3;
       ctx.save();
       ctx.translate(-radius * 0.8, 0);
       ctx.rotate(tailWag);
       ctx.fillStyle = entity.config.color;
       ctx.strokeStyle = 'rgba(0,0,0,0.2)';
       ctx.beginPath();
       ctx.moveTo(0, 0);
       ctx.lineTo(-radius * 0.6, -radius * 0.5);
       ctx.quadraticCurveTo(-radius * 0.3, 0, -radius * 0.6, radius * 0.5);
       ctx.closePath();
       ctx.fill();
       ctx.stroke();
       ctx.restore();

    } else if (type === CreatureType.MERMAID) {
       // Humanoid Upper Body
       ctx.fillStyle = '#fce7f3'; // Skin toneish
       ctx.beginPath();
       ctx.arc(radius * 0.2, 0, radius * 0.35, 0, Math.PI * 2); // Head/Torso overlap
       ctx.fill();

       // Hair
       ctx.fillStyle = '#db2777'; // Pink hair
       ctx.beginPath();
       ctx.arc(radius * 0.2, 0, radius * 0.4, Math.PI / 2, -Math.PI / 2, true);
       const hairFlow = Math.sin(visualTime * 0.3 + animOffset) * 0.2;
       ctx.lineTo(-radius * 0.5, -radius * 0.5 + hairFlow * 20);
       ctx.lineTo(-radius * 0.5, radius * 0.5 + hairFlow * 20);
       ctx.fill();

       // Fish Tail
       ctx.fillStyle = entity.config.color; // Cyan tail
       ctx.beginPath();
       ctx.moveTo(0, -radius * 0.35);
       ctx.lineTo(-radius * 1.2, -radius * 0.2); // Tail start
       ctx.lineTo(-radius * 1.2, radius * 0.2);
       ctx.lineTo(0, radius * 0.35);
       ctx.fill();
       ctx.stroke();

       // Fin
       const tailWag = Math.sin(visualTime * 0.5 + animOffset) * 0.4;
       ctx.save();
       ctx.translate(-radius * 1.2, 0);
       ctx.rotate(tailWag);
       ctx.beginPath();
       ctx.moveTo(0, 0);
       ctx.lineTo(-radius * 0.6, -radius * 0.6);
       ctx.lineTo(-radius * 0.6, radius * 0.6);
       ctx.closePath();
       ctx.fill();
       ctx.stroke();
       ctx.restore();

    } else if (type === CreatureType.AROWANA) {
       // Long body
       ctx.beginPath();
       ctx.ellipse(0, 0, radius * 1.3, radius * 0.5, 0, 0, Math.PI * 2);
       ctx.fill();
       ctx.stroke();

       // Scales
       ctx.strokeStyle = '#d97706'; // Darker gold
       ctx.lineWidth = 2;
       for(let i=0; i<3; i++) {
          ctx.beginPath();
          ctx.arc(-radius * 0.5 + i * radius * 0.6, 0, radius * 0.25, -Math.PI/2, Math.PI/2);
          ctx.stroke();
       }

       // Tail
       const tailWag = Math.sin(visualTime * 0.4 + animOffset) * 0.3;
       ctx.save();
       ctx.translate(-radius * 1.2, 0);
       ctx.rotate(tailWag);
       ctx.beginPath();
       ctx.moveTo(0, -radius * 0.2);
       ctx.lineTo(-radius * 0.4, -radius * 0.4);
       ctx.lineTo(-radius * 0.4, radius * 0.4);
       ctx.lineTo(0, radius * 0.2);
       ctx.fill();
       ctx.stroke();
       ctx.restore();

    } else if (type === CreatureType.FUR_SEAL) {
       // Sleek body
       ctx.beginPath();
       ctx.ellipse(0, 0, radius * 1.2, radius * 0.6, 0, 0, Math.PI * 2);
       ctx.fill();
       ctx.stroke();

       // Tail flippers
       const tailWag = Math.sin(visualTime * 0.6 + animOffset) * 0.3;
       ctx.save();
       ctx.translate(-radius * 1.1, 0);
       ctx.rotate(tailWag);
       ctx.beginPath();
       ctx.moveTo(0, 0);
       ctx.lineTo(-radius * 0.5, -radius * 0.3);
       ctx.lineTo(-radius * 0.5, radius * 0.3);
       ctx.closePath();
       ctx.fill();
       ctx.stroke();
       ctx.restore();

    } else {
       // Standard Fish Body
       ctx.beginPath();
       ctx.ellipse(0, 0, radius * bodyStretch, radius * 0.85, 0, 0, Math.PI * 2);
       ctx.fill();
       ctx.stroke(); 

       const tailWag = Math.sin(visualTime * 0.4 + animOffset) * 0.3;
       ctx.save();
       ctx.translate(-radius, 0);
       ctx.rotate(tailWag);
       ctx.beginPath();
       ctx.moveTo(0, 0);
       ctx.lineTo(-radius * 0.6, -radius * 0.5);
       ctx.lineTo(-radius * 0.6, radius * 0.5);
       ctx.closePath();
       ctx.fill();
       ctx.stroke();
       ctx.restore();
    }

    // -- Features (Eyes, Teeth, Lure) --

    if (type === CreatureType.ANGLER_FISH) {
       ctx.strokeStyle = "black";
       ctx.lineWidth = 2;
       ctx.beginPath();
       ctx.moveTo(radius * 0.5, -radius * 0.2);
       ctx.quadraticCurveTo(radius * 1.2, -radius * 0.8, radius * 1.5, -radius * 0.3);
       ctx.stroke();

       const lightX = radius * 1.5;
       const lightY = -radius * 0.3;
       const isLureActive = entity.lureActive;

       ctx.fillStyle = isLureActive ? "#fef08a" : "#4b5563";
       ctx.beginPath();
       ctx.arc(lightX, lightY, radius * 0.15, 0, Math.PI*2);
       ctx.fill();
       ctx.stroke();

       if (isLureActive) {
          ctx.shadowColor = "#fef08a";
          ctx.shadowBlur = 20 + Math.sin(visualTime * 0.2) * 10;
          ctx.fillStyle = "rgba(254, 240, 138, 0.5)";
          ctx.beginPath();
          ctx.arc(lightX, lightY, radius * 0.3, 0, Math.PI*2);
          ctx.fill();
          ctx.shadowBlur = 0; 
       }
    }

    // Eyes
    if (type !== CreatureType.PLANKTON && type !== CreatureType.JELLYFISH && type !== CreatureType.STINGRAY) {
      const eyeSizeBase = radius * 0.35;
      let eyeX = radius * 0.3;
      let eyeYOffset = radius * 0.35;

      if (type === CreatureType.HAMMERHEAD) {
          eyeX = radius * 0.9;
          eyeYOffset = radius * 0.9; // Eyes on the hammer
      }
      else if (type === CreatureType.ELECTRIC_EEL) {
          eyeX = radius * 0.9;
          eyeYOffset = radius * 0.2;
      }
      else if (type === CreatureType.NARWHAL) {
          eyeX = radius * 0.5;
          eyeYOffset = radius * 0.4;
      }
      else if (type === CreatureType.AROWANA) {
          eyeX = radius * 0.8;
          eyeYOffset = radius * 0.25;
      }

      const leftEyeSize = eyeSizeBase * 1.1;
      const rightEyeSize = eyeSizeBase * 0.8;

      ctx.lineWidth = 1;
      ctx.strokeStyle = 'black';

      ctx.fillStyle = 'white';
      ctx.beginPath();

      if (isHappy) {
          // HAPPY EYES ^ ^
          const drawHappyEye = (ex: number, ey: number, size: number) => {
              ctx.beginPath();
              ctx.lineWidth = 2;
              ctx.strokeStyle = 'black';
              ctx.moveTo(ex - size * 0.5, ey);
              ctx.quadraticCurveTo(ex, ey - size * 0.5, ex + size * 0.5, ey);
              ctx.stroke();
          };
          drawHappyEye(eyeX, -eyeYOffset, leftEyeSize);
          drawHappyEye(eyeX, eyeYOffset, rightEyeSize);
      } else {
          // Normal Eyes
          ctx.arc(eyeX, -eyeYOffset, leftEyeSize, 0, Math.PI * 2); 
          ctx.fill();
          ctx.stroke();

          ctx.beginPath();
          ctx.arc(eyeX, eyeYOffset, rightEyeSize, 0, Math.PI * 2); 
          ctx.fill();
          ctx.stroke();

          const lookX = Math.cos(visualTime * 0.1 + animOffset) * leftEyeSize * 0.2;
          const lookY = Math.sin(visualTime * 0.2 + animOffset) * leftEyeSize * 0.2;

          ctx.fillStyle = 'black';

          ctx.beginPath();
          ctx.arc(eyeX + lookX, -eyeYOffset + lookY, leftEyeSize * 0.3, 0, Math.PI * 2);
          ctx.fill();

          ctx.beginPath();
          ctx.arc(eyeX - lookY, eyeYOffset + lookX, rightEyeSize * 0.3, 0, Math.PI * 2);
          ctx.fill();
      }
    } else if (type === CreatureType.STINGRAY) {
        // Stingray Eyes on top
        if (isHappy) {
            ctx.strokeStyle = 'white';
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(radius * 0.2, -radius * 0.3);
            ctx.lineTo(radius * 0.3, -radius * 0.35);
            ctx.lineTo(radius * 0.4, -radius * 0.3);
            ctx.moveTo(radius * 0.2, radius * 0.3);
            ctx.lineTo(radius * 0.3, radius * 0.35);
            ctx.lineTo(radius * 0.4, radius * 0.3);
            ctx.stroke();
        } else {
            ctx.fillStyle = 'white';
            ctx.beginPath();
            ctx.arc(radius * 0.3, -radius * 0.3, radius * 0.15, 0, Math.PI*2);
            ctx.arc(radius * 0.3, radius * 0.3, radius * 0.15, 0, Math.PI*2);
            ctx.fill();
            ctx.fillStyle = 'black';
            ctx.beginPath();
            ctx.arc(radius * 0.35, -radius * 0.3, radius * 0.05, 0, Math.PI*2);
            ctx.arc(radius * 0.35, radius * 0.3, radius * 0.05, 0, Math.PI*2);
            ctx.fill();
        }
    }

    // Mouth
    if (type !== CreatureType.PLANKTON && type !== CreatureType.STINGRAY && type !== CreatureType.MERMAID) {
       ctx.save();
       ctx.translate(radius * 0.6, 0); 
       if (type === CreatureType.ELECTRIC_EEL) ctx.translate(radius * 0.4, 0);
       if (type === CreatureType.AROWANA) ctx.translate(radius * 0.4, -radius * 0.1); // Upturned mouth
       if (type === CreatureType.NARWHAL) ctx.translate(0, radius * 0.2); // Mouth below tusk

       const breath = 0.4 + 0.1 * Math.sin(visualTime * 0.2 + animOffset);
       let effectiveOpen = Math.max(breath, mouthOpenValue);

       // Chewing action when happy (FIXED SMOOTHNESS)
       if (isHappy) {
           // Use (sin + 1) / 2 to oscillate between 0 and 1 smoothly, then map to range
           const chew = (Math.sin(visualTime * 0.2) + 1) * 0.5; 
           effectiveOpen = 0.2 + chew * 0.3; 
       }

       const openW = radius * 0.5; 
       const openH = effectiveOpen * radius * 0.8;

       ctx.fillStyle = '#450a0a'; 
       ctx.beginPath();
       ctx.ellipse(0, 0, openW, openH, 0, 0, Math.PI * 2);
       ctx.fill();
       ctx.lineWidth = 2;
       ctx.strokeStyle = 'rgba(0,0,0,0.5)';
       ctx.stroke();

       // Teeth
       const toothColor = '#ffffff';
       const toothStroke = '#000000';
       ctx.fillStyle = toothColor;
       ctx.strokeStyle = toothStroke;
       ctx.lineWidth = 2;
       ctx.lineJoin = 'round'; 

       const seed = Math.floor(animOffset * 100);
       const rnd = (i: number) => {
         const x = Math.sin(seed + i * 132.1);
         return x * x; 
       };

       const drawTeethRow = (isTop: boolean) => {
          const numTeeth = (type === CreatureType.ANGLER_FISH || type === CreatureType.KRAKEN || type === CreatureType.GREAT_WHITE || type === CreatureType.AROWANA) ? 5 : 3; 
          const rowY = isTop ? -openH : openH;
          const dir = isTop ? 1 : -1;
          const totalW = openW * 1.6;
          const startX = -totalW / 2 + openW * 0.2;
          const step = totalW / numTeeth;

          ctx.beginPath();
          for(let i=0; i<numTeeth; i++) {
             const tX = startX + i * step;
             const tH = (openH * 0.6) + (openH * 0.6 * rnd(i + (isTop?0:10))); 

             const x1 = tX;
             const x2 = tX + step;
             const yBase = rowY;
             const tipX = tX + step * 0.5;
             const tipY = rowY + (tH * dir);

             ctx.moveTo(x1, yBase);
             ctx.quadraticCurveTo(tipX, tipY * 1.2, x2, yBase); 
          }
          ctx.fill();
          ctx.stroke();
       };

       drawTeethRow(true); 
       drawTeethRow(false); 

       ctx.restore();
    }

    // DRAW BOOST BAR FOR PLAYER (Attached to head)
    if (isPlayer) {
        // Rotate back so the bar stays horizontal relative to screen/fish
        ctx.save();
        ctx.rotate(-entity.angle); 

        // Position above head (adjust for radius)
        const barW = Math.max(40, radius * 2.5);
        const barH = 6;
        const barY = -radius - 15; // Gap above fish

        const p = entity as PlayerState;
        const boostRatio = p.boost.current / p.boost.max;
        const isFull = boostRatio >= 0.99;
        const isOverdrive = p.isOverdrive;

        // Background
        ctx.fillStyle = "rgba(0,0,0,0.6)";
        // If Overdrive, pulse red border
        if (isOverdrive) {
             const pulse = Math.abs(Math.sin(visualTime * 0.2)) * 3;
             ctx.strokeStyle = "#ef4444";
             ctx.lineWidth = 1 + pulse;
             ctx.strokeRect(-barW/2, barY, barW, barH);
        }

        ctx.beginPath();
        ctx.roundRect(-barW/2, barY, barW, barH, 3);
        ctx.fill();

        // Fill
        if (boostRatio > 0.05) {
            ctx.fillStyle = isFull ? "#fcd34d" : (boostRatio < 0.2 ? "#ef4444" : "#fbbf24");
            ctx.beginPath();
            ctx.roundRect(-barW/2 + 1, barY + 1, (barW - 2) * boostRatio, barH - 2, 2);
            ctx.fill();
        } else if (isOverdrive) {
            // Burning Weight Indicator (Solid Red Bar when empty but Overdriving)
            ctx.fillStyle = "#ef4444";
            const weightRatio = Math.min(1.0, Math.max(0, (p.weight - BOOST_CONFIG.OVERDRIVE_MIN_WEIGHT) / 10)); // Arbitrary scale for visual
            ctx.beginPath();
            ctx.roundRect(-barW/2 + 1, barY + 1, (barW - 2) * weightRatio, barH - 2, 2);
            ctx.fill();
        }

        // "MAX" or "OVERDRIVE" Text Effect
        if (isOverdrive) {
            ctx.fillStyle = "#ef4444";
            ctx.font = "bold 10px sans-serif";
            ctx.textAlign = "center";
            ctx.shadowColor = "red";
            ctx.shadowBlur = 4;
            const float = Math.sin(visualTime * 0.5) * 1;
            ctx.fillText(`${p.weight.toFixed(1)}kg`, 0, barY - 4 + float); // SHOW REAL-TIME WEIGHT
            ctx.shadowBlur = 0;
        } else if (isFull) {
            ctx.fillStyle = "#fcd34d";
            ctx.font = "bold 10px sans-serif";
            ctx.textAlign = "center";
            ctx.shadowColor = "black";
            ctx.shadowBlur = 2;
            const float = Math.sin(visualTime * 0.2) * 2;
            ctx.fillText("READY!", 0, barY - 4 + float);
            ctx.shadowBlur = 0;
        }

        ctx.restore();
    }

    if (entity.aggroTimer && entity.aggroTimer > 0 && !isPlayer && !isSquad) {
      ctx.save();
      ctx.translate(0, -radius * 1.5);
      ctx.fillStyle = '#ef4444';
      ctx.font = "bold 24px sans-serif";
      ctx.fillText("💢", 0, 0);
      ctx.restore();
    }

    // SPEECH BUBBLE
    if (entity.speechBubble) {
        ctx.save();
        // Counter-rotate to keep text upright relative to screen (not fish body)
        // Since we are rotated by `entity.angle`
        ctx.rotate(-entity.angle);

        // Push it further up if boost bar is there
        const boostOffset = isPlayer ? 20 : 0;
        ctx.translate(0, -radius - 30 - boostOffset);

        const text = entity.speechBubble.text;
        ctx.font = "bold 24px 'Microsoft YaHei', sans-serif";
        const metrics = ctx.measureText(text);
        const w = metrics.width + 20;
        const h = 34;

        // Bubble body
        ctx.fillStyle = 'rgba(0, 0, 0, 0.6)';
        ctx.strokeStyle = entity.speechBubble.color;
        ctx.lineWidth = 2;

        ctx.beginPath();
        // Simple rounded rect centered
        const r = 8;
        const x = -w/2;
        const y = -h/2;
        ctx.moveTo(x + r, y);
        ctx.lineTo(x + w - r, y);
        ctx.quadraticCurveTo(x + w, y, x + w, y + r);
        ctx.lineTo(x + w, y + h - r);
        ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
        ctx.lineTo(x + r, y + h);
        ctx.quadraticCurveTo(x, y + h, x, y + h - r);
        ctx.lineTo(x, y + r);
        ctx.quadraticCurveTo(x, y, x + r, y);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // Text
        ctx.fillStyle = entity.speechBubble.color;
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.fillText(text, 0, 0);

        ctx.restore();
    }

    // HEART EFFECT (Below speech bubble priority in visual stack)
    if (isHappy && !entity.speechBubble) {
        ctx.save();
        const boostOffset = isPlayer ? 15 : 0;
        ctx.translate(0, -radius * 1.2 - 20 - boostOffset);
        const beat = Math.sin(visualTime * 0.2) * 0.1 + 1; // Smooth beat
        ctx.scale(beat, beat);
        ctx.fillStyle = '#ef4444';
        ctx.font = "bold 24px sans-serif";
        ctx.textAlign = "center";
        ctx.fillText("❤️", 0, 0);
        ctx.restore();
    }

    ctx.restore();
  };

  const drawPowerUp = (ctx: CanvasRenderingContext2D, p: PowerUp, visualTime: number) => {
    ctx.save();
    ctx.translate(p.x, p.y);
    const floatY = Math.sin(visualTime * 0.1) * 5;
    ctx.translate(0, floatY);

    if (p.type === 'SPEED') {
      ctx.fillStyle = '#fde047'; 
      ctx.beginPath();
      ctx.arc(0, 0, p.radius, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#f59e0b'; 
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.fillStyle = '#b45309';
      // Bolt Icon
      ctx.beginPath();
      ctx.moveTo(0, -8);
      ctx.lineTo(5, 0);
      ctx.lineTo(0, 0);
      ctx.lineTo(0, 8);
      ctx.lineTo(-5, 0);
      ctx.lineTo(0, 0);
      ctx.fill();
    } else if (p.type === 'SHIELD') {
        ctx.fillStyle = '#06b6d4'; 
        ctx.beginPath();
        ctx.arc(0, 0, p.radius, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#22d3ee'; 
        ctx.lineWidth = 2;
        ctx.stroke();
        // Shield Icon
        ctx.strokeStyle = 'white';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.moveTo(0, -8);
        ctx.quadraticCurveTo(8, -8, 8, 0);
        ctx.quadraticCurveTo(8, 8, 0, 10);
        ctx.quadraticCurveTo(-8, 8, -8, 0);
        ctx.quadraticCurveTo(-8, -8, 0, -8);
        ctx.stroke();
    } else if (p.type === 'TORPEDO') {
        ctx.fillStyle = '#f87171'; 
        ctx.beginPath();
        ctx.arc(0, 0, p.radius, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#ef4444'; 
        ctx.lineWidth = 2;
        ctx.stroke();
        // Missile Icon
        ctx.fillStyle = 'white';
        ctx.translate(-5, -5);
        ctx.beginPath();
        ctx.moveTo(0, 10);
        ctx.lineTo(10, 0);
        ctx.lineTo(8, -2);
        ctx.lineTo(-2, 8);
        ctx.fill();
    }
    ctx.restore();
  };

  const drawProjectile = (ctx: CanvasRenderingContext2D, p: Projectile, visualTime: number) => {
      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.rotate(p.angle);

      // Body
      ctx.fillStyle = '#ef4444';
      ctx.beginPath();
      ctx.moveTo(10, 0);
      ctx.lineTo(-5, 5);
      ctx.lineTo(-5, -5);
      ctx.fill();

      // Fins
      ctx.fillStyle = '#991b1b';
      ctx.beginPath();
      ctx.moveTo(-5, 0);
      ctx.lineTo(-10, 5);
      ctx.lineTo(-8, 0);
      ctx.lineTo(-10, -5);
      ctx.fill();

      // Flame
      ctx.fillStyle = visualTime % 4 < 2 ? '#fef08a' : '#f97316';
      ctx.beginPath();
      ctx.arc(-12, 0, 3 + Math.random()*2, 0, Math.PI*2);
      ctx.fill();

      ctx.restore();
  };

  const drawHazard = (ctx: CanvasRenderingContext2D, h: Hazard, visualTime: number) => {
     ctx.save();
     ctx.translate(h.x, h.y);

     if (h.stage === 'WARNING') {
        // Red Ground Warning Zone
        const pulse = Math.sin(visualTime * 0.2) * 0.1 + 0.9;
        ctx.fillStyle = 'rgba(255, 0, 0, 0.2)';
        ctx.beginPath();
        ctx.arc(0, 0, h.radius, 0, Math.PI * 2);
        ctx.fill();

        ctx.strokeStyle = `rgba(255, 50, 50, ${Math.abs(Math.sin(visualTime * 0.1))})`;
        ctx.lineWidth = 4;
        ctx.beginPath();
        ctx.arc(0, 0, h.radius * pulse, 0, Math.PI * 2);
        ctx.stroke();

        ctx.fillStyle = '#ef4444';
        ctx.font = "bold 30px sans-serif";
        ctx.textAlign = "center";
        ctx.shadowColor = 'black';
        ctx.shadowBlur = 4;
        ctx.fillText("⚠️ 危险区域", 0, -h.radius - 20);
        ctx.shadowBlur = 0;

        // Shadow getting bigger
        const shadowSize = h.radius * (1 - (h.timer / 120)) * 0.8;
        ctx.fillStyle = 'rgba(0,0,0,0.4)';
        ctx.beginPath();
        ctx.arc(0,0, shadowSize, 0, Math.PI*2);
        ctx.fill();
     } else if (h.stage === 'STRIKE') {
        // Impact
        ctx.fillStyle = '#f59e0b'; // Fireball center
        ctx.beginPath();
        ctx.arc(0, 0, h.radius * 0.5, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#78350f';
        ctx.lineWidth = 4;
        ctx.stroke();
     }
     ctx.restore();
  };

  const drawObstacle = (ctx: CanvasRenderingContext2D, obs: Obstacle, visualTime: number) => {
    ctx.save();
    ctx.translate(obs.x, obs.y);
    ctx.lineWidth = 3;
    ctx.strokeStyle = 'rgba(0,0,0,0.3)';

    if (obs.type === 'ROCK') {
      ctx.fillStyle = '#64748b';
      ctx.beginPath();
      ctx.arc(0, 0, obs.radius, 0, Math.PI * 2);
