export const updateGame = (state: GameState, mouse: {x: number, y: number}, isSpaceHeld: boolean, tauntActive: boolean, screenW: number, screenH: number): GameState => {
  if (state.status !== GameStatus.PLAYING && state.status !== GameStatus.MENU) return state;

  state.time += 1;
  const { player } = state;
  const newParticles: Particle[] = [];

  // IN MENU MODE: Only update simple movement for background fish
  if (state.status === GameStatus.MENU) {
     state.entities.forEach(entity => {
         updateStrategyState(entity);
         // Gentle floating with smooth turns
         const turnNoise = Math.sin(state.time * 0.01 + entity.id.charCodeAt(0));
         entity.angle += turnNoise * 0.005; // Reduced turn speed to stop "twitching"

         const speed = entity.speed * 0.3; // Slower in menu
         entity.vx = Math.cos(entity.angle) * speed;
         entity.vy = Math.sin(entity.angle) * speed;
         entity.x += entity.vx;
         entity.y += entity.vy;

         // Screen wrapping for menu
         const margin = 100;
         if (entity.x < player.x - screenW/2 - margin) entity.x = player.x + screenW/2 + margin;
         if (entity.x > player.x + screenW/2 + margin) entity.x = player.x - screenW/2 - margin;
         if (entity.y < player.y - screenH/2 - margin) entity.y = player.y + screenH/2 + margin;
         if (entity.y > player.y + screenH/2 + margin) entity.y = player.y - screenH/2 - margin;
     });
     // Slowly pan camera
     state.player.x += 0.5;
     state.player.y += 0.2;
     state.camera.x = state.player.x;
     state.camera.y = state.player.y;
     return state;
  }

