      if (player.shieldTimer <= 0 && !player.isGodMode) {
          player.isInvulnerable = false;
      }
  }

  spawnPowerUps(state);
  spawnHazards(state);
  createObstacles().forEach(o => { if (Math.random() < 0.005 && state.obstacles.length < MAX_OBSTACLES) state.obstacles.push(o) });
  updateHazards(state, newParticles);
  updateStrategyState(player); 

  // Check player death from hazards (if not caught inside updateHazards)
  if (player.health <= 0 && (state.status as GameStatus) !== GameStatus.GAME_OVER) {
     if (!emergencySquadSwitch(state)) {
         state.status = GameStatus.GAME_OVER;
     }
