  state.obstacles = state.obstacles.filter(o => dist(player, o) < MAX_RENDER_DIST);
  state.powerUps = state.powerUps.filter(p => dist(player, p) < MAX_RENDER_DIST);

  // --- TORPEDO AUTO-FIRE LOGIC ---
  if (player.torpedoCount > 0 && player.torpedoCooldown <= 0) {
      // Find nearest THREAT (Predator) that is close
      let nearestThreat: Entity | null = null;
      let minThreatDist = 500; // Danger radius

      for (const e of state.entities) {
          if (e.isHidden) continue;
          if (e.ownerId === 'player') continue; // Don't shoot squad
          const d = dist(player, e);
          if (d < minThreatDist) {
              // Is it a threat? (Bigger than player)
              if (e.radius > player.radius * 1.1) {
                  minThreatDist = d;
                  nearestThreat = e;
              }
          }
      }

      if (nearestThreat) {
          player.torpedoCount--;
          player.torpedoCooldown = GAME_MECHANICS.TORPEDO_COOLDOWN;
          player.speechBubble = { text: "鱼雷发射!", timer: 45, color: "#f87171" };

          // Fire Torpedo
          const angle = Math.atan2(nearestThreat.y - player.y, nearestThreat.x - player.x);
          state.projectiles.push({
              id: uuid(),
              x: player.x,
              y: player.y,
              vx: Math.cos(angle) * GAME_MECHANICS.TORPEDO_SPEED,
              vy: Math.sin(angle) * GAME_MECHANICS.TORPEDO_SPEED,
              angle: angle,
              life: 180, // 3 seconds
              targetId: nearestThreat.id,
              radius: 10,
              damage: GAME_MECHANICS.TORPEDO_DAMAGE
