          if (target) {
              const dx = target.x - p.x;
              const dy = target.y - p.y;
              const targetAngle = Math.atan2(dy, dx);
              // Smooth turn
              let diff = targetAngle - p.angle;
              while (diff > Math.PI) diff -= Math.PI * 2;
              while (diff < -Math.PI) diff += Math.PI * 2;
              p.angle += diff * 0.1;

              p.vx = Math.cos(p.angle) * GAME_MECHANICS.TORPEDO_SPEED;
              p.vy = Math.sin(p.angle) * GAME_MECHANICS.TORPEDO_SPEED;
          }
      }

      p.x += p.vx;
      p.y += p.vy;
      p.life--;

      // Bubble trail
