  if (entity.config.special === 'LURE') {
    if (entity.isIdle) {
      entity.lureActive = true;
    } else {
      if (entity.lureActive) {
        entity.ambushTimer = GAME_MECHANICS.AMBUSH_BONUS_FRAMES;
