  const cy = WORLD_SIZE / 2;

  for (let i = 0; i < MAX_OBSTACLES; i++) {
    const r = Math.random();
    const type = r < 0.35 ? 'ROCK' : (r < 0.65 ? 'CORAL' : 'SEAWEED');
    const radius = 60 + Math.random() * 220; 

    const dist = 300 + Math.random() * 2000;
