      }
      if (state.time % 60 === 0 && !player.speechBubble) {
           player.speechBubble = { text: "快跑!!", timer: 30, color: "#f87171" };
      }
  }

  // --- OVERDRIVE & BOOST LOGIC ---

  // Reset Overdrive state every frame based on input, it's not a toggle anymore
  player.isOverdrive = false; 

  // Passive Regen if not using any boost
  if (!isSpaceHeld && player.boost.current < player.boost.max) {
