          }
      }

      victim.health = 0; 
      if ('weight' in attacker) (attacker as PlayerState).weight += victim.config.weightValue;
      for(let k=0; k<5; k++) particles.push(createParticle(victim.x, victim.y, victim.config.color));
      attacker.happyTimer = 60;
