interface GameCanvasProps {
  gameState: GameState;
  onMouseMove: (x: number, y: number) => void;
  onMouseDown: () => void;
  onMouseUp: () => void;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ gameState, onMouseMove, onMouseDown, onMouseUp }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // --- CUTE & FUNNY FISH DRAWING ---
  // Use visualTime (smooth float based on real time) for animations, not game tick time
  const drawCuteFish = (ctx: CanvasRenderingContext2D, entity: Entity, visualTime: number, isPlayer: boolean) => {
    const { type, radius, animOffset, mouthOpenValue, renderScale, isInvulnerable, happyTimer, ownerId, fearTimer, aggroTimer } = entity;

    const safeScale = Number.isFinite(renderScale) ? renderScale : 1;
    const isHappy = happyTimer && happyTimer > 0;
    const isScared = fearTimer && fearTimer > 0;
    const isAngry = aggroTimer && aggroTimer > 0;
    const isSquad = ownerId === 'player';

    ctx.save();
    ctx.translate(entity.x, entity.y);

    // SCARED SHAKE EFFECT
    if (isScared) {
        const shake = Math.sin(visualTime * 2) * 3;
        ctx.translate(shake, shake);
    }

    ctx.scale(safeScale, safeScale);

    // EVOLUTION EFFECT HERE (Before rotation to keep it independent)
    if (entity.evolutionVisualTimer && entity.evolutionVisualTimer > 0) {
        ctx.save();
        const evoTime = 180 - entity.evolutionVisualTimer; // Time since start
        const alpha = Math.min(1, entity.evolutionVisualTimer / 30); // Fade out at end

        // Rotating Golden Rays
        ctx.rotate(visualTime * 0.05); // Slow rotation
        ctx.globalAlpha = 0.6 * alpha;
        ctx.fillStyle = '#fbbf24'; // Amber-400
        for(let i=0; i<8; i++) {
             ctx.beginPath();
             ctx.rotate(Math.PI / 4);
             ctx.moveTo(0, 0);
             ctx.lineTo(radius * 3, -radius * 0.5);
             ctx.lineTo(radius * 3, radius * 0.5);
             ctx.fill();
        }

        // Inner Glow
        ctx.globalAlpha = 0.8 * alpha;
        ctx.beginPath();
        ctx.arc(0, 0, radius * 1.5, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(251, 191, 36, 0.3)';
        ctx.fill();
        ctx.strokeStyle = '#fcd34d';
        ctx.lineWidth = 4;
        ctx.stroke();

        ctx.restore();
    }

    // Rotate the fish body
    ctx.rotate(entity.angle);

    // --- PLAYER BOOST FULL EFFECT (Before drawing body for behind-glow) ---
    if (isPlayer) {
        const p = entity as PlayerState;
        const boostRatio = p.boost.current / p.boost.max;
        const isFull = boostRatio >= 0.99;
        const isOverdrive = p.isOverdrive;

        if (isFull && !isOverdrive) {
            ctx.save();
            ctx.shadowColor = '#fbbf24'; // Amber/Gold glow
            ctx.shadowBlur = 20 + Math.sin(visualTime * 0.2) * 10;
            // Pulsing ring
            ctx.beginPath();
            ctx.strokeStyle = `rgba(251, 191, 36, ${0.4 + Math.sin(visualTime * 0.3) * 0.2})`;
            ctx.lineWidth = 4;
            ctx.arc(0, 0, radius * 1.8, 0, Math.PI * 2);
            ctx.stroke();
            ctx.restore();
        }

        // OVERDRIVE GLOW
        if (isOverdrive) {
            ctx.save();
            ctx.shadowColor = '#ef4444'; // Red glow
            ctx.shadowBlur = 25 + Math.sin(visualTime * 0.5) * 15;
            ctx.beginPath();
            ctx.strokeStyle = `rgba(239, 68, 68, ${0.5 + Math.sin(visualTime * 0.8) * 0.3})`;
            ctx.lineWidth = 6;
            ctx.arc(0, 0, radius * 1.8, 0, Math.PI * 2);
            ctx.stroke();
            ctx.restore();
        }
    }

    // --- SQUAD MARKER ---
    if (isSquad) {
       ctx.save();
       // Rotate back so the text is upright relative to fish
       // Or draw a ring
       ctx.strokeStyle = '#4ade80'; // Green ring
       ctx.lineWidth = 3;
       ctx.setLineDash([5, 5]);
       ctx.beginPath();
       ctx.arc(0, 0, radius * 1.3, 0, Math.PI * 2);
       ctx.stroke();
       ctx.restore();
    }

    // --- CAMOUFLAGE (Squid/Octopus hidden) ---
    if (entity.camoActive) {
      ctx.fillStyle = "#64748b"; 
      ctx.beginPath();
      for(let i=0; i<8; i++) {
        const ang = (Math.PI*2 * i)/8;
        const r = radius * (0.8 + Math.sin(visualTime*0.05 + i * 132)*0.2);
        ctx.lineTo(Math.cos(ang)*r, Math.sin(ang)*r);
      }
      ctx.fill();
      ctx.stroke();

      const blink = Math.sin(visualTime * 0.1) > 0.95;
      if (!blink) {
        ctx.fillStyle = "white";
        ctx.beginPath();
        ctx.arc(radius*0.3, -radius*0.2, radius*0.15, 0, Math.PI*2);
        ctx.fill();
        ctx.fillStyle = "black";
        ctx.beginPath();
        ctx.arc(radius*0.3, -radius*0.2, radius*0.05, 0, Math.PI*2);
        ctx.fill();
      }
      ctx.restore();
      return; 
    }

    if (isInvulnerable || (isPlayer && (entity as PlayerState).isGodMode)) {
      ctx.save();
      ctx.rotate(visualTime * 0.1);
      ctx.beginPath();
      ctx.strokeStyle = `hsl(${(visualTime * 5) % 360}, 100%, 70%)`;
      ctx.lineWidth = 4;
      ctx.setLineDash([10, 10]);
      ctx.arc(0, 0, radius * 1.5, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
    }

    // --- PLAYER SHIELD VISUAL ---
    if (isPlayer && 'shieldTimer' in entity) {
        const p = entity as PlayerState;
        if (p.shieldTimer > 0) {
            ctx.save();
            ctx.globalAlpha = 0.4 + Math.sin(visualTime * 0.2) * 0.1;
            ctx.fillStyle = '#22d3ee'; // Cyan bubble
            ctx.strokeStyle = '#a5f3fc';
            ctx.lineWidth = 3;
            ctx.beginPath();
            ctx.arc(0, 0, radius * 1.6, 0, Math.PI * 2);
            ctx.fill();
            ctx.stroke();

            // Hexagon grid effect
            ctx.globalAlpha = 0.2;
            ctx.beginPath();
            for(let i=0; i<6; i++) {
                 const a = (Math.PI*2 * i)/6 + visualTime * 0.05;
                 ctx.moveTo(0,0);
                 ctx.lineTo(Math.cos(a)*radius*1.6, Math.sin(a)*radius*1.6);
            }
            ctx.stroke();

            ctx.restore();
        }
    }

    if (entity.speedBoostTimer && entity.speedBoostTimer > 0) {
      ctx.save();
      ctx.globalAlpha = 0.6;
      ctx.fillStyle = '#fde047'; 
      ctx.beginPath();
      ctx.arc(-radius, 0, radius * 0.8, 0, Math.PI*2);
      ctx.fill();
      ctx.restore();
    }

    if (entity.ambushTimer > 0) {
       ctx.strokeStyle = "red";
       ctx.lineWidth = 3;
       ctx.beginPath();
       ctx.moveTo(radius * 1.2, 0);
       ctx.lineTo(radius * 1.5, 0);
