       ctx.beginPath();
       ctx.ellipse(0, 0, radius * 1.2, radius * 0.6, 0, 0, Math.PI * 2);
       ctx.fill();
       ctx.stroke();

       // Tail flippers
       const tailWag = Math.sin(visualTime * 0.6 + animOffset) * 0.3;
       ctx.save();
       ctx.translate(-radius * 1.1, 0);
       ctx.rotate(tailWag);
       ctx.beginPath();
       ctx.moveTo(0, 0);
       ctx.lineTo(-radius * 0.5, -radius * 0.3);
       ctx.lineTo(-radius * 0.5, radius * 0.3);
       ctx.closePath();
       ctx.fill();
       ctx.stroke();
       ctx.restore();

    } else {
       // Standard Fish Body
       ctx.beginPath();
       ctx.ellipse(0, 0, radius * bodyStretch, radius * 0.85, 0, 0, Math.PI * 2);
       ctx.fill();
       ctx.stroke(); 

       const tailWag = Math.sin(visualTime * 0.4 + animOffset) * 0.3;
       ctx.save();
       ctx.translate(-radius, 0);
       ctx.rotate(tailWag);
       ctx.beginPath();
       ctx.moveTo(0, 0);
       ctx.lineTo(-radius * 0.6, -radius * 0.5);
       ctx.lineTo(-radius * 0.6, radius * 0.5);
       ctx.closePath();
       ctx.fill();
       ctx.stroke();
       ctx.restore();
    }

