             const dirY = (player.y - entity.y) / distToPlayer;
             fx += dirX * 2.0;
             fy += dirY * 2.0;
         } else {
             const wanderAngle = entity.angle + (Math.random() - 0.5);
             fx += Math.cos(wanderAngle) * 0.5;
             fy += Math.sin(wanderAngle) * 0.5;
