export const digestBasket = (state: GameState) => {
    const { player } = state;
    if (player.basket.length === 0) return;

    let totalWeightGain = 0;
    player.basket.forEach(item => {
        totalWeightGain += item.totalWeight;
    });

    player.weight += totalWeightGain;

    const currentMass = player.radius * player.radius;
    const massGain = totalWeightGain * 5; 

    const newRadius = Math.sqrt(currentMass + massGain);
    player.radius = Math.min(GAME_MECHANICS.MAX_RADIUS, newRadius);

    player.basket = [];

    player.happyTimer = 90;
    player.speechBubble = { text: "消化完毕!", timer: 60, color: '#34d399' };
    player.renderScale = 1.3;

    for(let i=0; i<20; i++) {
        state.particles.push(createParticle(player.x, player.y, '#34d399'));
    }
};

