       ctx.fill();
       ctx.stroke();
    } else if (type === CreatureType.STINGRAY) {
       // Diamond Shape
       ctx.beginPath();
       ctx.moveTo(radius * 1.2, 0); // Nose
       ctx.lineTo(0, -radius * 1.2); // Left wing tip
       ctx.lineTo(-radius * 0.5, 0); // Tail base
       ctx.lineTo(0, radius * 1.2); // Right wing tip
       ctx.closePath();
       ctx.fill();
       ctx.stroke();
       // Tail
       ctx.beginPath();
       ctx.moveTo(-radius * 0.5, 0);
       const tailWag = Math.sin(visualTime * 0.3 + animOffset) * radius * 0.5;
       ctx.quadraticCurveTo(-radius * 1.5, tailWag, -radius * 2.5, 0);
       ctx.stroke();
    } else if (type === CreatureType.ELECTRIC_EEL) {
       // Long wavy body
       ctx.beginPath();
       const segments = 10;
       const segLen = radius * 0.4;
       let px = radius; 
       let py = 0;

       // Head
       ctx.ellipse(radius * 0.8, 0, radius*0.6, radius*0.5, 0, 0, Math.PI*2);
       ctx.fill();
       ctx.stroke();

       // Body segments
       ctx.beginPath();
       ctx.moveTo(radius * 0.8, 0);
       for(let i=1; i<=segments; i++) {
          const t = i / segments;
          const sway = Math.sin(visualTime * 0.4 - i * 0.8 + animOffset) * (radius * 0.5);
          const bx = (radius * 0.8) - i * segLen;
          const by = sway;
          ctx.lineTo(bx, by);
       }
       ctx.lineWidth = radius * 0.8;
       ctx.lineCap = 'round';
       ctx.strokeStyle = entity.config.color;
       ctx.stroke();

       // Electric Effect
       if (visualTime % 10 < 5) {
           ctx.strokeStyle = '#fef08a';
           ctx.lineWidth = 2;
           ctx.stroke();
       }
       ctx.lineWidth = 3; 
       ctx.strokeStyle = 'rgba(0,0,0,0.2)';

    } else if (type === CreatureType.TURTLE) {
       // Round Shell Body
       ctx.beginPath();
       ctx.arc(0, 0, radius, 0, Math.PI * 2);
       ctx.fill();
       ctx.stroke();

       // Shell pattern
       ctx.fillStyle = 'rgba(0,0,0,0.1)';
       ctx.beginPath();
       ctx.arc(0, 0, radius * 0.7, 0, Math.PI * 2);
       ctx.fill();

       // Hexagon pattern attempt
       ctx.strokeStyle = 'rgba(0,0,0,0.3)';
       ctx.beginPath();
       ctx.moveTo(radius * 0.5, 0);
       for(let i=0; i<6; i++) {
          const a = (Math.PI*2 * i)/6;
          ctx.lineTo(Math.cos(a)*radius*0.5, Math.sin(a)*radius*0.5);
       }
       ctx.closePath();
       ctx.stroke();

    } else if (type === CreatureType.HAMMERHEAD) {
        // Body
       ctx.beginPath();
       ctx.ellipse(0, 0, radius * bodyStretch, radius * 0.7, 0, 0, Math.PI * 2);
       ctx.fill();
       ctx.stroke();

       // Hammer Head
       ctx.save();
       ctx.translate(radius * 0.8, 0);
       ctx.fillStyle = entity.config.color;
       ctx.fillRect(-radius * 0.2, -radius * 1.0, radius * 0.5, radius * 2.0);
       ctx.strokeRect(-radius * 0.2, -radius * 1.0, radius * 0.5, radius * 2.0);
       ctx.restore();

       // Tail
       const tailWag = Math.sin(visualTime * 0.4 + animOffset) * 0.3;
       ctx.save();
       ctx.translate(-radius, 0);
       ctx.rotate(tailWag);
       ctx.beginPath();
       ctx.moveTo(0, 0);
       ctx.lineTo(-radius * 0.8, -radius * 0.6);
       ctx.lineTo(-radius * 0.8, radius * 0.6);
       ctx.closePath();
       ctx.fill();
       ctx.stroke();
       ctx.restore();

    } else if (type === CreatureType.NARWHAL) {
       // Body (Chubby)
       ctx.beginPath();
       ctx.ellipse(0, 0, radius * bodyStretch, radius * 0.8, 0, 0, Math.PI * 2);
       ctx.fill();
       ctx.stroke();

       // Tusk
       ctx.fillStyle = '#e2e8f0'; // Light grey horn
       ctx.beginPath();
       ctx.moveTo(radius * 0.9, -radius * 0.2);
       ctx.lineTo(radius * 2.2, 0); // Long spike
       ctx.lineTo(radius * 0.9, radius * 0.2);
       ctx.fill();
       ctx.stroke();

       // Spiral detail on tusk
       ctx.beginPath();
       ctx.moveTo(radius * 1.0, -radius * 0.1);
       ctx.lineTo(radius * 2.0, 0);
       ctx.strokeStyle = '#94a3b8';
       ctx.stroke();

       // Tail
       const tailWag = Math.sin(visualTime * 0.4 + animOffset) * 0.3;
       ctx.save();
       ctx.translate(-radius * 0.8, 0);
       ctx.rotate(tailWag);
       ctx.fillStyle = entity.config.color;
       ctx.strokeStyle = 'rgba(0,0,0,0.2)';
       ctx.beginPath();
       ctx.moveTo(0, 0);
       ctx.lineTo(-radius * 0.6, -radius * 0.5);
       ctx.quadraticCurveTo(-radius * 0.3, 0, -radius * 0.6, radius * 0.5);
       ctx.closePath();
       ctx.fill();
       ctx.stroke();
       ctx.restore();

    } else if (type === CreatureType.MERMAID) {
       // Humanoid Upper Body
       ctx.fillStyle = '#fce7f3'; // Skin toneish
       ctx.beginPath();
       ctx.arc(radius * 0.2, 0, radius * 0.35, 0, Math.PI * 2); // Head/Torso overlap
       ctx.fill();

       // Hair
       ctx.fillStyle = '#db2777'; // Pink hair
       ctx.beginPath();
       ctx.arc(radius * 0.2, 0, radius * 0.4, Math.PI / 2, -Math.PI / 2, true);
       const hairFlow = Math.sin(visualTime * 0.3 + animOffset) * 0.2;
       ctx.lineTo(-radius * 0.5, -radius * 0.5 + hairFlow * 20);
       ctx.lineTo(-radius * 0.5, radius * 0.5 + hairFlow * 20);
       ctx.fill();

       // Fish Tail
       ctx.fillStyle = entity.config.color; // Cyan tail
       ctx.beginPath();
       ctx.moveTo(0, -radius * 0.35);
       ctx.lineTo(-radius * 1.2, -radius * 0.2); // Tail start
       ctx.lineTo(-radius * 1.2, radius * 0.2);
       ctx.lineTo(0, radius * 0.35);
       ctx.fill();
       ctx.stroke();

       // Fin
       const tailWag = Math.sin(visualTime * 0.5 + animOffset) * 0.4;
       ctx.save();
       ctx.translate(-radius * 1.2, 0);
       ctx.rotate(tailWag);
       ctx.beginPath();
       ctx.moveTo(0, 0);
       ctx.lineTo(-radius * 0.6, -radius * 0.6);
       ctx.lineTo(-radius * 0.6, radius * 0.6);
       ctx.closePath();
       ctx.fill();
       ctx.stroke();
       ctx.restore();

    } else if (type === CreatureType.AROWANA) {
       // Long body
       ctx.beginPath();
       ctx.ellipse(0, 0, radius * 1.3, radius * 0.5, 0, 0, Math.PI * 2);
       ctx.fill();
       ctx.stroke();

       // Scales
       ctx.strokeStyle = '#d97706'; // Darker gold
       ctx.lineWidth = 2;
       for(let i=0; i<3; i++) {
          ctx.beginPath();
          ctx.arc(-radius * 0.5 + i * radius * 0.6, 0, radius * 0.25, -Math.PI/2, Math.PI/2);
          ctx.stroke();
       }

       // Tail
       const tailWag = Math.sin(visualTime * 0.4 + animOffset) * 0.3;
       ctx.save();
       ctx.translate(-radius * 1.2, 0);
       ctx.rotate(tailWag);
       ctx.beginPath();
       ctx.moveTo(0, -radius * 0.2);
       ctx.lineTo(-radius * 0.4, -radius * 0.4);
       ctx.lineTo(-radius * 0.4, radius * 0.4);
       ctx.lineTo(0, radius * 0.2);
       ctx.fill();
       ctx.stroke();
       ctx.restore();

    } else if (type === CreatureType.FUR_SEAL) {
       // Sleek body
       ctx.beginPath();
       ctx.ellipse(0, 0, radius * 1.2, radius * 0.6, 0, 0, Math.PI * 2);
       ctx.fill();
       ctx.stroke();

       // Tail flippers
       const tailWag = Math.sin(visualTime * 0.6 + animOffset) * 0.3;
       ctx.save();
       ctx.translate(-radius * 1.1, 0);
       ctx.rotate(tailWag);
       ctx.beginPath();
       ctx.moveTo(0, 0);
       ctx.lineTo(-radius * 0.5, -radius * 0.3);
       ctx.lineTo(-radius * 0.5, radius * 0.3);
       ctx.closePath();
       ctx.fill();
       ctx.stroke();
       ctx.restore();

    } else {
       // Standard Fish Body
       ctx.beginPath();
       ctx.ellipse(0, 0, radius * bodyStretch, radius * 0.85, 0, 0, Math.PI * 2);
       ctx.fill();
       ctx.stroke(); 

       const tailWag = Math.sin(visualTime * 0.4 + animOffset) * 0.3;
       ctx.save();
       ctx.translate(-radius, 0);
       ctx.rotate(tailWag);
       ctx.beginPath();
       ctx.moveTo(0, 0);
       ctx.lineTo(-radius * 0.6, -radius * 0.5);
       ctx.lineTo(-radius * 0.6, radius * 0.5);
       ctx.closePath();
       ctx.fill();
       ctx.stroke();
       ctx.restore();
    }

    // -- Features (Eyes, Teeth, Lure) --

    if (type === CreatureType.ANGLER_FISH) {
       ctx.strokeStyle = "black";
       ctx.lineWidth = 2;
       ctx.beginPath();
       ctx.moveTo(radius * 0.5, -radius * 0.2);
       ctx.quadraticCurveTo(radius * 1.2, -radius * 0.8, radius * 1.5, -radius * 0.3);
       ctx.stroke();

       const lightX = radius * 1.5;
       const lightY = -radius * 0.3;
       const isLureActive = entity.lureActive;

       ctx.fillStyle = isLureActive ? "#fef08a" : "#4b5563";
       ctx.beginPath();
       ctx.arc(lightX, lightY, radius * 0.15, 0, Math.PI*2);
       ctx.fill();
       ctx.stroke();

       if (isLureActive) {
          ctx.shadowColor = "#fef08a";
          ctx.shadowBlur = 20 + Math.sin(visualTime * 0.2) * 10;
          ctx.fillStyle = "rgba(254, 240, 138, 0.5)";
          ctx.beginPath();
          ctx.arc(lightX, lightY, radius * 0.3, 0, Math.PI*2);
          ctx.fill();
          ctx.shadowBlur = 0; 
       }
    }

    // --- MOUTH & TEETH (RE-ADDED & ENHANCED) ---
    // Added logic for opening mouth and showing teeth/buckteeth
    if (type !== CreatureType.PLANKTON && type !== CreatureType.JELLYFISH && type !== CreatureType.STINGRAY) {
         ctx.save();

         // Mouth Position
         let mouthX = radius * 0.75;
         let mouthY = radius * 0.15;
         const mouthSize = radius * 0.25;

         if (type === CreatureType.HAMMERHEAD) { mouthX = radius * 0.6; }

         // Mouth Open Calculation
         const breath = Math.sin(visualTime * 0.1) * 0.05;
         const currentMouthOpen = Math.max(0, mouthOpenValue + breath);

         ctx.translate(mouthX, mouthY);

         // Draw Open Mouth
         if (currentMouthOpen > 0.1) {
             ctx.fillStyle = '#450a0a'; // Dark Red
             ctx.beginPath();
             ctx.ellipse(0, 0, mouthSize * 0.8, mouthSize * currentMouthOpen * 1.5, 0, 0, Math.PI * 2);
             ctx.fill();
         } else {
             // Closed Mouth Line
             ctx.beginPath();
             ctx.moveTo(0, 0);
             ctx.lineTo(-mouthSize, 0);
             ctx.strokeStyle = 'rgba(0,0,0,0.4)';
             ctx.lineWidth = 2;
             ctx.stroke();
         }

         // --- BUCKTEETH & FANGS ---
         // "Fierce Buckteeth" logic
         const isAggressive = (entity.config && entity.config.tier >= 2) || isAngry || type === CreatureType.ANGLER_FISH || type === CreatureType.CLOWN_FISH;

         if (isAggressive) {
             ctx.fillStyle = 'white';
             ctx.strokeStyle = 'rgba(0,0,0,0.1)';
             ctx.lineWidth = 1;

             const toothW = radius * 0.08;
             const toothH = radius * 0.12;

             // Two Sharp Upper Canines (Tiger Teeth)
             ctx.beginPath();

             // Left Canine
             ctx.moveTo(-toothW * 1.2, -toothH * 0.2); // Base Left
             ctx.lineTo(-toothW * 0.2, -toothH * 0.2); // Base Right
             ctx.lineTo(-toothW * 0.7, toothH * 1.2); // Tip (Sharp down)

             // Right Canine
             ctx.moveTo(toothW * 0.2, -toothH * 0.2); // Base Left
             ctx.lineTo(toothW * 1.2, -toothH * 0.2); // Base Right
             ctx.lineTo(toothW * 0.7, toothH * 1.2); // Tip

             ctx.fill();
             ctx.stroke();

             // Bottom Fangs (Only when mouth wide open) - interlocking
             if (currentMouthOpen > 0.4) {
                 ctx.beginPath();
                 // Left Bottom
                 ctx.moveTo(-toothW * 0.9, mouthSize * currentMouthOpen);
                 ctx.lineTo(-toothW * 0.4, mouthSize * currentMouthOpen);
                 ctx.lineTo(-toothW * 0.65, mouthSize * currentMouthOpen - toothH * 0.8); // Point Up

                 // Right Bottom
                 ctx.moveTo(toothW * 0.4, mouthSize * currentMouthOpen);
                 ctx.lineTo(toothW * 0.9, mouthSize * currentMouthOpen);
                 ctx.lineTo(toothW * 0.65, mouthSize * currentMouthOpen - toothH * 0.8); // Point Up

                 ctx.fill();
                 ctx.stroke();
             }
         }

         ctx.restore();
    }

    // --- ENHANCED EYES LOGIC (SIMPLIFIED & SYMMETRIC) ---
    if (type !== CreatureType.PLANKTON && type !== CreatureType.JELLYFISH && type !== CreatureType.STINGRAY) {
      // Reduced eye size slightly to avoid "panda eye" / big goggle look
      const eyeSizeBase = radius * 0.22; 
      let eyeX = radius * 0.3;
      let eyeYOffset = radius * 0.35;

      if (type === CreatureType.HAMMERHEAD) {
          eyeX = radius * 0.9;
          eyeYOffset = radius * 0.9; 
      }
      else if (type === CreatureType.ELECTRIC_EEL) {
          eyeX = radius * 0.9;
          eyeYOffset = radius * 0.2;
      }
      else if (type === CreatureType.NARWHAL) {
          eyeX = radius * 0.5;
          eyeYOffset = radius * 0.4;
      }
      else if (type === CreatureType.AROWANA) {
          eyeX = radius * 0.8;
          eyeYOffset = radius * 0.25;
      }

      const leftEyeSize = eyeSizeBase;
      const rightEyeSize = eyeSizeBase;

      // Blink Calculation
      const blinkSeed = entity.id.charCodeAt(0) * 13.0; 
      const blinkCycle = (visualTime + blinkSeed) % 300; 
      const isBlinking = blinkCycle < 15 && !isScared && !isAngry && !isHappy; 

      ctx.lineWidth = 1;
      ctx.strokeStyle = 'black';

      const drawEye = (x: number, y: number, size: number) => {
          // RESET DRAWING STATE FOR EACH EYE TO PREVENT STYLE LEAK
          ctx.fillStyle = 'white'; 
          ctx.lineWidth = 1;

          if (isHappy) {
              // ^ ^
              ctx.beginPath();
              ctx.lineWidth = 2;
              ctx.moveTo(x - size * 0.5, y);
              ctx.quadraticCurveTo(x, y - size * 0.6, x + size * 0.5, y);
              ctx.stroke();
          } else if (isBlinking) {
              // - -
              ctx.beginPath();
              ctx.lineWidth = 2;
              ctx.moveTo(x - size * 0.5, y);
              ctx.lineTo(x + size * 0.5, y);
              ctx.stroke();
          } else if (isScared) {
              // O O (Standard size, just tiny pupil)
              ctx.beginPath();
              ctx.arc(x, y, size, 0, Math.PI * 2); 
              ctx.fill();
              ctx.stroke();

              // Tiny pupil shaking
              const shakeX = (Math.random() - 0.5) * size * 0.4;
              const shakeY = (Math.random() - 0.5) * size * 0.4;
              ctx.fillStyle = 'black';
              ctx.beginPath();
              ctx.arc(x + shakeX, y + shakeY, size * 0.15, 0, Math.PI * 2);
              ctx.fill();
          } else if (isAngry) {
              // > < (Slanted eyebrows)
              ctx.beginPath();
              ctx.arc(x, y, size, 0, Math.PI*2);
              ctx.fill();
              ctx.stroke();

              // Pupil focused forward
              ctx.fillStyle = 'black';
              ctx.beginPath();
              ctx.arc(x + size * 0.2, y, size * 0.25, 0, Math.PI * 2);
              ctx.fill();

              // Eyebrow
              ctx.lineWidth = 3;
              ctx.beginPath();
              ctx.moveTo(x - size * 0.5, y - size * 0.5);
              ctx.lineTo(x + size * 0.5, y);
              ctx.stroke();
          } else {
              // Normal
              ctx.beginPath();
              ctx.arc(x, y, size, 0, Math.PI * 2); 
              ctx.fill();
              ctx.stroke();

              // Pupil tracking
              let lookX = Math.cos(visualTime * 0.1 + animOffset) * size * 0.2;
              let lookY = Math.sin(visualTime * 0.2 + animOffset) * size * 0.2;

              // Look at target if exists
              if (entity.targetId) {
                 // We don't have target pos here easily without lookups, so just look forward/aggressive
                 lookX = size * 0.3;
                 lookY = 0;
              }

              // Draw Pupil
              ctx.fillStyle = 'black';
              ctx.beginPath();
              ctx.arc(x + lookX, y + lookY, size * 0.25, 0, Math.PI * 2);
              ctx.fill();
          }
      };

      drawEye(eyeX, -eyeYOffset, rightEyeSize);
      drawEye(eyeX, eyeYOffset, leftEyeSize);
    } 

    ctx.restore();
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const resize = () => {
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
    };
    window.addEventListener('resize', resize);
    resize();

    let animationFrameId: number;

    const render = () => {
        const { player, entities, particles, obstacles, powerUps, hazards, projectiles, portals, camera, worldWidth, worldHeight } = gameState;
        const visualTime = performance.now() / 16; 

        // Clear
        ctx.fillStyle = '#0f172a'; 
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        ctx.save();
        ctx.translate(canvas.width / 2, canvas.height / 2);
        ctx.scale(camera.zoom, camera.zoom);
        ctx.translate(-camera.x, -camera.y);

        // --- DRAW BIOME BACKGROUNDS ---
        Object.values(BIOME_CONFIGS).forEach(biome => {
             ctx.fillStyle = biome.color;
             // Draw Rect
             ctx.fillRect(biome.xRange[0], biome.yRange[0], biome.xRange[1] - biome.xRange[0], biome.yRange[1] - biome.yRange[0]);

             // Draw Label in center (Very large, faint)
             ctx.save();
             ctx.fillStyle = "rgba(255,255,255,0.05)";
             ctx.font = "bold 200px Arial";
             ctx.textAlign = "center";
             ctx.textBaseline = "middle";
             const cx = (biome.xRange[0] + biome.xRange[1]) / 2;
             const cy = (biome.yRange[0] + biome.yRange[1]) / 2;
             ctx.fillText(biome.name, cx, cy);
             ctx.restore();
        });

        // Draw World Bounds
        ctx.strokeStyle = '#334155';
        ctx.lineWidth = 10;
        ctx.strokeRect(0, 0, worldWidth, worldHeight);

        // PORTALS (Bottom Layer)
        if (portals) {
            portals.forEach(p => {
               ctx.save();
               ctx.translate(p.x, p.y);
               ctx.rotate(p.angle);

               // Glow
               ctx.shadowBlur = 30;
               ctx.shadowColor = '#d8b4fe';

               // Outer swirl
               ctx.lineWidth = 6;
               ctx.strokeStyle = '#a855f7';
               ctx.beginPath();
               // Spiral approximation
               for (let i = 0; i < 3; i++) {
                 const startAngle = (Math.PI * 2 * i) / 3;
                 ctx.arc(0, 0, p.radius * 0.8, startAngle, startAngle + Math.PI, false);
               }
               ctx.stroke();

               // Inner swirl (counter rotate)
               ctx.rotate(visualTime * -0.1);
               ctx.lineWidth = 4;
               ctx.strokeStyle = '#22d3ee';
               ctx.beginPath();
               ctx.arc(0, 0, p.radius * 0.4, 0, Math.PI * 1.5);
               ctx.stroke();

               // Center glow
               ctx.fillStyle = '#f0abfc';
               ctx.beginPath();
               ctx.arc(0, 0, p.radius * 0.2, 0, Math.PI * 2);
               ctx.fill();

               ctx.restore();
            });
        }

        // Obstacles
        obstacles.forEach(obs => {
           ctx.save();
           ctx.translate(obs.x, obs.y);
           if (obs.type === 'SEAWEED') {
              ctx.fillStyle = 'rgba(34, 197, 94, 0.4)'; // Darker Seaweed for swamp visibility
              // Waving effect
              ctx.beginPath();
              ctx.moveTo(0, 0);
              for(let i=0; i<5; i++) {
                   const y = -obs.radius * 2 * (i/5);
                   const x = Math.sin(visualTime * 0.1 + obs.x + i) * 20;
                   ctx.lineTo(x, y);
              }
              ctx.strokeStyle = '#4d7c0f';
              ctx.lineWidth = obs.radius;
              ctx.lineCap = 'round';
              ctx.stroke();

           } else if (obs.type === 'CORAL') {
              ctx.fillStyle = '#f43f5e';
              ctx.beginPath();
              ctx.arc(0, 0, obs.radius, 0, Math.PI * 2);
              ctx.fill();
              // Details
              ctx.fillStyle = 'rgba(255,255,255,0.2)';
              ctx.beginPath();
              ctx.arc(obs.radius*0.3, -obs.radius*0.3, obs.radius*0.2, 0, Math.PI*2);
              ctx.fill();
           } else {
              // Rock
              ctx.fillStyle = '#475569';
              ctx.beginPath();
              ctx.arc(0, 0, obs.radius, 0, Math.PI * 2);
              ctx.fill();
              // Cracks
              ctx.strokeStyle = '#334155';
              ctx.lineWidth = 3;
              ctx.beginPath();
              ctx.moveTo(-obs.radius*0.5, 0);
              ctx.lineTo(0, obs.radius*0.3);
              ctx.lineTo(obs.radius*0.4, -obs.radius*0.2);
              ctx.stroke();
           }
           ctx.restore();
        });

        // Hazards
        hazards.forEach(h => {
             if (h.stage !== 'COOLDOWN') {
                 ctx.save();
                 ctx.translate(h.x, h.y);
                 ctx.fillStyle = 'rgba(239, 68, 68, 0.1)';
                 ctx.beginPath();
                 ctx.arc(0, 0, h.radius, 0, Math.PI * 2);
                 ctx.fill();
                 if (h.stage === 'WARNING') {
                     ctx.strokeStyle = `rgba(239, 68, 68, ${0.5 + Math.sin(visualTime * 0.2) * 0.5})`;
                     ctx.lineWidth = 5;
                     ctx.stroke();
                 }
                 ctx.restore();
             }
        });

        // PowerUps
        powerUps.forEach(p => {
            ctx.save();
            ctx.translate(p.x, p.y);
            ctx.fillStyle = p.type === 'SPEED' ? '#fde047' : (p.type === 'SHIELD' ? '#06b6d4' : '#f87171');
            ctx.shadowColor = ctx.fillStyle;
            ctx.shadowBlur = 15;
            ctx.beginPath();
            ctx.arc(0, 0, p.radius, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();
        });

        // Projectiles
        projectiles.forEach(p => {
            ctx.save();
            ctx.translate(p.x, p.y);
            ctx.rotate(p.angle);
            ctx.fillStyle = '#f87171';
            ctx.beginPath();
            ctx.rect(-10, -3, 20, 6);
            ctx.fill();
            ctx.restore();
        });

        // Particles
        particles.forEach(p => {
             ctx.save();
             ctx.translate(p.x, p.y);
             ctx.fillStyle = p.color;
             ctx.globalAlpha = p.life;
             ctx.beginPath();
             ctx.arc(0, 0, p.size, 0, Math.PI * 2);
             ctx.fill();
             ctx.restore();
        });

        // Entities
        entities.forEach(e => {
            if (!e.isHidden) {
                drawCuteFish(ctx, e, visualTime, false);
                if (e.speechBubble) drawSpeechBubble(ctx, e);
            }
        });

        // Player
        drawCuteFish(ctx, player, visualTime, true);
        if (player.speechBubble) drawSpeechBubble(ctx, player);

        ctx.restore();

        animationFrameId = requestAnimationFrame(render);
    };

    const drawSpeechBubble = (ctx: CanvasRenderingContext2D, e: Entity | PlayerState) => {
