export const createBuildings = (): Building[] => {
    const buildings: Building[] = [];

    // Helper to spawn in biome
    const spawn = (type: BuildingType, biome: BiomeType, count: number) => {
        const conf = BUILDING_CONFIGS[type];
        for(let i=0; i<count; i++) {
