// --- MAP GEOMETRY ---
// Returns the maximum radius allowed at a given angle (from center)
// Creates a 4-leaf clover / petal shape
export const getMapBoundaryRadius = (angle: number): number => {
    // 4 petals. Peaks at PI/4, 3PI/4, etc.
    // sin(2*angle) is 0 at 0, 90, 180. 1 at 45, 135.
    // We want corners to be far, axes to be close.
    // Use abs(sin(2*theta)) to get 4 lobes
    const variance = MAP_SHAPE_CONFIG.PETAL_VARIANCE * Math.abs(Math.sin(2 * angle));
    return MAP_SHAPE_CONFIG.BASE_RADIUS + variance;
};

// Check if position is inside the flower map
const isPositionValid = (x: number, y: number, buffer: number = 0): boolean => {
    const cx = MAP_SHAPE_CONFIG.CENTER_X;
    const cy = MAP_SHAPE_CONFIG.CENTER_Y;
    const dx = x - cx;
    const dy = y - cy;
    const distance = Math.hypot(dx, dy);
    const angle = Math.atan2(dy, dx);
    const maxR = getMapBoundaryRadius(angle);
    return distance < maxR - buffer;
};

// Clamp position to flower boundary
const clampToMap = (entity: {x: number, y: number, radius: number, angle: number, vx?: number, vy?: number}) => {
    const cx = MAP_SHAPE_CONFIG.CENTER_X;
    const cy = MAP_SHAPE_CONFIG.CENTER_Y;
    const dx = entity.x - cx;
    const dy = entity.y - cy;
    const dist = Math.hypot(dx, dy);
    const angle = Math.atan2(dy, dx);

    const limit = getMapBoundaryRadius(angle) - entity.radius;

    if (dist > limit) {
        // Push back inside
        entity.x = cx + Math.cos(angle) * limit;
        entity.y = cy + Math.sin(angle) * limit;

        // Bounce Angle logic?
        // Normal vector at boundary is roughly towards center (approximation)
        // Reflect velocity if it exists
        if (entity.vx !== undefined && entity.vy !== undefined) {
             // Simple bounce: reverse velocity
             entity.vx *= -0.5;
             entity.vy *= -0.5;
             // Adjust facing angle
             entity.angle += Math.PI;
        }
    }
};

// --- BIOME LOGIC ---
const getBiome = (x: number, y: number): BiomeType => {
  const half = WORLD_SIZE / 2;
  // Biomes are still quadrants, matching the petals
  if (x < half && y < half) return BiomeType.SHALLOWS;
  if (x >= half && y < half) return BiomeType.REEF;
  if (x < half && y >= half) return BiomeType.SWAMP;
  return BiomeType.ABYSS;
};

// Returns a valid coordinate inside the specified biome petal
const getRandomPosInBiome = (biome: BiomeType) => {
    // Biome centers are roughly at diagonals
    let baseAngle = 0;
    if (biome === BiomeType.SHALLOWS) baseAngle = -3 * Math.PI / 4; // Top Left (225 deg)
    else if (biome === BiomeType.REEF) baseAngle = -Math.PI / 4;    // Top Right (315 deg)
    else if (biome === BiomeType.SWAMP) baseAngle = 3 * Math.PI / 4; // Bottom Left (135 deg)
    else baseAngle = Math.PI / 4;                                   // Bottom Right (45 deg)

    // Pick a distance within the petal
    // Max radius at this angle is roughly Base + Variance
    const maxR = MAP_SHAPE_CONFIG.BASE_RADIUS + MAP_SHAPE_CONFIG.PETAL_VARIANCE * 0.8;
    const r = 500 + Math.random() * (maxR - 800);
    // Add some angle jitter
    const a = baseAngle + (Math.random() - 0.5) * 0.5;

    return {
        x: MAP_SHAPE_CONFIG.CENTER_X + Math.cos(a) * r,
        y: MAP_SHAPE_CONFIG.CENTER_Y + Math.sin(a) * r
    };
};

