    spawn(BuildingType.SHRINE, BiomeType.SWAMP, 1);
    spawn(BuildingType.SHRINE, BiomeType.REEF, 1);
    spawn(BuildingType.SALON, BiomeType.SHALLOWS, 1); // New Salon in Shallows
    return buildings;
};

