    const w = m.width + 24;
    const h = 36;

    // Bubble shadow
    ctx.shadowBlur = 10;
    ctx.shadowColor = 'rgba(0,0,0,0.5)';

    ctx.fillStyle = 'rgba(255, 255, 255, 0.95)';
    ctx.strokeStyle = e.speechBubble.color;
    ctx.lineWidth = 3;

    drawRoundRect(ctx, -w/2, -h, w, h, 12);
    ctx.fill();
    ctx.stroke();

    // Text glow
    ctx.shadowBlur = 0;
    ctx.fillStyle = 'black';
    ctx.textAlign = 'center';
