const uuid = () => Math.random().toString(36).substr(2, 9);

// SAFE DISTANCE FUNCTION
const dist = (e1: {x: number, y: number}, e2: {x: number, y: number}) => {
  if (!e1 || !e2 || typeof e1.x !== 'number' || typeof e2.x !== 'number') return 999999;
  const dx = e1.x - e2.x;
  const dy = e1.y - e2.y;
