class SoundEngine {
  private ctx: AudioContext | null = null;

  private init() {
    if (!this.ctx) {
      this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }

  private createOscillator(freq: number, type: OscillatorType = 'sine', duration: number = 0.1, volume: number = 0.1) {
    this.init();
    if (!this.ctx) return;

    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = type;
    osc.frequency.setValueAtTime(freq, this.ctx.currentTime);

    gain.gain.setValueAtTime(volume, this.ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + duration);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start();
    osc.stop(this.ctx.currentTime + duration);
    return { osc, gain };
  }

  // 吞噬：滑稽的“啵”
  playEat() {
    const { osc } = this.createOscillator(150, 'sine', 0.15, 0.2)!;
    if (this.ctx) {
      osc.frequency.exponentialRampToValueAtTime(400, this.ctx.currentTime + 0.1);
    }
  }

  // 加速：滑稽的滑音
  playBoost() {
    const { osc } = this.createOscillator(300, 'triangle', 0.3, 0.1)!;
    if (this.ctx) {
      osc.frequency.exponentialRampToValueAtTime(900, this.ctx.currentTime + 0.3);
    }
  }

  // 惊吓：颤抖的高音
  playScared() {
    this.createOscillator(880, 'sawtooth', 0.05, 0.05);
    setTimeout(() => this.createOscillator(932, 'sawtooth', 0.05, 0.05), 50);
    setTimeout(() => this.createOscillator(880, 'sawtooth', 0.05, 0.05), 100);
  }

  // 进化：成功的旋律
  playEvolve() {
    const now = this.ctx?.currentTime || 0;
    const notes = [440, 554, 659, 880];
    notes.forEach((freq, i) => {
      setTimeout(() => {
        this.createOscillator(freq, 'square', 0.1, 0.1);
      }, i * 100);
    });
  }

  // 撞击：咚！
  playHit() {
    this.createOscillator(100, 'sine', 0.2, 0.3);
  }

  // 死亡：滑稽的下行音
  playGameOver() {
    const { osc } = this.createOscillator(400, 'sawtooth', 0.6, 0.2)!;
    if (this.ctx) {
      osc.frequency.linearRampToValueAtTime(50, this.ctx.currentTime + 0.6);
    }
  }
}

export const sounds = new SoundEngine();
