class SoundEngine {
  private ctx: AudioContext | null = null;

  private init() {
    if (!this.ctx) {
      this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }

  private createOscillator(freq: number, type: OscillatorType = 'sine', duration: number = 0.1, volume: number = 0.1) {
    this.init();
    if (!this.ctx) return;

    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = type;
    osc.frequency.setValueAtTime(freq, this.ctx.currentTime);

    gain.gain.setValueAtTime(volume, this.ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + duration);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start();
    osc.stop(this.ctx.currentTime + duration);
    return { osc, gain };
  }

  // 吞噬：滑稽的“啵”音，加入随机音调使其听起来更有趣
  playEat() {
    const pitch = 150 + Math.random() * 200;
    const { osc } = this.createOscillator(pitch, 'sine', 0.15, 0.25)!;
    if (this.ctx) {
      osc.frequency.exponentialRampToValueAtTime(pitch * 2.5, this.ctx.currentTime + 0.12);
    }
  }

  // 加速：滑稽的滑笛（Slide Whistle）效果
  playBoost() {
    const { osc } = this.createOscillator(200, 'triangle', 0.4, 0.15)!;
    if (this.ctx) {
      osc.frequency.linearRampToValueAtTime(1200, this.ctx.currentTime + 0.4);
    }
  }

  // 惊吓：类似于受惊尖叫的颤音
  playScared() {
    const now = this.ctx?.currentTime || 0;
    for(let i=0; i<3; i++) {
        setTimeout(() => {
            const { osc } = this.createOscillator(1000 + (i*100), 'sawtooth', 0.04, 0.05)!;
            if (this.ctx) osc.frequency.exponentialRampToValueAtTime(1500, this.ctx.currentTime + 0.04);
        }, i * 40);
    }
  }

  // 进化：明快搞笑的胜利旋律
  playEvolve() {
    const notes = [523, 659, 784, 1046]; // C5, E5, G5, C6
    notes.forEach((freq, i) => {
      setTimeout(() => {
        this.createOscillator(freq, 'square', 0.15, 0.1);
      }, i * 80);
    });
  }

  // 撞击：沉闷的咚
  playHit() {
    this.createOscillator(80, 'sine', 0.2, 0.4);
    this.createOscillator(120, 'triangle', 0.1, 0.2);
  }

  // 死亡：滑稽的“呜呜~”下滑音
  playGameOver() {
    const { osc } = this.createOscillator(500, 'sawtooth', 1.0, 0.2)!;
    if (this.ctx) {
      osc.frequency.exponentialRampToValueAtTime(40, this.ctx.currentTime + 1.0);
    }
  }
}

export const sounds = new SoundEngine();
