const updateAI = (entity: Entity, state: GameState) => {
  const { player } = state;
  if (entity.isMascot) {
      entity.angle = Math.atan2(player.y - entity.y, player.x - entity.x);
      return;
  }
  if (entity.type === CreatureType.PLANKTON) {
      entity.x += Math.cos(entity.angle)*0.5;
      entity.y += Math.sin(entity.angle)*0.5;
      if (Math.random() < 0.01) entity.angle += (Math.random()-0.5);
      return;
  }
  // 基础AI：捕食比自己小的，躲避比自己大的
  const d = dist(entity, player);
  if (d < 800) {
      const angleToPlayer = Math.atan2(player.y - entity.y, player.x - entity.x);
      if (player.radius > entity.radius * 1.1) {
          entity.angle = angleToPlayer + Math.PI; // 逃跑
      } else if (player.radius < entity.radius * 0.9) {
          entity.angle = angleToPlayer; // 追击
      }
