  entity.x += Math.cos(entity.angle) * entity.speed;
  entity.y += Math.sin(entity.angle) * entity.speed;

  if (entity.speechBubble) {
      entity.speechBubble.timer--;
      if (entity.speechBubble.timer <= 0) entity.speechBubble = null;
