const processCollision = (attacker: Entity | PlayerState, victim: Entity | PlayerState, state: GameState) => {
  if (dist(attacker, victim) > attacker.radius + victim.radius) return;

  // 吞噬逻辑
  if (attacker.radius > victim.radius * 1.1) {
      victim.health = 0;
      attacker.radius = Math.min(GAME_MECHANICS.MAX_RADIUS, Math.sqrt(attacker.radius * attacker.radius + victim.radius * victim.radius * 0.5));
      if (attacker.id === 'player') {
          sounds.playEat();
          const p = attacker as PlayerState;
          p.weight += victim.config.weightValue;
          p.eatenHistory[victim.type] = (p.eatenHistory[victim.type] || 0) + 1;
      }
  } else {
      // 撞击逻辑
      const angle = Math.atan2(attacker.y - victim.y, attacker.x - victim.x);
      attacker.x += Math.cos(angle) * 5;
      attacker.y += Math.sin(angle) * 5;
  }
};

export const updateGame = (state: GameState, mouse: {x: number, y: number}, isSpacePressed: boolean, isMouseDown: boolean, screenWidth: number, screenHeight: number): GameState => {
  // 核心拦截：非播放/菜单状态不执行逻辑
  if (state.status !== GameStatus.PLAYING && state.status !== GameStatus.MENU) return state;

  state.time++;

  if (state.status === GameStatus.PLAYING) {
      // 玩家移动逻辑
      const dx = mouse.x - screenWidth/2;
      const dy = mouse.y - screenHeight/2;
      const targetAngle = Math.atan2(dy, dx);
      let angleDiff = targetAngle - state.player.angle;
      while (angleDiff > Math.PI) angleDiff -= Math.PI * 2;
      while (angleDiff < -Math.PI) angleDiff += Math.PI * 2;
      state.player.angle += angleDiff * 0.1;

      let speedMult = 1.0;
      if (isSpacePressed && state.player.boost.current > 0) {
          if (!state.player.boost.active) sounds.playBoost();
          state.player.boost.active = true;
          state.player.boost.current -= 0.5;
          speedMult = 2.0;
      } else {
          state.player.boost.active = false;
          state.player.boost.current = Math.min(100, state.player.boost.current + 0.2);
      }

      state.player.x += Math.cos(state.player.angle) * state.player.speed * speedMult;
      state.player.y += Math.sin(state.player.angle) * state.player.speed * speedMult;

