      state.player.x = Math.max(0, Math.min(WORLD_SIZE, state.player.x));
      state.player.y = Math.max(0, Math.min(WORLD_SIZE, state.player.y));

      // 进化检测
      const nextType = getNextEvolution(state.player.type, state.player.eatenHistory, state.player.radius);
      if (nextType !== state.player.type) {
          state.player.type = nextType;
          state.player.config = CREATURES[nextType];
          sounds.playEvolve();
          state.player.evolutionVisualTimer = 120;
      }

      if (state.player.health <= 0 && state.time > 60) {
          state.status = GameStatus.GAME_OVER;
          sounds.playGameOver();
      }
  }

  // 环境更新
  if (state.entities.length < MAX_ENTITIES) {
      const type = Math.random() < 0.7 ? CreatureType.PLANKTON : CreatureType.CLOWN_FISH;
      state.entities.push(createEntity(type, Math.random()*WORLD_SIZE, Math.random()*WORLD_SIZE));
  }

  state.entities.forEach(ent => {
      updateAI(ent, state);
      if (state.status === GameStatus.PLAYING) {
          processCollision(state.player, ent, state);
          processCollision(ent, state.player, state);
      }
  });

  state.entities = state.entities.filter(e => e.health > 0);

  spawnPowerUps(state);

  // 摄像机跟随
  state.camera.x += (state.player.x - state.camera.x) * 0.1;
  state.camera.y += (state.player.y - state.camera.y) * 0.1;
  state.camera.zoom = Math.max(0.4, 0.8 - state.player.radius/1000);

  return state;
};
