      reviveCount: 0, isIdle: false, lureActive: false, camoActive: false, ambushTimer: 0,
      shieldTimer: 0, invulnerableTimer: 0, evolutionVisualTimer: 0, torpedoCount: 0, torpedoCooldown: 0,
      isOverdrive: false, currentBiome: BiomeType.SHALLOWS, biomeDebuffTimer: 0,
      cosmetics: { teeth: 'NORMAL', skinColor: config.color, pattern: 'NONE', scaleType: 'NONE' }
    },
    entities: [], particles: [], obstacles: createObstacles(), powerUps: [], hazards: [], projectiles: [],
    portals: [], buildings: createBuildings(), worldWidth: WORLD_SIZE, worldHeight: WORLD_SIZE,
    camera: { x: WORLD_SIZE/2, y: WORLD_SIZE/2, zoom: 0.8 }, score: 0, genePoints: 0, time: 0
  };
};

const App: React.FC = () => {
  const gameStateRef = useRef<GameState>(createInitialState());
  const [uiState, setUiState] = useState<GameState>(gameStateRef.current);
  const mouseRef = useRef({ x: 0, y: 0 });
  const keysRef = useRef({ space: false });
  const isDownRef = useRef(false);
  const frameId = useRef(0);

  useEffect(() => {
    const itv = setInterval(() => setUiState({ ...gameStateRef.current }), 50);
    return () => clearInterval(itv);
  }, []);

  const loop = useCallback(() => {
    gameStateRef.current = updateGame(gameStateRef.current, mouseRef.current, keysRef.current.space, isDownRef.current, window.innerWidth, window.innerHeight);
    frameId.current = requestAnimationFrame(loop);
  }, []);

  useEffect(() => {
    frameId.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(frameId.current);
  }, [loop]);

  return (
    <div className="w-full h-screen overflow-hidden bg-slate-900 relative">
      <GameCanvas 
        gameState={gameStateRef.current} 
        onMouseMove={(x, y) => mouseRef.current = {x,y}} 
        onMouseDown={() => isDownRef.current = true}
        onMouseUp={() => isDownRef.current = false}
      />
      <UIOverlay 
        gameState={uiState}
        onStart={() => { gameStateRef.current.status = GameStatus.PLAYING; }}
        onRestart={() => { gameStateRef.current = createInitialState(); gameStateRef.current.status = GameStatus.PLAYING; }}
        setGameStatus={(s) => gameStateRef.current.status = s}
        onUpdateCosmetics={(cos) => { gameStateRef.current.player.cosmetics = { ...gameStateRef.current.player.cosmetics, ...cos }; }}
      />
    </div>
  );
