  special?: 'POISON' | 'SHOCK' | 'SPIKE' | 'LURE' | 'CAMO' | 'NONE' | 'SHELL';
  tier: 0 | 1 | 2 | 3 | 4;
  description?: string; // For selection menu
  nativeBiome?: BiomeType; // Preferred biome
}

export interface BasketItem {
  type: CreatureType;
  count: number;
  totalWeight: number;
}

