  | 'NORMAL' | 'SHARP' | 'VAMPIRE' | 'BRACES' | 'GOLD' 
  | 'CURVED' | 'DOUBLE_ROW' | 'SABER' | 'GAPPED' | 'DIAMOND' 
  | 'RAINBOW' | 'BUGS' | 'BLOCKY';

