});

const spawnHazards = (state: GameState) => {
    if (state.time % METEOR_CONFIG.INTERVAL === 0 && state.status === GameStatus.PLAYING) {
        state.hazards.push({
            id: uuid(), x: state.player.x + (Math.random()-0.5)*800, y: state.player.y + (Math.random()-0.5)*800,
            radius: METEOR_CONFIG.RADIUS, type: 'METEOR_STRIKE', timer: METEOR_CONFIG.WARNING_TIME,
            duration: METEOR_CONFIG.WARNING_TIME + METEOR_CONFIG.STRIKE_TIME, stage: 'WARNING'
        });
    }
};

const spawnPortals = (state: GameState) => {
    if (state.portals.length < PORTAL_CONFIG.MAX_COUNT && Math.random() < PORTAL_CONFIG.SPAWN_CHANCE) {
        state.portals.push({
            id: uuid(), x: Math.random() * WORLD_SIZE, y: Math.random() * WORLD_SIZE,
            radius: PORTAL_CONFIG.RADIUS, timer: PORTAL_CONFIG.DURATION, angle: 0
        });
    }
};

const updateHazards = (state: GameState) => {
    state.hazards.forEach(h => {
        h.timer--;
        if (h.timer === 0) {
            h.stage = 'STRIKE';
            sounds.playHit();
            if (dist(state.player, h) < h.radius) state.player.health -= 50;
            for(let i=0; i<15; i++) state.particles.push(createParticle(h.x, h.y, '#f59e0b'));
