              state.player.y = Math.random() * WORLD_SIZE;
              state.player.speechBubble = { text: "时空跳跃!", timer: 60, color: '#a855f7' };
              for(let i=0; i<20; i++) state.particles.push(createParticle(state.player.x, state.player.y, '#a855f7'));
              p.timer = 0; // 传送后销毁
