      if (state.player.health <= 0) {
          state.status = GameStatus.GAME_OVER;
          sounds.playGameOver();
      }
  }

  // 环境与 NPC 更新
  if (state.entities.length < MAX_ENTITIES) {
      state.entities.push(createEntity(CreatureType.PLANKTON, Math.random()*WORLD_SIZE, Math.random()*WORLD_SIZE));
  }

