class SoundEngine {
  private ctx: AudioContext | null = null;

  private init() {
    if (!this.ctx) {
      this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }

  private createOscillator(freq: number, type: OscillatorType = 'sine', duration: number = 0.1, volume: number = 0.1) {
    this.init();
    if (!this.ctx) return;

    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = type;
    osc.frequency.setValueAtTime(freq, this.ctx.currentTime);

    gain.gain.setValueAtTime(volume, this.ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + duration);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start();
    osc.stop(this.ctx.currentTime + duration);
    return { osc, gain };
  }

  playEat() {
    const pitch = 150 + Math.random() * 100;
    const { osc } = this.createOscillator(pitch, 'sine', 0.15, 0.2)!;
    if (this.ctx) {
      osc.frequency.exponentialRampToValueAtTime(pitch * 2, this.ctx.currentTime + 0.1);
    }
  }

  // 加速声：改短、改低、改柔和
  playBoost() {
    const { osc } = this.createOscillator(100, 'sine', 0.2, 0.08)!;
    if (this.ctx) {
      osc.frequency.linearRampToValueAtTime(300, this.ctx.currentTime + 0.2);
    }
  }

  playEvolve() {
    const notes = [523, 659, 784, 1046];
    notes.forEach((freq, i) => {
      setTimeout(() => {
        this.createOscillator(freq, 'triangle', 0.2, 0.05);
      }, i * 80);
    });
  }

  playHit() {
    this.createOscillator(80, 'sine', 0.2, 0.3);
  }

  playGameOver() {
    const { osc } = this.createOscillator(400, 'sawtooth', 0.8, 0.1)!;
    if (this.ctx) {
      osc.frequency.exponentialRampToValueAtTime(40, this.ctx.currentTime + 0.8);
    }
  }
}

export const sounds = new SoundEngine();
