import { CREATURES, WORLD_SIZE, MAX_ENTITIES, BOOST_CONFIG, MAX_OBSTACLES, GAME_MECHANICS, MAX_POWERUPS, METEOR_CONFIG, EVOLUTION_THRESHOLDS, BUILDING_CONFIGS, BIOME_CONFIGS, MAP_SHAPE_CONFIG, PORTAL_CONFIG } from './constants';
import { CreatureType, Entity, GameState, GameStatus, Obstacle, Particle, PlayerState, PowerUp, Hazard, Portal, Building, BuildingType, Cosmetics } from './types';
import { sounds } from './soundEngine';

const uuid = () => Math.random().toString(36).substr(2, 9);

const dist = (e1: {x: number, y: number}, e2: {x: number, y: number}) => Math.hypot(e1.x - e2.x, e1.y - e2.y);

export const getMapBoundaryRadius = (angle: number): number => {
  const { BASE_RADIUS, PETAL_VARIANCE } = MAP_SHAPE_CONFIG;
  return BASE_RADIUS + Math.sin(angle * 5) * PETAL_VARIANCE;
};

const getDefaultCosmetics = (type: CreatureType): Cosmetics => ({
  teeth: 'NORMAL',
  skinColor: CREATURES[type].color,
  pattern: 'NONE',
  eyeType: 'NORMAL',
  tailType: 'NORMAL'
});

export const createEntity = (type: CreatureType, x: number, y: number): Entity => {
  const config = CREATURES[type];
  return {
    id: uuid(), type, x, y, vx: 0, vy: 0, radius: config.baseRadius, angle: Math.random() * Math.PI * 2,
    health: config.health, maxHealth: config.health, speed: config.speed, config,
    mouthOpenValue: 0, isHidden: false, isIdle: false, lureActive: false, camoActive: false, ambushTimer: 0,
    animOffset: Math.random() * 100, renderScale: 1.0, isInvulnerable: false, aggroTimer: 0,
    speedBoostTimer: 0, happyTimer: 0, fearTimer: 0, speechBubble: null, evolutionVisualTimer: 0,
    cosmetics: getDefaultCosmetics(type)
  };
};

export const createObstacles = (): Obstacle[] => {
  const obs: Obstacle[] = [];
  for (let i = 0; i < MAX_OBSTACLES; i++) {
    const angle = Math.random() * Math.PI * 2;
    const d = 300 + Math.random() * 2500;
    obs.push({ id: uuid(), x: WORLD_SIZE/2 + Math.cos(angle)*d, y: WORLD_SIZE/2 + Math.sin(angle)*d, radius: 60 + Math.random()*150, type: Math.random() < 0.5 ? 'ROCK' : 'SEAWEED' });
  }
  return obs;
};

export const createBuildings = (): Building[] => [
  { id: uuid(), type: BuildingType.HOSPITAL, x: WORLD_SIZE*0.3, y: WORLD_SIZE*0.3, radius: 200 },
  { id: uuid(), type: BuildingType.ARMORY, x: WORLD_SIZE*0.7, y: WORLD_SIZE*0.3, radius: 200 },
  { id: uuid(), type: BuildingType.SALON, x: WORLD_SIZE*0.5, y: WORLD_SIZE*0.7, radius: 200 }
];

export const createParticle = (x: number, y: number, color: string): Particle => ({
  id: uuid(), x, y, vx: (Math.random()-0.5)*4, vy: (Math.random()-0.5)*4, life: 1.0, maxLife: 1.0, color, size: 2+Math.random()*3
});

const spawnHazards = (state: GameState) => {
    if (state.time % METEOR_CONFIG.INTERVAL === 0 && state.status === GameStatus.PLAYING) {
        state.hazards.push({
            id: uuid(), x: state.player.x + (Math.random()-0.5)*800, y: state.player.y + (Math.random()-0.5)*800,
            radius: METEOR_CONFIG.RADIUS, type: 'METEOR_STRIKE', timer: METEOR_CONFIG.WARNING_TIME,
            duration: METEOR_CONFIG.WARNING_TIME + METEOR_CONFIG.STRIKE_TIME, stage: 'WARNING'
        });
    }
};

const spawnEntities = (state: GameState) => {
    if (state.entities.length < MAX_ENTITIES) {
        const r = Math.random();
        let type = CreatureType.PLANKTON;
        if (r > 0.4) type = CreatureType.CLOWN_FISH;
        if (r > 0.6) type = CreatureType.JELLYFISH;
        if (r > 0.8) type = CreatureType.ELECTRIC_EEL;
        if (r > 0.95) type = CreatureType.STINGRAY;

        state.entities.push(createEntity(type, Math.random() * WORLD_SIZE, Math.random() * WORLD_SIZE));
    }
};

export const updateGame = (state: GameState, mouse: {x: number, y: number}, isSpace: boolean, isDown: boolean, sw: number, sh: number): GameState => {
  // 即使在商店也保持 NPC 的活动，防止“空城”
  spawnEntities(state);

  if (state.status === GameStatus.SHOP) {
      // 在商店模式下，玩家不移动，但粒子和 NPC 应该继续更新以保持视觉活跃
      updateNPCs(state);
      updateParticles(state);
      return state;
  }

  if (state.status !== GameStatus.PLAYING && state.status !== GameStatus.MENU) return state;

  state.time++;

  if (state.status === GameStatus.PLAYING) {
      const dx = mouse.x - sw/2;
      const dy = mouse.y - sh/2;
      const targetAngle = Math.atan2(dy, dx);
      let diff = targetAngle - state.player.angle;
      while (diff > Math.PI) diff -= Math.PI*2;
      while (diff < -Math.PI) diff += Math.PI*2;
      state.player.angle += diff * 0.1;

      let speedMult = 1.0;
      if (isSpace && state.player.boost.current > 0) {
          if (!state.player.boost.active) sounds.playBoost();
          state.player.boost.active = true;
          state.player.boost.current -= BOOST_CONFIG.DRAIN_RATE;
          speedMult = BOOST_CONFIG.SPEED_MULTIPLIER;
          if (state.time % 4 === 0) state.particles.push(createParticle(state.player.x, state.player.y, 'rgba(255,255,255,0.3)'));
      } else {
          state.player.boost.active = false;
          state.player.boost.current = Math.min(100, state.player.boost.current + BOOST_CONFIG.REGEN_RATE);
      }

      if (state.player.y > WORLD_SIZE * 0.7) state.player.x += 2.5;

      state.player.x += Math.cos(state.player.angle) * state.player.speed * speedMult;
      state.player.y += Math.sin(state.player.angle) * state.player.speed * speedMult;
      state.player.x = Math.max(0, Math.min(WORLD_SIZE, state.player.x));
      state.player.y = Math.max(0, Math.min(WORLD_SIZE, state.player.y));

      state.buildings.forEach(b => {
          if (dist(state.player, b) < b.radius) {
              if (b.type === BuildingType.SALON) {
                  state.status = GameStatus.SHOP;
              } else if (b.type === BuildingType.HOSPITAL) {
                  state.player.health = Math.min(state.player.maxHealth, state.player.health + 0.5);
              } else if (b.type === BuildingType.ARMORY) {
                  state.player.torpedoCount = 5;
              }
          }
      });

      if (state.player.invulnerableTimer > 0) state.player.invulnerableTimer--;
      else state.player.isInvulnerable = false;

      if (state.player.health <= 0) {
          state.status = GameStatus.GAME_OVER;
          sounds.playGameOver();
      }
  }

  updateNPCs(state);
  updateParticles(state);
  spawnHazards(state);

  state.camera.x += (state.player.x - state.camera.x) * 0.1;
  state.camera.y += (state.player.y - state.camera.y) * 0.1;
  state.camera.zoom = Math.max(0.4, 0.8 - state.player.radius/1000);

  return state;
};

const updateNPCs = (state: GameState) => {
    state.entities.forEach(ent => {
        if (ent.y > WORLD_SIZE * 0.7) ent.x += 1.5;
        const d = dist(ent, state.player);
        if (d < 500) {
            const ang = Math.atan2(state.player.y - ent.y, state.player.x - ent.x);
            ent.angle = state.player.radius > ent.radius ? ang + Math.PI : ang;
        }
        ent.x += Math.cos(ent.angle) * ent.speed;
        ent.y += Math.sin(ent.angle) * ent.speed;

        if (state.status === GameStatus.PLAYING && d < ent.radius + state.player.radius) {
            if (state.player.radius > ent.radius * 1.1) {
                ent.health = 0;
                state.player.radius = Math.min(GAME_MECHANICS.MAX_RADIUS, Math.sqrt(state.player.radius**2 + ent.radius**2 * 0.5));
                state.player.weight += ent.config.weightValue;
                sounds.playEat();
            } else if (ent.radius > state.player.radius * 1.2 && !state.player.isInvulnerable) {
                state.player.health -= 0.5;
                if (state.time % 40 === 0) sounds.playHit();
            }
        }
    });
    state.entities = state.entities.filter(e => e.health > 0);
};

const updateParticles = (state: GameState) => {
    state.particles.forEach(p => { p.x += p.vx; p.y += p.vy; p.life -= 0.02; });
    state.particles = state.particles.filter(p => p.life > 0);
};
