      default:
        ctx.moveTo(0, 0); ctx.lineTo(-radius * 0.8, -radius * 0.6); ctx.lineTo(-radius * 0.8, radius * 0.6);
    }
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  };

