        ctx.save();
        ctx.translate(x, y);
        ctx.fillStyle = 'white';
        ctx.beginPath();
        switch(type) {
            case 'ANGRY': ctx.moveTo(-5, -5); ctx.lineTo(10, 5); ctx.lineTo(-5, 10); break;
            case 'CUTE': ctx.arc(0, 0, radius * 0.25, 0, Math.PI*2); break;
            case 'DEAD': ctx.moveTo(-5, -5); ctx.lineTo(5, 5); ctx.moveTo(5, -5); ctx.lineTo(-5, 5); break;
