import React, { useRef, useEffect } from 'react';
import { GameState, Entity, CreatureType, Obstacle, PlayerState, Building, BuildingType, Cosmetics, EyeType, TailType, PatternType } from '../types';
import { WORLD_SIZE } from '../constants';

interface GameCanvasProps {
  gameState: GameState;
  onMouseMove: (x: number, y: number) => void;
  onMouseDown: () => void;
  onMouseUp: () => void;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ gameState, onMouseMove, onMouseDown, onMouseUp }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const drawTail = (ctx: CanvasRenderingContext2D, radius: number, color: string, type: TailType) => {
    ctx.save();
    ctx.translate(-radius * 0.8, 0);
    ctx.fillStyle = color;
    ctx.beginPath();
    switch(type) {
      case 'LONG': ctx.moveTo(0,0); ctx.lineTo(-radius*1.8, -radius*0.2); ctx.lineTo(-radius*1.8, radius*0.2); break;
      case 'FORKED': ctx.moveTo(0,0); ctx.lineTo(-radius, -radius); ctx.lineTo(-radius*0.5, 0); ctx.lineTo(-radius, radius); break;
      case 'ROUND': ctx.arc(-radius*0.3, 0, radius*0.7, 0, Math.PI*2); break;
      case 'FAN': ctx.moveTo(0,0); ctx.arc(0,0, radius, Math.PI*0.8, Math.PI*1.2); break;
      case 'RIBBON': ctx.moveTo(0,0); ctx.quadraticCurveTo(-radius*2, -radius, -radius*3, 0); ctx.quadraticCurveTo(-radius*2, radius, 0,0); break;
      case 'HEART': ctx.moveTo(0,0); ctx.bezierCurveTo(-radius, -radius, -radius*2, -radius/2, -radius, radius); break;
      case 'SQUARE': ctx.rect(-radius, -radius*0.6, radius, radius*1.2); break;
      case 'POINTY': ctx.moveTo(0,0); ctx.lineTo(-radius*1.5, 0); break;
      case 'STUBBY': ctx.moveTo(0,0); ctx.lineTo(-radius*0.5, -radius*0.4); ctx.lineTo(-radius*0.5, radius*0.4); break;
      default: ctx.moveTo(0,0); ctx.lineTo(-radius, -radius*0.7); ctx.lineTo(-radius, radius*0.7);
    }
    ctx.fill();
    ctx.restore();
  };

  const drawEyes = (ctx: CanvasRenderingContext2D, radius: number, type: EyeType) => {
    const drawEye = (x: number, y: number) => {
      ctx.save();
      ctx.translate(x, y);
      ctx.fillStyle = 'white';
      ctx.beginPath();
      switch(type) {
        case 'ANGRY': ctx.moveTo(-5, -5); ctx.lineTo(10, 5); ctx.lineTo(-5, 10); break;
        case 'CUTE': ctx.arc(0,0, radius*0.28, 0, Math.PI*2); break;
        case 'COOL': ctx.fillRect(-5, -2, 12, 4); break;
        case 'DEAD': ctx.moveTo(-5,-5); ctx.lineTo(5,5); ctx.moveTo(5,-5); ctx.lineTo(-5,5); break;
        case 'GLOW': ctx.shadowBlur = 10; ctx.shadowColor = 'cyan'; ctx.arc(0,0, radius*0.2, 0, Math.PI*2); break;
        case 'CYBORG': ctx.fillStyle = 'red'; ctx.fillRect(-4,-4,8,8); break;
        case 'BIG': ctx.arc(0,0, radius*0.4, 0, Math.PI*2); break;
        case 'SQUINT': ctx.fillRect(-8, 0, 16, 2); break;
        case 'DERP': ctx.arc(Math.random()*2, Math.random()*2, radius*0.2, 0, Math.PI*2); break;
        default: ctx.arc(0,0, radius*0.2, 0, Math.PI*2);
      }
      ctx.fill();
      if (['NORMAL', 'CUTE', 'BIG'].includes(type)) {
        ctx.fillStyle = 'black'; ctx.beginPath(); ctx.arc(1, 0, radius*0.12, 0, Math.PI*2); ctx.fill();
      }
      ctx.restore();
    };
    drawEye(radius*0.4, -radius*0.35);
    drawEye(radius*0.4, radius*0.35);
  };

  const drawBodyPattern = (ctx: CanvasRenderingContext2D, radius: number, type: PatternType) => {
    ctx.save();
    ctx.clip();
    ctx.strokeStyle = 'rgba(0,0,0,0.2)';
    ctx.lineWidth = 3;
    switch(type) {
      case 'STRIPES':
        for(let i=-radius; i<radius; i+=10) { ctx.beginPath(); ctx.moveTo(i, -radius); ctx.lineTo(i, radius); ctx.stroke(); }
        break;
      case 'SPOTS':
        for(let i=0; i<10; i++) { ctx.beginPath(); ctx.arc(Math.random()*radius*2-radius, Math.random()*radius*2-radius, 5, 0, Math.PI*2); ctx.stroke(); }
        break;
      case 'TIGER':
        ctx.lineWidth = 5;
        for(let i=-radius; i<radius; i+=20) { ctx.beginPath(); ctx.moveTo(i, -radius); ctx.quadraticCurveTo(i+10, 0, i, radius); ctx.stroke(); }
        break;
      case 'HEART':
        ctx.fillStyle = 'rgba(255,0,0,0.2)';
        ctx.fillText("❤", 0,0);
        break;
    }
    ctx.restore();
  };

  const drawCuteFish = (ctx: CanvasRenderingContext2D, entity: Entity) => {
    const { radius, angle, cosmetics } = entity;
    ctx.save();
    ctx.translate(entity.x, entity.y);
    ctx.rotate(angle);

    drawTail(ctx, radius, cosmetics.skinColor, cosmetics.tailType);

    ctx.fillStyle = cosmetics.skinColor;
    ctx.beginPath();
    ctx.arc(0,0, radius, 0, Math.PI*2);
    ctx.fill();

    drawBodyPattern(ctx, radius, cosmetics.pattern);
    drawEyes(ctx, radius, cosmetics.eyeType);

    if (cosmetics.teeth !== 'NORMAL') {
      ctx.fillStyle = cosmetics.teeth === 'GOLD' ? '#fbbf24' : 'white';
      ctx.beginPath();
      ctx.moveTo(radius*0.8, -radius*0.2);
      ctx.lineTo(radius, 0);
      ctx.lineTo(radius*0.8, radius*0.2);
      ctx.fill();
    }
    ctx.restore();
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let frameId: number;
    const render = () => {
      const { player, entities, particles, camera, buildings, obstacles } = gameState;
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.fillStyle = '#0f172a';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.translate(canvas.width / 2, canvas.height / 2);
      ctx.scale(camera.zoom, camera.zoom);
      ctx.translate(-camera.x, -camera.y);

      // 背景
      ctx.fillStyle = '#1e293b';
      ctx.fillRect(0,0, WORLD_SIZE, WORLD_SIZE);

      buildings.forEach(b => {
        ctx.fillStyle = b.type === BuildingType.SALON ? '#ec4899' : '#334155';
        ctx.beginPath(); ctx.arc(b.x, b.y, b.radius/2, 0, Math.PI*2); ctx.fill();
        if (b.type === BuildingType.SALON) {
          ctx.fillStyle = 'white'; ctx.font = "bold 40px Arial"; ctx.textAlign="center"; ctx.fillText("✂️", b.x, b.y+15);
        }
      });

      obstacles.forEach(o => {
        ctx.fillStyle = o.type === 'ROCK' ? '#475569' : '#065f46';
        ctx.beginPath(); ctx.arc(o.x, o.y, o.radius, 0, Math.PI*2); ctx.fill();
      });

      entities.forEach(e => drawCuteFish(ctx, e));
      drawCuteFish(ctx, player);

      particles.forEach(p => {
        ctx.globalAlpha = p.life; ctx.fillStyle = p.color;
        ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, Math.PI*2); ctx.fill();
      });
      ctx.globalAlpha = 1;

      frameId = requestAnimationFrame(render);
    };

    const handleResize = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    };

