import React, { useRef, useEffect } from 'react';
import { GameState, Entity, Cosmetics, EyeType, TailType, PatternType } from '../types';
import { WORLD_SIZE } from '../constants';

interface GameCanvasProps {
  gameState: GameState;
  onMouseMove: (x: number, y: number) => void;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ gameState, onMouseMove }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const drawTail = (ctx: CanvasRenderingContext2D, radius: number, color: string, type: TailType) => {
    ctx.save();
    ctx.translate(-radius * 0.8, 0);
    ctx.fillStyle = color;
    ctx.beginPath();
    switch(type) {
      case 'FORKED': ctx.moveTo(0,0); ctx.lineTo(-radius, -radius); ctx.lineTo(-radius*0.5, 0); ctx.lineTo(-radius, radius); break;
      case 'ROUND': ctx.arc(-radius*0.3, 0, radius*0.7, 0, Math.PI*2); break;
      case 'FAN': ctx.moveTo(0,0); ctx.arc(0,0, radius, Math.PI*0.8, Math.PI*1.2); break;
      case 'HEART': ctx.moveTo(0,0); ctx.bezierCurveTo(-radius, -radius, -radius*2, 0, 0, radius); break;
      case 'LONG': ctx.moveTo(0,0); ctx.lineTo(-radius*2, 0); break;
      case 'SQUARE': ctx.rect(-radius, -radius*0.5, radius, radius); break;
      default: ctx.moveTo(0,0); ctx.lineTo(-radius, -radius*0.7); ctx.lineTo(-radius, radius*0.7);
    }
    ctx.fill();
    ctx.restore();
  };

  const drawEyes = (ctx: CanvasRenderingContext2D, radius: number, type: EyeType) => {
    const drawEye = (x: number, y: number) => {
      ctx.save();
      ctx.translate(x, y);
      ctx.fillStyle = 'white';
      ctx.beginPath();
      switch(type) {
        case 'ANGRY': ctx.moveTo(-5,-5); ctx.lineTo(10,0); ctx.lineTo(-5,5); break;
        case 'DEAD': ctx.moveTo(-5,-5); ctx.lineTo(5,5); ctx.moveTo(5,-5); ctx.lineTo(-5,5); break;
        case 'GLOW': ctx.shadowBlur = 10; ctx.shadowColor = 'cyan'; ctx.arc(0,0, radius*0.2, 0, Math.PI*2); break;
        case 'COOL': ctx.fillRect(-5, -2, 12, 4); break;
        case 'BIG': ctx.arc(0,0, radius*0.3, 0, Math.PI*2); break;
        default: ctx.arc(0,0, radius*0.2, 0, Math.PI*2);
      }
      ctx.fill();
      if (type !== 'DEAD' && type !== 'GLOW') { ctx.fillStyle = 'black'; ctx.beginPath(); ctx.arc(2, 0, radius*0.1, 0, Math.PI*2); ctx.fill(); }
      ctx.restore();
    };
    drawEye(radius*0.4, -radius*0.35);
    drawEye(radius*0.4, radius*0.35);
  };

  const drawCuteFish = (ctx: CanvasRenderingContext2D, entity: Entity) => {
    const { radius, angle, cosmetics } = entity;
    ctx.save();
    ctx.translate(entity.x, entity.y);
    ctx.rotate(angle);
    drawTail(ctx, radius, cosmetics.skinColor, cosmetics.tailType);
    ctx.fillStyle = cosmetics.skinColor;
    ctx.beginPath(); ctx.arc(0, 0, radius, 0, Math.PI*2); ctx.fill();
    drawEyes(ctx, radius, cosmetics.eyeType);
    if (cosmetics.teeth !== 'NORMAL') {
      ctx.fillStyle = cosmetics.teeth === 'GOLD' ? '#fbbf24' : 'white';
      ctx.beginPath(); ctx.moveTo(radius*0.8, -radius*0.2); ctx.lineTo(radius, 0); ctx.lineTo(radius*0.8, radius*0.2); ctx.fill();
    }
    ctx.restore();
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let frameId: number;
    const render = () => {
      const { player, entities, camera } = gameState;
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.fillStyle = '#0f172a';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.translate(canvas.width/2, canvas.height/2);
      ctx.scale(camera.zoom, camera.zoom);
      ctx.translate(-camera.x, -camera.y);

      // 背景网格感
      ctx.strokeStyle = '#1e293b';
      ctx.lineWidth = 2;
      for(let i=0; i<=WORLD_SIZE; i+=500) {
        ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, WORLD_SIZE); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(WORLD_SIZE, i); ctx.stroke();
      }

      entities.forEach(e => drawCuteFish(ctx, e));
      drawCuteFish(ctx, player);
      frameId = requestAnimationFrame(render);
    };

    const resize = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    };
    window.addEventListener('resize', resize);
    resize();
    render();
    return () => {
      cancelAnimationFrame(frameId);
      window.removeEventListener('resize', resize);
    };
  }, [gameState]);

  return <canvas ref={canvasRef} className="w-full h-full block" onMouseMove={(e) => onMouseMove(e.clientX, e.clientY)} />;
};

export default GameCanvas;
