import { CreatureType, Entity, GameState, GameStatus, Obstacle, Portal, Cosmetics } from './types';
import { CREATURES, WORLD_SIZE, MAX_ENTITIES, BOOST_CONFIG, GAME_MECHANICS, EVOLUTION_THRESHOLDS, MAP_SHAPE_CONFIG, PORTAL_CONFIG, MAX_OBSTACLES } from './constants';
import { sounds } from './soundEngine';

const uuid = () => Math.random().toString(36).substr(2, 9);
const dist = (e1: {x: number, y: number}, e2: {x: number, y: number}) => Math.hypot(e1.x - e2.x, e1.y - e2.y);

// 花瓣状地图边界算法
export const getMapBoundaryRadius = (angle: number): number => {
    const { BASE_RADIUS, PETAL_VARIANCE } = MAP_SHAPE_CONFIG;
    return BASE_RADIUS + Math.sin(angle * 5) * PETAL_VARIANCE;
};

const getDefaultCosmetics = (type: CreatureType): Cosmetics => ({
  teeth: 'NORMAL', skinColor: CREATURES[type].color, pattern: 'NONE', eyeType: 'NORMAL', tailType: 'NORMAL'
});

export const createEntity = (type: CreatureType, x: number, y: number): Entity => {
  const config = CREATURES[type];
  return {
    id: uuid(), type, x, y, radius: config.baseRadius, angle: Math.random() * Math.PI * 2,
    health: config.health, maxHealth: config.health, speed: config.speed, config,
    cosmetics: getDefaultCosmetics(type), renderScale: 1.0, isHidden: false, speechBubble: null
  };
};

const spawnEntities = (state: GameState) => {
    if (state.entities.length < MAX_ENTITIES) {
        const types = Object.keys(CREATURES) as CreatureType[];
        const type = types[Math.floor(Math.random() * types.length)];
        // 随机在地图内部生成
        const ang = Math.random() * Math.PI * 2;
        const d = Math.random() * getMapBoundaryRadius(ang);
        const x = WORLD_SIZE/2 + Math.cos(ang) * d;
        const y = WORLD_SIZE/2 + Math.sin(ang) * d;
        state.entities.push(createEntity(type, x, y));
    }
};

export const updateGame = (state: GameState, mouse: {x: number, y: number}, isSpace: boolean, sw: number, sh: number): GameState => {
  spawnEntities(state);
  state.time++;

  if (state.status === GameStatus.MENU || state.status === GameStatus.SHOP) {
      updateNPCs(state);
      state.camera.x += (state.player.x - state.camera.x) * 0.1;
      state.camera.y += (state.player.y - state.camera.y) * 0.1;
      state.camera.zoom += (state.status === GameStatus.SHOP ? 1.8 : 1.2 - state.camera.zoom) * 0.05;
      return state;
  }

  if (state.status === GameStatus.PLAYING) {
      // 玩家操作
      const dx = mouse.x - sw / 2;
      const dy = mouse.y - sh / 2;
      const targetAngle = Math.atan2(dy, dx);
      let diff = targetAngle - state.player.angle;
      while (diff > Math.PI) diff -= Math.PI * 2;
      while (diff < -Math.PI) diff += Math.PI * 2;
      state.player.angle += diff * 0.15;

      let speedMult = 1.0;
      if (isSpace && state.player.boost.current > 0) {
          state.player.boost.active = true;
          state.player.boost.current -= BOOST_CONFIG.DRAIN_RATE;
          speedMult = BOOST_CONFIG.SPEED_MULTIPLIER;
      } else {
          state.player.boost.active = false;
          state.player.boost.current = Math.min(100, state.player.boost.current + BOOST_CONFIG.REGEN_RATE);
      }

      state.player.x += Math.cos(state.player.angle) * state.player.speed * speedMult;
      state.player.y += Math.sin(state.player.angle) * state.player.speed * speedMult;

      // 边界弹性限制
      const centerDist = dist(state.player, { x: WORLD_SIZE/2, y: WORLD_SIZE/2 });
      const currentAngle = Math.atan2(state.player.y - WORLD_SIZE/2, state.player.x - WORLD_SIZE/2);
      const limit = getMapBoundaryRadius(currentAngle);
      if (centerDist > limit) {
          const pushBack = (centerDist - limit) * 0.1;
          state.player.x -= Math.cos(currentAngle) * pushBack;
          state.player.y -= Math.sin(currentAngle) * pushBack;
      }

      // 进化检测
      const threshold = EVOLUTION_THRESHOLDS.find(t => t.tier === state.player.config.tier + 1);
      if (threshold && state.player.radius >= threshold.radius) {
          const nextTierTypes = (Object.keys(CREATURES) as CreatureType[]).filter(k => CREATURES[k].tier === threshold.tier);
          const nextType = nextTierTypes[Math.floor(Math.random() * nextTierTypes.length)];
          state.player.type = nextType;
          state.player.config = CREATURES[nextType];
          state.player.maxHealth = state.player.config.health;
          state.player.health = state.player.maxHealth;
          sounds.playEvolve();
      }

      updateNPCs(state);

      state.camera.x += (state.player.x - state.camera.x) * 0.1;
      state.camera.y += (state.player.y - state.camera.y) * 0.1;
      state.camera.zoom += (Math.max(0.3, 0.8 - state.player.radius / 800) - state.camera.zoom) * 0.05;
  }

  return state;
};

const updateNPCs = (state: GameState) => {
    state.entities.forEach(ent => {
