        const cd = dist(ent, { x: WORLD_SIZE/2, y: WORLD_SIZE/2 });
        const ca = Math.atan2(ent.y - WORLD_SIZE/2, ent.x - WORLD_SIZE/2);
        if (cd > getMapBoundaryRadius(ca)) {
            ent.angle = ca + Math.PI + (Math.random()-0.5);
        }
    });
    state.entities = state.entities.filter(e => e.health > 0 || e.type === CreatureType.PLANKTON);
