import { WORLD_SIZE, CREATURES } from './constants';
import { updateGame, createObstacles } from './gameEngine';

const createInitialState = (type: CreatureType = CreatureType.CLOWN_FISH): GameState => {
  const config = CREATURES[type];
  return {
    status: GameStatus.MENU,
    player: {
      id: 'player', type, x: WORLD_SIZE/2, y: WORLD_SIZE/2, radius: config.baseRadius, angle: 0,
