      cosmetics: { teeth: 'NORMAL', skinColor: config.color, pattern: 'NONE', eyeType: 'NORMAL', tailType: 'NORMAL' }
    },
    entities: [], obstacles: createObstacles(), portals: [], particles: [], 
    worldWidth: WORLD_SIZE, worldHeight: WORLD_SIZE, camera: { x: WORLD_SIZE/2, y: WORLD_SIZE/2, zoom: 0.8 }, time: 0
  };
};

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>(createInitialState());
  const gameStateRef = useRef<GameState>(gameState);
  const mouseRef = useRef({ x: 0, y: 0 });
  const keysRef = useRef({ space: false });
  const frameId = useRef(0);

  useEffect(() => { gameStateRef.current = gameState; }, [gameState]);

  const loop = useCallback(() => {
    const nextState = updateGame(gameStateRef.current, mouseRef.current, keysRef.current.space, window.innerWidth, window.innerHeight);
    gameStateRef.current = nextState;
    setGameState({ ...nextState });
    frameId.current = requestAnimationFrame(loop);
  }, []);

  useEffect(() => {
    frameId.current = requestAnimationFrame(loop);
    const down = (e: KeyboardEvent) => { if(e.code === 'Space') { e.preventDefault(); keysRef.current.space = true; } };
    const up = (e: KeyboardEvent) => { if(e.code === 'Space') keysRef.current.space = false; };
    const blur = () => { keysRef.current.space = false; };
    window.addEventListener('keydown', down); window.addEventListener('keyup', up); window.addEventListener('blur', blur);
    return () => { cancelAnimationFrame(frameId.current); window.removeEventListener('keydown', down); window.removeEventListener('keyup', up); window.removeEventListener('blur', blur); };
  }, [loop]);

  return (
    <div className="w-full h-screen overflow-hidden bg-slate-900 relative">
      <GameCanvas gameState={gameState} onMouseMove={(x, y) => mouseRef.current = {x,y}} />
      <UIOverlay 
        gameState={gameState}
        onStart={() => setGameState(prev => ({ ...prev, status: GameStatus.PLAYING }))}
        onRestart={() => setGameState(createInitialState())}
        setGameStatus={(s) => setGameState(prev => ({ ...prev, status: s }))}
        onUpdateCosmetics={(cos) => {
            const next = { ...gameStateRef.current };
            next.player.cosmetics = { ...next.player.cosmetics, ...cos };
            if (cos.skinColor) next.player.config.color = cos.skinColor;
            setGameState({ ...next });
        }}
      />
