      case 'FORKED': ctx.moveTo(0,0); ctx.lineTo(-radius, -radius); ctx.lineTo(-radius*0.5, 0); ctx.lineTo(-radius, radius); break;
      case 'ROUND': ctx.arc(-radius*0.3, 0, radius*0.7, 0, Math.PI*2); break;
      case 'FAN': ctx.moveTo(0,0); ctx.arc(0,0, radius, Math.PI*0.8, Math.PI*1.2); break;
      case 'HEART': ctx.moveTo(0,0); ctx.bezierCurveTo(-radius, -radius, -radius*2, 0, 0, radius); break;
      case 'LONG': ctx.moveTo(0,0); ctx.lineTo(-radius*2, 0); break;
      case 'POINTY': ctx.moveTo(0, -radius*0.5); ctx.lineTo(-radius*1.5, 0); ctx.lineTo(0, radius*0.5); break;
      default: ctx.moveTo(0,0); ctx.lineTo(-radius, -radius*0.7); ctx.lineTo(-radius, radius*0.7);
    }
    ctx.fill();
    ctx.restore();

    // 绘制身体
    ctx.fillStyle = cosmetics.skinColor;
    ctx.beginPath();
    ctx.ellipse(0, 0, radius, radius * 0.85, 0, 0, Math.PI * 2);
    ctx.fill();

    // 绘制眼睛
    const drawEye = (ex: number, ey: number) => {
      ctx.save();
      ctx.translate(ex, ey);
      ctx.fillStyle = 'white';
      ctx.beginPath();
      switch(cosmetics.eyeType) {
        case 'ANGRY': ctx.moveTo(-radius*0.1, -radius*0.1); ctx.lineTo(radius*0.2, 0); ctx.lineTo(-radius*0.1, radius*0.1); break;
        case 'DEAD': ctx.moveTo(-5,-5); ctx.lineTo(5,5); ctx.moveTo(5,-5); ctx.lineTo(-5,5); ctx.strokeStyle='black'; ctx.stroke(); break;
        case 'GLOW': ctx.shadowBlur = 15; ctx.shadowColor = 'cyan'; ctx.arc(0,0, radius*0.2, 0, Math.PI*2); break;
        case 'COOL': ctx.fillRect(-radius*0.15, -radius*0.05, radius*0.3, radius*0.1); break;
        case 'BIG': ctx.arc(0,0, radius*0.3, 0, Math.PI*2); break;
        case 'CUTE': ctx.arc(0,0, radius*0.2, 0, Math.PI*2); break;
