import { CreatureType, Entity, GameState, GameStatus, Obstacle, Portal, Cosmetics, EyeType, TailType, TeethType } from './types';
import { CREATURES, WORLD_SIZE, MAX_ENTITIES, BOOST_CONFIG, GAME_MECHANICS, EVOLUTION_THRESHOLDS, MAP_SHAPE_CONFIG, MAX_OBSTACLES, COSMETIC_OPTIONS } from './constants';
import { sounds } from './soundEngine';

const uuid = () => Math.random().toString(36).substr(2, 9);
const dist = (e1: {x: number, y: number}, e2: {x: number, y: number}) => Math.hypot(e1.x - e2.x, e1.y - e2.y);

export const getMapBoundaryRadius = (angle: number): number => {
    const { BASE_RADIUS, PETAL_VARIANCE } = MAP_SHAPE_CONFIG;
    return BASE_RADIUS + Math.sin(angle * 5) * PETAL_VARIANCE;
};

// 随机搭配外观，让每个NPC都独一无二
const getRandomCosmetics = (type: CreatureType): Cosmetics => {
    const baseColor = CREATURES[type].color;
    return {
        skinColor: Math.random() > 0.3 ? COSMETIC_OPTIONS.colors[Math.floor(Math.random() * COSMETIC_OPTIONS.colors.length)] : baseColor,
        eyeType: COSMETIC_OPTIONS.eyes[Math.floor(Math.random() * COSMETIC_OPTIONS.eyes.length)] as EyeType,
        tailType: COSMETIC_OPTIONS.tails[Math.floor(Math.random() * COSMETIC_OPTIONS.tails.length)] as TailType,
        teeth: Math.random() > 0.8 ? COSMETIC_OPTIONS.teeth[Math.floor(Math.random() * COSMETIC_OPTIONS.teeth.length)] as TeethType : 'NORMAL',
        pattern: 'NONE'
    };
};

export const createEntity = (type: CreatureType, x: number, y: number): Entity => {
  const config = CREATURES[type];
  return {
    id: uuid(), type, x, y, radius: config.baseRadius, angle: Math.random() * Math.PI * 2,
    health: config.health, maxHealth: config.health, speed: config.speed, config,
    cosmetics: getRandomCosmetics(type), renderScale: 1.0, isHidden: false, speechBubble: null
  };
};

const spawnEntities = (state: GameState) => {
    if (state.entities.length < MAX_ENTITIES) {
        const types = (Object.keys(CREATURES) as CreatureType[]).filter(t => t !== CreatureType.PLANKTON);
        const type = types[Math.floor(Math.random() * types.length)];
        const ang = Math.random() * Math.PI * 2;
        const d = Math.random() * getMapBoundaryRadius(ang) * 0.95;
        const x = WORLD_SIZE/2 + Math.cos(ang) * d;
        const y = WORLD_SIZE/2 + Math.sin(ang) * d;
        state.entities.push(createEntity(type, x, y));
    }
};

export const updateGame = (state: GameState, mouse: {x: number, y: number}, isSpace: boolean, sw: number, sh: number): GameState => {
  spawnEntities(state);
  state.time++;

  if (state.status === GameStatus.SHOP) {
      updateNPCs(state);
      const targetCamX = state.player.x + (sw * 0.25) / state.camera.zoom; 
      state.camera.x += (targetCamX - state.camera.x) * 0.1;
      state.camera.y += (state.player.y - state.camera.y) * 0.1;
      state.camera.zoom += (2.8 - state.camera.zoom) * 0.05;
      return state;
  }

  if (state.status === GameStatus.MENU) {
      updateNPCs(state);
      state.camera.x += (WORLD_SIZE/2 + Math.cos(state.time * 0.005) * 500 - state.camera.x) * 0.01;
      state.camera.y += (WORLD_SIZE/2 + Math.sin(state.time * 0.005) * 500 - state.camera.y) * 0.01;
      state.camera.zoom += (0.6 - state.camera.zoom) * 0.01;
      return state;
  }

  if (state.status === GameStatus.PLAYING) {
      const dx = mouse.x - sw / 2;
      const dy = mouse.y - sh / 2;
      const targetAngle = Math.atan2(dy, dx);
      let diff = targetAngle - state.player.angle;
      while (diff > Math.PI) diff -= Math.PI * 2;
      while (diff < -Math.PI) diff += Math.PI * 2;
      state.player.angle += diff * 0.15;

      let speedMult = 1.0;
      if (isSpace && state.player.boost.current > 0) {
          state.player.boost.active = true;
          state.player.boost.current -= BOOST_CONFIG.DRAIN_RATE;
          speedMult = BOOST_CONFIG.SPEED_MULTIPLIER;
      } else {
          state.player.boost.active = false;
          state.player.boost.current = Math.min(100, state.player.boost.current + BOOST_CONFIG.REGEN_RATE);
      }

      state.player.x += Math.cos(state.player.angle) * state.player.speed * speedMult;
      state.player.y += Math.sin(state.player.angle) * state.player.speed * speedMult;

      const centerDist = dist(state.player, { x: WORLD_SIZE/2, y: WORLD_SIZE/2 });
      const currentAngle = Math.atan2(state.player.y - WORLD_SIZE/2, state.player.x - WORLD_SIZE/2);
      const limit = getMapBoundaryRadius(currentAngle);
      if (centerDist > limit) {
          const pushBack = (centerDist - limit) * 0.1;
          state.player.x -= Math.cos(currentAngle) * pushBack;
          state.player.y -= Math.sin(currentAngle) * pushBack;
      }

      const threshold = EVOLUTION_THRESHOLDS.find(t => t.tier === state.player.config.tier + 1);
      if (threshold && state.player.radius >= threshold.radius) {
          const nextTierTypes = (Object.keys(CREATURES) as CreatureType[]).filter(k => CREATURES[k].tier === threshold.tier);
          const nextType = nextTierTypes[Math.floor(Math.random() * nextTierTypes.length)];
          state.player.type = nextType;
          state.player.config = CREATURES[nextType];
          state.player.maxHealth = state.player.config.health;
          state.player.health = state.player.maxHealth;
          sounds.playEvolve();
      }

      updateNPCs(state);

      state.camera.x += (state.player.x - state.camera.x) * 0.1;
      state.camera.y += (state.player.y - state.camera.y) * 0.1;
      const targetZoom = Math.max(0.2, 0.8 - state.player.radius / 1000);
      state.camera.zoom += (targetZoom - state.camera.zoom) * 0.05;
  }

  return state;
};

const updateNPCs = (state: GameState) => {
    state.entities.forEach(ent => {
        const d = dist(ent, state.player);
        if (d < 600) {
            const ang = Math.atan2(state.player.y - ent.y, state.player.x - ent.x);
            ent.angle = state.player.radius > ent.radius ? ang + Math.PI : ang;
        }
        ent.x += Math.cos(ent.angle) * ent.speed;
        ent.y += Math.sin(ent.angle) * ent.speed;

        if (state.status === GameStatus.PLAYING && d < ent.radius + state.player.radius) {
            if (state.player.radius > ent.radius * 1.15) {
                ent.health = 0;
                state.player.radius = Math.min(GAME_MECHANICS.MAX_RADIUS, Math.sqrt(state.player.radius**2 + ent.radius**2 * 0.3));
                state.player.weight += ent.config.weightValue;
                sounds.playEat();
            } else if (ent.radius > state.player.radius * 1.4 && state.player.invulnerableTimer <= 0) {
                state.player.health -= 0.3;
                if (state.player.health <= 0) state.status = GameStatus.GAME_OVER;
            }
        }

        const cd = dist(ent, { x: WORLD_SIZE/2, y: WORLD_SIZE/2 });
        const ca = Math.atan2(ent.y - WORLD_SIZE/2, ent.x - WORLD_SIZE/2);
        if (cd > getMapBoundaryRadius(ca)) {
            ent.angle = ca + Math.PI + (Math.random()-0.5);
        }
    });
    state.entities = state.entities.filter(e => e.health > 0);
};

export const createObstacles = (): Obstacle[] => {
    const obs: Obstacle[] = [];
    for(let i=0; i<MAX_OBSTACLES; i++) {
        const ang = Math.random() * Math.PI * 2;
        const d = Math.random() * getMapBoundaryRadius(ang) * 0.95;
        obs.push({
            id: uuid(),
            x: WORLD_SIZE/2 + Math.cos(ang) * d,
            y: WORLD_SIZE/2 + Math.sin(ang) * d,
            radius: 40 + Math.random() * 120,
            type: Math.random() > 0.6 ? 'SEAWEED' : (Math.random() > 0.5 ? 'CORAL' : 'ROCK')
        });
    }
    return obs;
};
