        break;
      case 'ROUND': 
        ctx.arc(-radius*0.3, 0, radius*0.8, 0, Math.PI*2); 
        break;
      case 'FAN': 
        ctx.moveTo(0,0); ctx.arc(0,0, radius * 1.2, Math.PI*0.8, Math.PI*1.2); 
        break;
      case 'HEART': 
        ctx.moveTo(0,0); ctx.bezierCurveTo(-radius, -radius, -radius*2.2, 0, 0, radius); 
        break;
      case 'RIBBON':
        ctx.moveTo(0,0); 
        ctx.bezierCurveTo(-radius, -radius*1.5, -radius*2, 0, -radius*2.5, radius);
