import { CreatureType, Entity, GameState, GameStatus, Obstacle, Portal, Cosmetics, EyeType, TailType, TeethType } from './types';
import { CREATURES, WORLD_SIZE, MAX_ENTITIES, BOOST_CONFIG, GAME_MECHANICS, EVOLUTION_THRESHOLDS, MAP_SHAPE_CONFIG, MAX_OBSTACLES, COSMETIC_OPTIONS } from './constants';
