const GameCanvas: React.FC<GameCanvasProps> = ({ gameState, onMouseMove }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let frameId: number;
    const render = () => {
      const { player, entities, camera, obstacles, status, time } = gameState;
      ctx.setTransform(1, 0, 0, 1, 0, 0);

      if (status === GameStatus.SHOP) {
          const grad = ctx.createRadialGradient(canvas.width*0.3, canvas.height/2, 100, canvas.width*0.3, canvas.height/2, 800);
          grad.addColorStop(0, '#1e3a3a');
          grad.addColorStop(1, '#020617');
          ctx.fillStyle = grad;
      } else {
          ctx.fillStyle = '#0f172a';
      }
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.save();
      ctx.translate(canvas.width/2, canvas.height/2);
      ctx.scale(camera.zoom, camera.zoom);
      ctx.translate(-camera.x, -camera.y);

      if (status !== GameStatus.SHOP) {
        ctx.fillStyle = 'rgba(30, 41, 59, 0.4)';
        ctx.beginPath();
        for(let a=0; a<=Math.PI*2; a+=0.1) {
            const r = getMapBoundaryRadius(a);
            ctx.lineTo(WORLD_SIZE/2 + Math.cos(a)*r, WORLD_SIZE/2 + Math.sin(a)*r);
        }
        ctx.fill();

        obstacles.forEach(o => {
            ctx.save();
            ctx.translate(o.x, o.y);
            ctx.fillStyle = o.type === 'ROCK' ? '#475569' : (o.type === 'CORAL' ? '#f43f5e' : 'rgba(34, 197, 94, 0.3)');
            ctx.beginPath(); ctx.arc(0, 0, o.radius, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        });

        entities.forEach(e => {
            ctx.save();
            ctx.translate(e.x, e.y);
            drawFishParts(ctx, e.radius, e.angle, e.cosmetics);
            ctx.restore();
        });
      }

      // 玩家绘制逻辑
      ctx.save();
      ctx.translate(player.x, player.y);

      // 无敌闪烁效果
      if (player.invulnerableTimer > 0) {
          ctx.globalAlpha = 0.4 + Math.sin(time * 0.2) * 0.3;
      }

      const renderAngle = status === GameStatus.SHOP ? Math.sin(Date.now()/1000)*0.2 : player.angle;
      drawFishParts(ctx, player.radius, renderAngle, player.cosmetics);
      ctx.restore();

      ctx.restore();

      if (status === GameStatus.PLAYING) {
        const ms = 180;
        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.translate(20, canvas.height - ms - 20);
        ctx.fillStyle = 'rgba(15, 23, 42, 0.8)';
        ctx.beginPath(); ctx.roundRect(0, 0, ms, ms, 20); ctx.fill();
        const scale = ms / WORLD_SIZE;
        ctx.fillStyle = '#4ade80';
        ctx.beginPath(); ctx.arc(player.x * scale, player.y * scale, 4, 0, Math.PI*2); ctx.fill();
      }

      frameId = requestAnimationFrame(render);
    };

    const resize = () => { canvas.width = window.innerWidth; canvas.height = window.innerHeight; };
    window.addEventListener('resize', resize); resize(); render();
    return () => { cancelAnimationFrame(frameId); window.removeEventListener('resize', resize); };
  }, [gameState]);

  return <canvas ref={canvasRef} className="w-full h-full block" onMouseMove={(e) => onMouseMove(e.clientX, e.clientY)} />;
};

export default GameCanvas;
