             <div className="w-full bg-slate-700 h-2 rounded-full overflow-hidden mb-3">
              <div 
                className={`h-full transition-all duration-300 ${player.radius < 10 ? 'bg-red-500 animate-pulse' : 'bg-green-500'}`}
