                        ctx.beginPath(); ctx.moveTo(i, -radius*0.8); ctx.quadraticCurveTo(i+10, 0, i, radius*0.8); ctx.lineTo(i+8, radius*0.8); ctx.quadraticCurveTo(i+18, 0, i+8, -radius*0.8); ctx.fill();
