export const drawCuteFish = (ctx: CanvasRenderingContext2D, entity: Entity | PlayerState, visualTime: number, isPreview: boolean = false) => {
    const { type, radius, angle, config, renderScale, mouthOpenValue, animOffset } = entity;
    const isPlayer = entity.id === 'player';

    ctx.save();
    if (!isPreview) {
        ctx.translate(entity.x, entity.y);
        ctx.rotate(angle);
        ctx.scale(renderScale, renderScale);
    } else {
        ctx.translate(entity.x, entity.y);
        ctx.rotate(angle); // Preview rotation handled outside or just straight
    }

    const bodyFill = config.color;

    if (type === CreatureType.PLANKTON) {
        ctx.fillStyle = bodyFill;
        ctx.beginPath();
        ctx.arc(0, 0, radius, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();
    } else if (type === CreatureType.MASCOT) {
        // --- MASCOT RENDERING ---
