        const tailWag = Math.sin(visualTime * 0.2 + animOffset) * 0.2;

        // Tail
        ctx.fillStyle = bodyFill;
        ctx.beginPath();
        ctx.moveTo(-radius * 0.8, 0);
        ctx.lineTo(-radius * 1.5, -radius * 0.5 + tailWag * 10);
        ctx.lineTo(-radius * 1.5, radius * 0.5 + tailWag * 10);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // Fins
