export const getMapBoundaryRadius = (angle: number): number => {
    const { BASE_RADIUS, PETAL_VARIANCE } = MAP_SHAPE_CONFIG;
    // 5 petals flower shape
    return BASE_RADIUS + Math.cos(angle * 5) * PETAL_VARIANCE;
};

const clampToMap = (entity: Entity | PlayerState) => {
    const dx = entity.x - MAP_SHAPE_CONFIG.CENTER_X;
    const dy = entity.y - MAP_SHAPE_CONFIG.CENTER_Y;
    const angle = Math.atan2(dy, dx);
    const dist = Math.hypot(dx, dy);
    const maxR = getMapBoundaryRadius(angle);

    if (dist > maxR - entity.radius) {
        const r = maxR - entity.radius;
        entity.x = MAP_SHAPE_CONFIG.CENTER_X + Math.cos(angle) * r;
        entity.y = MAP_SHAPE_CONFIG.CENTER_Y + Math.sin(angle) * r;
    }
};

const getBiome = (x: number, y: number): BiomeType => {
    if (x < WORLD_SIZE / 2) {
        return y < WORLD_SIZE / 2 ? BiomeType.SHALLOWS : BiomeType.SWAMP;
    } else {
        return y < WORLD_SIZE / 2 ? BiomeType.REEF : BiomeType.ABYSS;
    }
};

const isPositionValid = (x: number, y: number): boolean => {
    const dx = x - MAP_SHAPE_CONFIG.CENTER_X;
    const dy = y - MAP_SHAPE_CONFIG.CENTER_Y;
    const angle = Math.atan2(dy, dx);
    const dist = Math.hypot(dx, dy);
    return dist < getMapBoundaryRadius(angle);
};

const getRandomPosInBiome = (biome: BiomeType): {x: number, y: number} => {
   const config = BIOME_CONFIGS[biome];
   for(let i=0; i<10; i++) {
       const x = config.xRange[0] + Math.random() * (config.xRange[1] - config.xRange[0]);
       const y = config.yRange[0] + Math.random() * (config.yRange[1] - config.yRange[0]);
       if (isPositionValid(x, y)) return {x, y};
   }
   // Fallback
   return { x: MAP_SHAPE_CONFIG.CENTER_X, y: MAP_SHAPE_CONFIG.CENTER_Y };
};

export const createBuildings = (): Building[] => {
    const buildings: Building[] = [];
    const types = [BuildingType.HOSPITAL, BuildingType.ARMORY, BuildingType.SHRINE, BuildingType.SHOP];

    types.forEach(type => {
        let pos;
        if (type === BuildingType.SHOP) pos = { x: WORLD_SIZE/2, y: WORLD_SIZE/2 }; 
        else {
             let valid = false;
             while(!valid) {
                 const x = Math.random() * WORLD_SIZE;
                 const y = Math.random() * WORLD_SIZE;
                 if (isPositionValid(x, y)) {
                     pos = {x, y};
                     valid = true;
                 }
             }
        }

        buildings.push({
            id: uuid(),
            type,
            x: pos!.x,
            y: pos!.y,
            radius: BUILDING_CONFIGS[type].radius,
            cooldown: 0
        });
    });
    return buildings;
};

