      torpedoCooldown: 0,
      isOverdrive: false,
      currentBiome: BiomeType.SHALLOWS,
      biomeDebuffTimer: 0,
      cosmetics: options.cosmetics || {
          teeth: 'NORMAL',
          skinColor: 'DEFAULT',
          pattern: 'NONE',
          scaleType: 'NONE',
