        const pos = getRandomPosInBiome(biome);
        portals.push({
            id: uuid(),
            x: pos.x,
            y: pos.y,
            radius: PORTAL_CONFIG.RADIUS,
            angle: 0
        });
    };
    makePortal(BiomeType.SHALLOWS);
    makePortal(BiomeType.REEF);
    makePortal(BiomeType.SWAMP);
    makePortal(BiomeType.ABYSS);
    return portals;
