    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    canvas.width = 400;
    canvas.height = 400;

    let frameId: number;

    const loop = () => {
        const visualTime = performance.now() / 16;

        ctx.clearRect(0, 0, canvas.width, canvas.height);

        const grad = ctx.createRadialGradient(canvas.width/2, canvas.height/2, 50, canvas.width/2, canvas.height/2, 200);
        grad.addColorStop(0, 'rgba(168, 85, 247, 0.1)');
        grad.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.fillStyle = grad;
        ctx.fillRect(0,0, canvas.width, canvas.height);

        const dummy: Entity = {
            ...player,
            x: canvas.width / 2,
            y: canvas.height / 2,
            radius: 80,
            angle: 0,
            vx: 0, vy: 0,
            cosmetics: player.cosmetics,
            animOffset: 0,
            renderScale: 1.0,
            isHidden: false,
            camoActive: false,
            isIdle: false,
            lureActive: false,
            ambushTimer: 0,
            mouthOpenValue: 0,
            fearTimer: 0,
            happyTimer: 0,
            speedBoostTimer: 0,
            evolutionVisualTimer: 0
        };

        dummy.angle = Math.sin(visualTime * 0.05) * 0.1;

        drawCuteFish(ctx, dummy, visualTime, true);

        frameId = requestAnimationFrame(loop);
    };
    loop();

    return () => cancelAnimationFrame(frameId);
