  state.camera.y += (player.y - state.camera.y) * 0.1;
  // Increase max zoom to 1.5, min zoom 0.3
  const targetZoom = Math.max(0.3, Math.min(1.5, 1.0 - (player.radius / 800)));
  state.camera.zoom += (targetZoom - state.camera.zoom) * 0.05;

  return state;
};
