          if (!dangerMarked && e.radius > player.radius * 1.5 && d < 1000 && !e.isHidden) {
              state.labels.push({ x: e.x, y: e.y - e.radius - 30, text: "太大了! 快跑!", color: '#ef4444' });
              dangerMarked = true;
          }
