      // F. PowerUp Identification
      state.powerUps.forEach(p => {
          if (dist(player, p) < 800) {
              let txt = "道具";
              let col = "#fff";
              if (p.type === 'SPEED') { txt = "加速BUFF"; col = "#fde047"; }
              else if (p.type === 'SHIELD') { txt = "无敌护盾"; col = "#22d3ee"; }
