            ctx.lineTo(-radius*2.5, -radius*0.5);
            ctx.lineTo(-radius*2.0, 0);
            ctx.lineTo(-radius*2.5, radius*0.5);
            ctx.fill();
        } else if (tType === 'ELECTRIC') {
            ctx.strokeStyle = '#00ffff';
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(-radius, 0);
            for(let i=0; i<5; i++) {
                ctx.lineTo(-radius * (1.5 + i*0.3), (Math.random()-0.5)*radius);
            }
