const updateTreasures = (state: GameState) => {
    state.treasures.forEach(t => {
        if (t.status === 'WARNING') {
            t.timer--;
            if (t.timer <= 0) {
                t.status = 'ACTIVE';
            }
        }

        // Active Treasure Interactions
        if (t.status === 'ACTIVE') {
            // Check collisions with player
            if (dist(state.player, t) < state.player.radius + t.radius) {
                // Collect!
                t.status = 'WARNING'; // Hack to mark for deletion, processed next
                t.timer = -1; // Flag to remove

                if (t.type === 'FEAST') {
                    state.player.weight += TREASURE_CONFIG.MASS_REWARD;
                    state.player.speechBubble = { text: "暴饮暴食!", timer: 120, color: '#bef264' };
                    // Visuals
                    for(let i=0; i<30; i++) state.particles.push(createParticle(t.x, t.y, '#bef264'));
                } else {
                    // CHEST: Super Buffs
                    state.player.shieldTimer = TREASURE_CONFIG.BUFF_DURATION;
                    state.player.speedBoostTimer = TREASURE_CONFIG.BUFF_DURATION;
                    state.player.speechBubble = { text: "神力加持!", timer: 120, color: '#d8b4fe' };
                    for(let i=0; i<30; i++) state.particles.push(createParticle(t.x, t.y, '#d8b4fe'));
                }
            }

            // Check collisions with AI
            for (const ent of state.entities) {
                if (dist(ent, t) < ent.radius + t.radius) {
                    t.status = 'WARNING'; 
                    t.timer = -1;

                    ent.renderScale = 1.5;
                    ent.speechBubble = { text: "抢到了!", timer: 60, color: '#fbbf24' };

                    if (t.type === 'FEAST') {
                        // AI gets bigger
                        const newR = Math.sqrt(ent.radius*ent.radius + 3000); 
                        ent.radius = Math.min(GAME_MECHANICS.MAX_RADIUS, newR);
                    } else {
                        // AI gets super buff
                        ent.isInvulnerable = true;
                        ent.speedBoostTimer = TREASURE_CONFIG.BUFF_DURATION;
                    }
                    break; // Only one eats it
                }
            }
        }
    });

    // Remove claimed treasures
    state.treasures = state.treasures.filter(t => t.timer !== -1);
};

export const updateGame = (state: GameState, mouse: {x: number, y: number}, isSpacePressed: boolean, isMouseDown: boolean, screenWidth: number, screenHeight: number): GameState => {
  if (state.status !== GameStatus.PLAYING && state.status !== GameStatus.MENU) return state;

  state.time++;
  if (state.entities.length < MAX_ENTITIES) {
      const r = Math.random();
      let type = CreatureType.PLANKTON;
      if (r < 0.6) type = CreatureType.PLANKTON;
      else if (r < 0.8) type = CreatureType.CLOWN_FISH;
