      },
      isGodMode: false,
      isAutoMode: false,
      reviveCount: 0,
      isIdle: false,
      lureActive: false,
      camoActive: false,
      ambushTimer: 0,
      shieldTimer: 0,
      invulnerableTimer: 0, 
      evolutionVisualTimer: 0, 
      torpedoCount: 0,
      torpedoCooldown: 0,
      isOverdrive: false,
      currentBiome: BiomeType.SHALLOWS,
      biomeDebuffTimer: 0,
      cosmetics: options.cosmetics || {
          teeth: 'NORMAL',
          skinColor: 'DEFAULT',
          pattern: 'NONE',
          scaleType: 'NONE',
          accessory: 'NONE',
          tailType: 'DEFAULT',
          bodyType: 'DEFAULT',
          eyeType: 'NORMAL',
          eyebrowType: 'NONE', 
          trailType: 'NONE'    
      }
    },
    entities: [],
    particles: [],
    obstacles: createObstacles(),
    powerUps: [],
    hazards: [],
