        for (const p of state.portals) {
            if (dist(entity, p) < p.radius) {
                const currentBiome = getBiome(entity.x, entity.y);
                const biomes = [BiomeType.SHALLOWS, BiomeType.REEF, BiomeType.SWAMP, BiomeType.ABYSS];
