export const createObstacles = (): Obstacle[] => {
  const obstacles: Obstacle[] = [];
  for (let i = 0; i < MAX_OBSTACLES * 1.5; i++) { 
    const x = Math.random() * WORLD_SIZE;
    const y = Math.random() * WORLD_SIZE;
    if (!isPositionValid(x, y, 100)) continue;

    const biome = getBiome(x, y);
    let type: 'ROCK' | 'CORAL' | 'SEAWEED' = 'ROCK';
    if (biome === BiomeType.SHALLOWS) type = Math.random() < 0.2 ? 'CORAL' : 'ROCK';
    else if (biome === BiomeType.REEF) type = 'CORAL';
    else if (biome === BiomeType.SWAMP) type = 'SEAWEED';
    else type = 'ROCK'; 

    const radius = 60 + Math.random() * 220; 
    obstacles.push({ id: uuid(), x, y, radius, type });
    if (obstacles.length >= MAX_OBSTACLES) break;
  }
  return obstacles;
};

export const createBuildings = (): Building[] => {
    const buildings: Building[] = [];
    const spawn = (type: BuildingType, biome: BiomeType, count: number) => {
        const conf = BUILDING_CONFIGS[type];
        for(let i=0; i<count; i++) {
            const pos = getRandomPosInBiome(biome);
            buildings.push({
                id: uuid(),
                x: pos.x,
                y: pos.y,
                type: type,
                radius: conf.radius,
                cooldown: 0
            });
        }
    };
    spawn(BuildingType.HOSPITAL, BiomeType.SHALLOWS, 1);
    spawn(BuildingType.HOSPITAL, BiomeType.REEF, 1);
    spawn(BuildingType.ARMORY, BiomeType.ABYSS, 2);
    spawn(BuildingType.SHRINE, BiomeType.SWAMP, 1);
    spawn(BuildingType.SHRINE, BiomeType.REEF, 1);

    const cx = MAP_SHAPE_CONFIG.CENTER_X;
    const cy = MAP_SHAPE_CONFIG.CENTER_Y;
    const shopDist = 2200;
    const addShop = (angle: number) => {
        buildings.push({
            id: uuid(),
            x: cx + Math.cos(angle) * shopDist,
            y: cy + Math.sin(angle) * shopDist,
            type: BuildingType.SHOP,
            radius: BUILDING_CONFIGS.SHOP.radius,
            cooldown: 0
        });
    };
    addShop(-Math.PI * 0.75); 
    addShop(-Math.PI * 0.25);
    addShop(Math.PI * 0.75);
    addShop(Math.PI * 0.25);
    return buildings;
};

export const createPortals = (): Portal[] => {
    const portals: Portal[] = [];
    const makePortal = (biome: BiomeType) => {
        const pos = getRandomPosInBiome(biome);
        portals.push({
            id: uuid(),
            x: pos.x,
            y: pos.y,
            radius: PORTAL_CONFIG.RADIUS,
            angle: 0
        });
    };
    makePortal(BiomeType.SHALLOWS);
    makePortal(BiomeType.REEF);
    makePortal(BiomeType.SWAMP);
    makePortal(BiomeType.ABYSS);
    return portals;
};

const spawnPowerUps = (state: GameState) => {
  if (state.powerUps.length >= MAX_POWERUPS) return;
  if (Math.random() > 0.03) return; 
  const angle = Math.random() * Math.PI * 2;
  const distVal = 600 + Math.random() * 1000;
  const x = state.player.x + Math.cos(angle) * distVal;
  const y = state.player.y + Math.sin(angle) * distVal;
  if (!isPositionValid(x, y)) return;
  const r = Math.random();
  let type: 'SPEED' | 'SHIELD' | 'TORPEDO' = 'SPEED';
  if (r < 0.6) type = 'SPEED';
  else if (r < 0.8) type = 'SHIELD';
  else type = 'TORPEDO';
  state.powerUps.push({ id: uuid(), x, y, type, radius: 20 });
};

const spawnHazards = (state: GameState) => {
  if (state.time % METEOR_CONFIG.INTERVAL === 0) {
    for (let i = 0; i < METEOR_CONFIG.WAVE_COUNT; i++) {
      let tx, ty;
      const r = Math.random();
      if (r < 0.3) {
        tx = state.player.x + (Math.random() - 0.5) * 600;
        ty = state.player.y + (Math.random() - 0.5) * 600;
      } else if (state.entities.length > 0) {
        const ent = state.entities[Math.floor(Math.random() * state.entities.length)];
        tx = ent.x; ty = ent.y;
      } else {
        const angle = Math.random() * Math.PI * 2;
        const d = 500 + Math.random() * 1000;
        tx = state.player.x + Math.cos(angle) * d;
        ty = state.player.y + Math.sin(angle) * d;
      }
      if (!isPositionValid(tx, ty)) continue;
      state.hazards.push({
        id: uuid(),
        x: tx || MAP_SHAPE_CONFIG.CENTER_X,
        y: ty || MAP_SHAPE_CONFIG.CENTER_Y,
        radius: METEOR_CONFIG.RADIUS,
        type: 'METEOR_STRIKE',
        timer: METEOR_CONFIG.WARNING_TIME,
        duration: METEOR_CONFIG.WARNING_TIME + METEOR_CONFIG.STRIKE_TIME,
        stage: 'WARNING'
      });
    }
  }
};

const spawnTreasures = (state: GameState) => {
    if (state.time > 0 && state.time % TREASURE_CONFIG.SPAWN_INTERVAL === 0) {
        let tx = 0, ty = 0;
        for(let i=0; i<10; i++) {
            const angle = Math.random() * Math.PI * 2;
            const distVal = 500 + Math.random() * 2000;
            tx = MAP_SHAPE_CONFIG.CENTER_X + Math.cos(angle) * distVal;
            ty = MAP_SHAPE_CONFIG.CENTER_Y + Math.sin(angle) * distVal;
            if (isPositionValid(tx, ty, 200)) break;
        }
        const type = Math.random() < 0.6 ? 'FEAST' : 'CHEST';
        if (!state.treasures) state.treasures = [];
        state.treasures.push({
            id: uuid(), x: tx, y: ty, type, status: 'WARNING',
            timer: TREASURE_CONFIG.WARNING_DURATION,
            radius: TREASURE_CONFIG.RADIUS
        });
        const typeText = type === 'FEAST' ? '超级盛宴' : '神秘宝箱';
        state.player.speechBubble = { text: `${typeText} 即将出现!`, timer: 120, color: '#fbbf24' };
    }
};

// --- 更新逻辑 ---
const updateTreasures = (state: GameState) => {
    if (!state.treasures) return;
    const { player, entities, particles } = state;
    state.treasures.forEach(t => {
        if (t.status === 'WARNING') {
            t.timer--;
            if (t.timer <= 0) t.status = 'ACTIVE';
        }
        if (t.status === 'ACTIVE') {
            if (dist(player, t) < player.radius + t.radius) {
                t.timer = -1; // 标记删除
                if (t.type === 'FEAST') {
                    player.weight += TREASURE_CONFIG.MASS_REWARD;
                    player.speechBubble = { text: "饱餐一顿!", timer: 120, color: '#bef264' };
                    for(let i=0; i<30; i++) state.particles.push(createParticle(t.x, t.y, '#bef264'));
                } else {
                    player.shieldTimer = TREASURE_CONFIG.BUFF_DURATION;
                    player.speedBoostTimer = TREASURE_CONFIG.BUFF_DURATION;
                    player.speechBubble = { text: "神力加持!", timer: 120, color: '#d8b4fe' };
                    for(let i=0; i<30; i++) state.particles.push(createParticle(t.x, t.y, '#d8b4fe'));
                }
            }
            for (const ent of entities) {
                if (dist(ent, t) < ent.radius + t.radius) {
                    t.timer = -1;
                    ent.renderScale = 1.5;
                    ent.speechBubble = { text: "抢到了!", timer: 60, color: '#fbbf24' };
                    if (t.type === 'FEAST') {
                        const newR = Math.sqrt(ent.radius*ent.radius + 3000); 
                        ent.radius = Math.min(GAME_MECHANICS.MAX_RADIUS, newR);
                    } else {
                        ent.isInvulnerable = true;
                        ent.speedBoostTimer = TREASURE_CONFIG.BUFF_DURATION;
                    }
                    break;
                }
            }
        }
    });
    state.treasures = state.treasures.filter(t => t.timer !== -1);
};

const calculateAIMovement = (entity: Entity, entities: Entity[], player: PlayerState, hazards: Hazard[], obstacles: Obstacle[], isPlayer: boolean, treasures: Treasure[]) => {
    const baseDetection = 700;
    const nearby = entities.filter(e => {
        if (e.id === entity.id || e.isHidden) return false;
        return dist(entity, e) < baseDetection + (e.radius * 5);
    });
    if (!isPlayer && !player.isHidden && entity.ownerId !== 'player') nearby.push(player);

    let fx = 0, fy = 0, fearFactor = 0;
    let nearestFoodDist = Infinity;
    let nearestFood: {x: number, y: number} | null = null;
    let targetEntityId: string | null = null;

    // 宝藏吸引力
    if (treasures) {
        for (const t of treasures) {
            const d = dist(entity, t);
            if (d < TREASURE_CONFIG.DETECTION_RANGE) {
                const weight = t.status === 'ACTIVE' ? 4.0 : 2.5; // 激活后吸引力更强
                fx += ((t.x - entity.x) / d) * weight;
                fy += ((t.y - entity.y) / d) * weight;
            }
        }
    }

    // 危险规避
    for (const h of hazards) {
        if (h.stage !== 'COOLDOWN' && h.timer > 0) {
            const d = dist(entity, h);
            if (d < h.radius + 150) {
                const evade = 5000 / (d + 1);
                fx -= ((h.x - entity.x) / d) * evade; fy -= ((h.y - entity.y) / d) * evade;
                fearFactor += evade;
            }
        }
    }

    // 掠食与逃跑
    for (const other of nearby) {
        const d = dist(entity, other);
        const sizeRatio = other.radius / entity.radius;
        if (sizeRatio > 1.1) { // 规避大鱼
            const repulsion = 30000 / (d * d + 1);
            fx -= ((other.x - entity.x) / d) * repulsion;
            fy -= ((other.y - entity.y) / d) * repulsion;
            fearFactor += repulsion;
        } else if (sizeRatio < 0.9 && d < nearestFoodDist) { // 捕食小鱼
            nearestFoodDist = d; nearestFood = other;
            if ('id' in other) targetEntityId = (other as Entity).id;
        }
    }

    if (nearestFood && fearFactor < 0.5) {
        fx += ((nearestFood.x - entity.x) / nearestFoodDist) * 2.0;
        fy += ((nearestFood.y - entity.y) / nearestFoodDist) * 2.0;
    }

    return { desiredAngle: Math.atan2(fy, fx), targetEntityId, fearFactor };
};

const updateAI = (entity: Entity, state: GameState) => {
  const { player, entities, hazards, obstacles, treasures } = state; 
  updateStrategyState(entity);
  if (entity.aggroTimer && entity.aggroTimer > 0) entity.aggroTimer--;
  if (entity.speedBoostTimer && entity.speedBoostTimer > 0) entity.speedBoostTimer--;

  if (entity.type === CreatureType.PLANKTON) {
    entity.x += Math.cos(entity.angle) * 0.5; entity.y += Math.sin(entity.angle) * 0.5;
    if (Math.random() < 0.01) entity.angle += (Math.random() - 0.5);
    clampToMap(entity); return;
  }
  if (entity.type === CreatureType.MASCOT) {
      entity.y += Math.sin(state.time * 0.05) * 1.5; return;
  }

  const agility = Math.max(0.05, GAME_MECHANICS.BASE_TURN_SPEED - (entity.radius * GAME_MECHANICS.SIZE_AGILITY_PENALTY));
  const { desiredAngle, targetEntityId } = calculateAIMovement(entity, entities, player, hazards, obstacles, false, treasures);

  if (targetEntityId) entity.targetId = targetEntityId;
  let angleDiff = desiredAngle - entity.angle;
  while (angleDiff > Math.PI) angleDiff -= Math.PI * 2;
  while (angleDiff < -Math.PI) angleDiff += Math.PI * 2;
  entity.angle += angleDiff * agility;

  const spd = entity.speed * (entity.speedBoostTimer ? 1.5 : 1.0);
  entity.vx = Math.cos(entity.angle) * spd;
  entity.vy = Math.sin(entity.angle) * spd;
  entity.x += entity.vx; entity.y += entity.vy;
  if (entity.renderScale > 1.0) entity.renderScale += (1.0 - entity.renderScale) * 0.1;
  clampToMap(entity);
};

const processCollision = (attacker: Entity | PlayerState, victim: Entity | PlayerState, particles: Particle[], state: GameState) => {
  if (attacker.type === CreatureType.MASCOT || victim.type === CreatureType.MASCOT) return;
  if ((victim.type === CreatureType.SEAHORSE || victim.type === CreatureType.MASCOT) && attacker.id !== 'player') return;

  const isVictimInvuln = 'shieldTimer' in victim && ((victim as PlayerState).shieldTimer > 0 || (victim as PlayerState).isGodMode || (victim as PlayerState).isInvulnerable);
  if (isVictimInvuln) {
      attacker.x += Math.cos(Math.atan2(attacker.y-victim.y, attacker.x-victim.x)) * 20;
      attacker.y += Math.sin(Math.atan2(attacker.y-victim.y, attacker.x-victim.x)) * 20;
      return;
  }

  const angleToVictim = Math.atan2(victim.y - attacker.y, victim.x - attacker.x);
  let angleDiff = angleToVictim - attacker.angle;
  while (angleDiff > Math.PI) angleDiff -= Math.PI * 2;
  while (angleDiff < -Math.PI) angleDiff += Math.PI * 2;
  if (Math.abs(angleDiff) > Math.PI / 3) return;

  if (victim.type === CreatureType.PLANKTON) {
    const mass = attacker.radius > 60 ? 0 : GAME_MECHANICS.PLANKTON_MASS;
    attacker.radius = Math.min(GAME_MECHANICS.MAX_RADIUS, Math.sqrt(attacker.radius**2 + mass));
    if ('weight' in attacker) (attacker as PlayerState).weight += victim.config.weightValue;
    victim.health = 0; return;
  }

  if (attacker.radius > victim.radius) {
      const swallowChance = attacker.radius / victim.radius > 2.0 ? 0.8 : 0.2;
      if (Math.random() < swallowChance) {
          attacker.radius = Math.min(GAME_MECHANICS.MAX_RADIUS, Math.sqrt(attacker.radius**2 + victim.radius**2 * 0.5));
          victim.health = 0;
          if ('weight' in attacker) (attacker as PlayerState).weight += victim.config.weightValue * 2;
          particles.push(createParticle(victim.x, victim.y, victim.config.color));
      } else {
          victim.health -= attacker.config.damage;
          particles.push(createParticle(victim.x, victim.y, 'red'));
      }
  } else {
      victim.health -= attacker.config.damage * 0.1;
      particles.push(createParticle(victim.x, victim.y, attacker.config.color));
  }
};

const updateStrategyState = (e: Entity) => {
  const speed = Math.hypot(e.vx, e.vy);
  e.isIdle = speed < GAME_MECHANICS.IDLE_THRESHOLD;
  if (e.happyTimer && e.happyTimer > 0) e.happyTimer--;
  if (e.fearTimer && e.fearTimer > 0) e.fearTimer--;
  if (e.speechBubble) {
    e.speechBubble.timer--;
    if (e.speechBubble.timer <= 0) e.speechBubble = null;
  }
};

export const updateGame = (state: GameState, mouse: {x: number, y: number}, isSpacePressed: boolean, isMouseDown: boolean, screenWidth: number, screenHeight: number): GameState => {
  if (state.status !== GameStatus.PLAYING && state.status !== GameStatus.MENU) return state;
  state.time++;

  if (state.entities.length < MAX_ENTITIES && Math.random() < 0.1) {
      const pos = { x: Math.random()*WORLD_SIZE, y: Math.random()*WORLD_SIZE };
      if (isPositionValid(pos.x, pos.y)) state.entities.push(createEntity(CreatureType.PLANKTON, pos.x, pos.y));
  }

  spawnPowerUps(state); spawnHazards(state); spawnTreasures(state);

  const { player, entities, treasures } = state;
  const targetAngle = Math.atan2(mouse.y - screenHeight/2, mouse.x - screenWidth/2);
  const agility = Math.max(0.05, GAME_MECHANICS.BASE_TURN_SPEED - (player.radius * GAME_MECHANICS.SIZE_AGILITY_PENALTY));
  let ad = targetAngle - player.angle;
  while (ad > Math.PI) ad -= Math.PI * 2; while (ad < -Math.PI) ad += Math.PI * 2;
  player.angle += ad * agility;

  const spd = player.speed * (isSpacePressed && player.boost.current > 0 ? 2.0 : 1.0);
  if (isSpacePressed) player.boost.current = Math.max(0, player.boost.current - 1);
  else player.boost.current = Math.min(BOOST_CONFIG.MAX_ENERGY, player.boost.current + 0.5);

  player.vx = Math.cos(player.angle) * spd; player.vy = Math.sin(player.angle) * spd;
  player.x += player.vx; player.y += player.vy;
  clampToMap(player);

  state.entities.forEach(ent => updateAI(ent, state));
  updateTreasures(state);

  for (const ent of entities) {
      if (dist(ent, player) < ent.radius + player.radius) {
          processCollision(player, ent, state.particles, state);
          processCollision(ent, player, state.particles, state);
      }
  }
  state.entities = state.entities.filter(e => e.health > 0);

  state.camera.x += (player.x - state.camera.x) * 0.1;
  state.camera.y += (player.y - state.camera.y) * 0.1;
  return state;
};
