const spawnHazards = (state: GameState) => {
  if (state.time % METEOR_CONFIG.INTERVAL === 0) {
    for (let i = 0; i < METEOR_CONFIG.WAVE_COUNT; i++) {
      let tx, ty;
      for(let attempt=0; attempt<5; attempt++) {
