        ctx.strokeStyle = '#000000'; ctx.lineWidth = 4; ctx.beginPath(); ctx.moveTo(-radius * 0.1, -radius * 0.6); ctx.lineTo(radius * 0.1, -radius * 0.6); ctx.stroke();
        ctx.restore(); return;
    }

