                    });
                }
                if (entity.id === 'player') {
                    particles.push({
                        id: uuid(), x: entity.x, y: entity.y, vx: 0, vy: 0, life: 0.3, maxLife: 0.3, color: 'rgba(216, 180, 254, 0.8)', size: 5000 
                    });
                }
                entity.x = dest.x;
