const PORTAL_NAMES = ["时空裂缝", "量子通道", "深海虫洞", "次元锚点", "虚空之门", "幻影旋涡", "波塞冬之径", "利维坦入口"];

// 获取商店中所有可能的搭配
const getRandomCosmetics = (tier: number): Cosmetics => {
  const mouthTypes: MouthType[] = ['TRIANGLE', 'CIRCLE', 'SQUARE', 'FLAT', 'BEAK', 'CURVE'];
  const teethTypes: TeethType[] = ['NORMAL', 'SHARP', 'VAMPIRE', 'BRACES', 'GOLD', 'CURVED', 'DOUBLE_ROW', 'SABER', 'GAPPED', 'DIAMOND', 'RAINBOW', 'BUGS', 'BLOCKY'];
  const patternTypes: PatternType[] = ['NONE', 'STRIPES', 'SPOTS', 'TIGER', 'DOTS', 'CAMO', 'ZEBRA', 'LEOPARD', 'HEART', 'STAR', 'CIRCUIT', 'LAVA', 'KOI', 'SKELETON', 'LIGHTNING', 'CLOUD', 'CHECKER', 'VINES', 'TARGET', 'GALAXY', 'SMILEY', 'FIREY', 'RUNE', 'CANDY'];
  const scaleTypes: ScaleType[] = ['NONE', 'SHINY', 'DRAGON', 'STONE', 'FEATHER', 'MECHANICAL', 'GLOW', 'MOSAIC', 'CRYSTAL', 'VOID', 'PIXEL', 'ARMOR', 'DIAMOND_PLATE', 'SLIME', 'BIO_HAZARD'];
  const accessoryTypes: AccessoryType[] = ['NONE', 'GOLD_CHAIN', 'PEARL_NECKLACE', 'JADE_PENDANT', 'SUNGLASSES', 'CROWN', 'BOW_TIE', 'DIAMOND_RING', 'MEDAL', 'HEADPHONES', 'EYEPATCH', 'HALO', 'UNICORN_HORN'];
  const tailTypes: TailType[] = ['DEFAULT', 'CRESCENT', 'FORKED', 'FAN', 'TRIDENT', 'LOBSTER', 'MECHANICAL', 'GHOST', 'RIBBON'];
  const bodyTypes: BodyType[] = ['DEFAULT', 'ROUND', 'SLENDER', 'CHUNKY', 'BOX', 'STAR', 'MERMAID', 'RAY', 'EEL'];
  const eyeTypes: EyeType[] = ['NORMAL', 'ANIME', 'MAD', 'DERP', 'CYBORG', 'DEAD', 'LOVE', 'HYPNO', 'CAT', 'FIRE', 'BUTTON', 'GOGGLES'];
  const eyebrowTypes: EyebrowType[] = ['NONE', 'ANGRY', 'SAD', 'CONFUSED', 'THICK', 'UNI', 'TIERED'];
  const trailTypes: TrailType[] = ['NONE', 'BUBBLES', 'RAINBOW', 'FIRE', 'GLITTER', 'HEARTS', 'ELECTRIC', 'SLIME'];
