            ctx.textAlign = 'center';
            for(let i=0; i<3; i++) {
                ctx.fillText('❤️', -radius * (1.3 + i*0.5), Math.sin(offset + i)*10);
            }
        } else if (tType === 'SLIME') {
            ctx.fillStyle = 'rgba(74, 222, 128, 0.4)';
            for(let i=0; i<3; i++) {
                ctx.beginPath();
                ctx.arc(-radius * (1.1 + i*0.3), Math.sin(offset + i)*12, 6, 0, Math.PI*2);
                ctx.fill();
            }
        } else if (tType === 'GLITTER') {
            ctx.fillStyle = '#fbbf24';
            for(let i=0; i<5; i++) {
                ctx.beginPath();
                ctx.arc(-radius * (1.1 + Math.random()*0.5), (Math.random()-0.5)*radius, 2, 0, Math.PI*2);
                ctx.fill();
            }
        }
        ctx.restore();
    }

    ctx.save();
    ctx.translate(entity.x, entity.y);
    if (isScared) {
        const shake = Math.sin(visualTime * 2) * 3;
        ctx.translate(shake, shake);
    }
    ctx.scale(safeScale, safeScale);

    // 玩家特有的光环
    if (isPlayer) {
        ctx.save();
        ctx.beginPath();
        ctx.strokeStyle = `rgba(34, 211, 238, ${0.4 + Math.sin(visualTime * 0.1) * 0.3})`;
        ctx.lineWidth = 4;
        ctx.shadowBlur = 15;
        ctx.shadowColor = '#22d3ee';
        ctx.arc(0, 0, radius * 1.5, 0, Math.PI * 2);
        ctx.stroke();
        ctx.restore();
    }

    ctx.rotate(entity.angle);
    if (isHidden) ctx.globalAlpha = isPlayer ? 0.4 : 0.2;
    if (camoActive) {
        ctx.fillStyle = isPlayer ? 'rgba(100, 116, 139, 0.8)' : 'rgba(100, 116, 139, 0.2)';
        ctx.beginPath();
        ctx.arc(0, 0, radius, 0, Math.PI * 2);
        ctx.fill();
        if (isPlayer) {
            ctx.strokeStyle = 'white';
            ctx.setLineDash([5, 5]);
            ctx.stroke();
        }
        ctx.restore();
        return; 
    }

    // 绘制身体颜色和渐变
    let bodyFill: string | CanvasGradient = entity.config.color;
    if (cosmetics && cosmetics.skinColor !== 'DEFAULT') {
        const skin = cosmetics.skinColor;
        if (skin.startsWith('GRADIENT_')) {
            const grad = ctx.createLinearGradient(-radius, -radius * 0.5, radius, radius * 0.5);
            if (skin === 'GRADIENT_GOLD_1') { grad.addColorStop(0, '#fef08a'); grad.addColorStop(0.5, '#eab308'); grad.addColorStop(1, '#a16207'); }
            else if (skin === 'GRADIENT_GOLD_2') { grad.addColorStop(0, '#fbcfe8'); grad.addColorStop(0.5, '#f472b6'); grad.addColorStop(1, '#ca8a04'); }
            else if (skin === 'GRADIENT_GOLD_3') { grad.addColorStop(0, '#1c1917'); grad.addColorStop(1, '#facc15'); }
            else if (skin === 'GRADIENT_SUNSET') { grad.addColorStop(0, '#6d28d9'); grad.addColorStop(0.5, '#db2777'); grad.addColorStop(1, '#f59e0b'); }
            else if (skin === 'GRADIENT_RAINBOW') { grad.addColorStop(0, '#ef4444'); grad.addColorStop(0.2, '#f59e0b'); grad.addColorStop(0.4, '#eab308'); grad.addColorStop(0.6, '#22d3ee'); grad.addColorStop(0.8, '#3b82f6'); grad.addColorStop(1, '#a855f7'); }
            else if (skin === 'GRADIENT_FIRE') { grad.addColorStop(0, '#7f1d1d'); grad.addColorStop(0.5, '#ef4444'); grad.addColorStop(1, '#fcd34d'); }
            else if (skin === 'GRADIENT_OCEAN') { grad.addColorStop(0, '#1e3a8a'); grad.addColorStop(0.5, '#06b6d4'); grad.addColorStop(1, '#a5f3fc'); }
            else if (skin === 'GRADIENT_AURORA') { grad.addColorStop(0, '#0f172a'); grad.addColorStop(0.5, '#22c55e'); grad.addColorStop(1, '#3b82f6'); }
            else if (skin === 'GRADIENT_TOXIC') { grad.addColorStop(0, '#14532d'); grad.addColorStop(0.5, '#4ade80'); grad.addColorStop(1, '#facc15'); }
            else if (skin === 'GRADIENT_CANDY') { grad.addColorStop(0, '#f472b6'); grad.addColorStop(1, '#60a5fa'); }
            bodyFill = grad;
        } else { bodyFill = skin; }
    }

    let biteSpeed = 0.12; 
    const isBoosting = (entity.speedBoostTimer && entity.speedBoostTimer > 0) || (isPlayer && (entity as any).boost?.active);
    const isChasing = !!entity.targetId;
    if (isBoosting || isChasing) { biteSpeed = 0.40; }
    const mouthGap = 0.1 + Math.abs(Math.sin(visualTime * biteSpeed + animOffset)) * 0.47; 
    const mType = cosmetics ? cosmetics.mouthType : 'TRIANGLE';

    const defineBodyPath = () => {
         ctx.beginPath();
         if (type === CreatureType.PLANKTON) { 
             ctx.arc(0, 0, radius, 0, Math.PI * 2); 
         } else {
            const bType = cosmetics ? cosmetics.bodyType : 'DEFAULT';

            // 处理特殊体型
            if (bType === 'ROUND') { ctx.arc(0, 0, radius, 0, Math.PI * 2); }
            else if (bType === 'BOX') { ctx.rect(-radius, -radius, radius * 2, radius * 2); }
            else if (bType === 'SLENDER') { ctx.ellipse(0, 0, radius * 1.5, radius * 0.6, 0, 0, Math.PI * 2); }
            else {
                // 默认嘴部切割逻辑
                if (mType === 'TRIANGLE') {
                    ctx.moveTo(0, 0);
                    ctx.arc(0, 0, radius, mouthGap, -mouthGap);
                } else if (mType === 'CIRCLE') {
                    const openR = radius * 0.3 * (mouthGap / 0.57);
                    ctx.arc(0, 0, radius, 0, Math.PI * 2);
                    ctx.moveTo(radius * 0.8, 0);
                    ctx.arc(radius * 0.85, 0, openR, 0, Math.PI * 2, true);
                } else if (mType === 'SQUARE') {
                    const h = radius * 0.6 * (mouthGap / 0.57);
                    ctx.moveTo(radius, h);
                    ctx.lineTo(radius * 0.5, h);
                    ctx.lineTo(radius * 0.5, -h);
                    ctx.lineTo(radius, -h);
                    ctx.arc(0, 0, radius, -mouthGap, mouthGap, true);
                } else if (mType === 'FLAT') {
                    const h = radius * 0.15 * (mouthGap / 0.57);
                    ctx.moveTo(radius, h);
                    ctx.lineTo(radius * 0.2, h);
                    ctx.lineTo(radius * 0.2, -h);
                    ctx.lineTo(radius, -h);
                    ctx.arc(0, 0, radius, -0.2, 0.2, true);
                } else if (mType === 'BEAK') {
                    const angle = mouthGap * 0.8;
                    ctx.moveTo(radius * 0.6, 0);
                    ctx.lineTo(radius * 1.3, -angle * radius);
                    ctx.lineTo(radius * 1.3, angle * radius);
                    ctx.arc(0, 0, radius, mouthGap, -mouthGap);
                } else if (mType === 'CURVE') {
                    const curveX = radius * 0.4 * (1 - mouthGap/0.57);
                    ctx.moveTo(radius, -radius * 0.5);
                    ctx.quadraticCurveTo(curveX, 0, radius, radius * 0.5);
                    ctx.arc(0, 0, radius, mouthGap, -mouthGap);
                } else {
                    ctx.moveTo(0, 0);
                    ctx.arc(0, 0, radius, mouthGap, -mouthGap);
                }
            }
         }
         ctx.closePath();
    };

    // 绘制尾巴
    if (type !== CreatureType.PLANKTON) {
        ctx.save(); ctx.translate(-radius * 0.6, 0);
        const tailWag = Math.sin(visualTime * 0.4 + animOffset) * 0.4; ctx.rotate(tailWag);
        ctx.fillStyle = bodyFill; ctx.strokeStyle = 'rgba(0,0,0,0.3)'; ctx.lineWidth = 2;
        const tailType = cosmetics ? cosmetics.tailType : 'DEFAULT';
        ctx.beginPath();
        if (tailType === 'DEFAULT') { ctx.moveTo(0, 0); ctx.lineTo(-radius * 0.8, -radius * 0.6); ctx.lineTo(-radius * 0.8, radius * 0.6); }
        else if (tailType === 'CRESCENT') { ctx.arc(-radius*0.5, 0, radius*0.6, 0.5, -0.5, true); }
        else if (tailType === 'FORKED') { ctx.moveTo(0, 0); ctx.lineTo(-radius * 1.2, -radius * 0.4); ctx.lineTo(-radius * 0.5, 0); ctx.lineTo(-radius * 1.2, radius * 0.4); }
        else if (tailType === 'FAN') { ctx.moveTo(0, 0); ctx.quadraticCurveTo(-radius * 0.8, -radius * 1.0, -radius * 1.4, -radius * 0.4); ctx.lineTo(-radius * 1.4, radius * 0.4); ctx.quadraticCurveTo(-radius * 0.8, radius * 1.0, 0, 0); }
        else if (tailType === 'TRIDENT') { ctx.moveTo(0, 0); ctx.lineTo(-radius * 1.2, -radius * 0.6); ctx.lineTo(-radius * 0.6, -radius * 0.2); ctx.lineTo(-radius * 1.5, 0); ctx.lineTo(-radius * 0.6, radius * 0.2); ctx.lineTo(-radius * 1.2, radius * 0.6); }
        else if (tailType === 'LOBSTER') { ctx.moveTo(0, 0); ctx.lineTo(-radius * 0.8, -radius * 0.8); ctx.lineTo(-radius * 0.8, radius * 0.8); ctx.moveTo(-radius * 0.4, 0); ctx.lineTo(-radius * 1.0, -radius * 0.3); ctx.lineTo(-radius * 1.0, radius * 0.3); }
        else if (tailType === 'MECHANICAL') { ctx.rect(-radius*1.0, -radius*0.4, radius*1.0, radius*0.8); }
        else if (tailType === 'GHOST') { ctx.moveTo(0,0); ctx.quadraticCurveTo(-radius, -radius, -radius*1.5, 0); ctx.quadraticCurveTo(-radius, radius, 0, 0); }
        else if (tailType === 'RIBBON') { ctx.moveTo(0,0); ctx.bezierCurveTo(-radius, -radius, -radius*2, radius, -radius*3, 0); }
        ctx.closePath(); ctx.fill(); ctx.stroke();
        ctx.restore();
    }

    // 绘制身体和花纹
    ctx.save();
    defineBodyPath();
    ctx.fillStyle = bodyFill; 
    ctx.strokeStyle = 'rgba(0,0,0,0.3)'; 
    ctx.lineWidth = 2; 
    ctx.fill();

    // 渲染花纹
    if (cosmetics && cosmetics.pattern !== 'NONE') {
        ctx.save();
        ctx.clip();
        const pType = cosmetics.pattern;
        ctx.fillStyle = 'rgba(0, 0, 0, 0.2)';
        if (pType === 'STRIPES') {
            for(let i=-5; i<5; i++) ctx.fillRect(i*radius*0.4, -radius, radius*0.15, radius*2);
        } else if (pType === 'SPOTS') {
            for(let i=0; i<12; i++) {
                const a = (i * Math.PI * 2) / 12;
                ctx.beginPath(); ctx.arc(Math.cos(a)*radius*0.6, Math.sin(a)*radius*0.4, radius*0.12, 0, Math.PI*2); ctx.fill();
            }
        } else if (pType === 'HEART') {
            ctx.font = `${radius}px Arial`; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.fillText('❤️', 0, 0);
        } else if (pType === 'STAR') {
             ctx.font = `${radius}px Arial`; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.fillText('⭐', 0, 0);
        } else if (pType === 'SMILEY') {
             ctx.font = `${radius}px Arial`; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.fillText('😊', 0, 0);
        } else if (pType === 'DOTS') {
             for(let x=-radius; x<radius; x+=radius*0.3) for(let y=-radius; y<radius; y+=radius*0.3) { ctx.beginPath(); ctx.arc(x, y, radius*0.05, 0, Math.PI*2); ctx.fill(); }
        } else if (pType === 'LIGHTNING') {
             ctx.strokeStyle = 'rgba(255,255,255,0.4)'; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(-radius, 0); ctx.lineTo(-radius*0.2, radius*0.3); ctx.lineTo(radius*0.2, -radius*0.3); ctx.lineTo(radius, 0); ctx.stroke();
        } else if (pType === 'CLOUD') {
             ctx.fillStyle = 'rgba(255,255,255,0.3)'; for(let i=0; i<3; i++) { ctx.beginPath(); ctx.arc(-radius*0.3 + i*radius*0.3, 0, radius*0.25, 0, Math.PI*2); ctx.fill(); }
        } else if (pType === 'TIGER') {
             for(let i=-3; i<3; i++) { ctx.beginPath(); ctx.moveTo(i*radius*0.6, -radius); ctx.lineTo(i*radius*0.6 + 10, 0); ctx.lineTo(i*radius*0.6, radius); ctx.stroke(); }
        }
        ctx.restore();
    }

    ctx.stroke();
    ctx.restore();

    // 鳞片/质感特效
    if (cosmetics && cosmetics.scaleType !== 'NONE') {
        const sType = cosmetics.scaleType;
        if (sType === 'GLOW') {
            ctx.save();
            ctx.shadowBlur = radius * 0.3;
            ctx.shadowColor = 'cyan';
            ctx.strokeStyle = 'cyan';
            ctx.lineWidth = 2;
            defineBodyPath(); ctx.stroke();
            ctx.restore();
        } else if (sType === 'SHINY') {
            ctx.save();
            const grad = ctx.createRadialGradient(0,0, 0, 0,0, radius);
            grad.addColorStop(0, 'rgba(255,255,255,0.4)');
            grad.addColorStop(1, 'rgba(255,255,255,0)');
            ctx.fillStyle = grad;
            defineBodyPath(); ctx.fill();
            ctx.restore();
        } else if (sType === 'DIAMOND_PLATE') {
            ctx.save(); ctx.clip();
            ctx.strokeStyle = 'rgba(255,255,255,0.1)'; ctx.lineWidth = 1;
            for(let i=-radius; i<radius; i+=10) { ctx.beginPath(); ctx.moveTo(i, -radius); ctx.lineTo(i+radius, radius); ctx.stroke(); }
            ctx.restore();
        } else if (sType === 'DRAGON') {
             ctx.save(); ctx.clip(); ctx.fillStyle = 'rgba(0,0,0,0.1)';
             for(let x=-radius; x<radius; x+=15) for(let y=-radius; y<radius; y+=15) { ctx.beginPath(); ctx.arc(x, y, 8, 0, Math.PI); ctx.fill(); }
             ctx.restore();
        }
    }

    // 绘制内口阴影
    if (type !== CreatureType.PLANKTON && (mType === 'TRIANGLE' || mType === 'BEAK' || mType === 'CURVE')) {
        ctx.save();
        ctx.fillStyle = '#450a0a'; 
        ctx.beginPath(); 
        ctx.moveTo(0, 0); 
        ctx.arc(0, 0, radius * 0.95, -mouthGap, mouthGap); 
        ctx.fill();
        ctx.restore();
    }

    // 眼睛和眉毛
    const eyeType = cosmetics ? cosmetics.eyeType : 'NORMAL';
    const eyebrowType = cosmetics ? cosmetics.eyebrowType : 'NONE';
    const eyeX = radius * 0.2; const eyeY = radius * 0.45; const eyeSize = radius * 0.22;

    const drawSingleEye = (x: number, y: number, size: number) => {
        ctx.save();
        ctx.translate(x, y);

        // 眉毛
        if (eyebrowType !== 'NONE') {
            ctx.strokeStyle = 'black'; ctx.lineWidth = size * 0.3; ctx.beginPath();
            if (eyebrowType === 'ANGRY') { ctx.moveTo(-size, -size); ctx.lineTo(size, -size*0.5); }
            else if (eyebrowType === 'SAD') { ctx.moveTo(-size, -size*0.5); ctx.lineTo(size, -size); }
            else if (eyebrowType === 'THICK') { ctx.lineWidth = size*0.6; ctx.moveTo(-size, -size*0.8); ctx.lineTo(size, -size*0.8); }
            else if (eyebrowType === 'UNI') { ctx.lineWidth = size*0.4; ctx.moveTo(-size*1.5, -size); ctx.lineTo(size*1.5, -size); }
            else if (eyebrowType === 'CONFUSED') { ctx.moveTo(-size, -size*0.5); ctx.bezierCurveTo(-size, -size*1.5, size, -size*0.5, size, -size*1.2); }
            ctx.stroke();
        }

        ctx.fillStyle = 'white'; ctx.beginPath(); ctx.arc(0, 0, size, 0, Math.PI*2); ctx.fill(); 

        // 瞳孔样式
        ctx.fillStyle = 'black';
        if (eyeType === 'ANIME') {
            ctx.beginPath(); ctx.arc(0, 0, size*0.7, 0, Math.PI*2); ctx.fill();
            ctx.fillStyle = 'white'; ctx.beginPath(); ctx.arc(-size*0.2, -size*0.2, size*0.2, 0, Math.PI*2); ctx.fill();
        } else if (eyeType === 'DEAD') {
            ctx.strokeStyle = 'black'; ctx.lineWidth = 2;
            ctx.beginPath(); ctx.moveTo(-size*0.5, -size*0.5); ctx.lineTo(size*0.5, size*0.5); ctx.moveTo(size*0.5, -size*0.5); ctx.lineTo(-size*0.5, size*0.5); ctx.stroke();
        } else if (eyeType === 'CAT') {
            ctx.fillStyle = '#bef264'; ctx.beginPath(); ctx.arc(0,0, size, 0, Math.PI*2); ctx.fill();
            ctx.fillStyle = 'black'; ctx.fillRect(-size*0.2, -size*0.7, size*0.4, size*1.4);
        } else if (eyeType === 'LOVE') {
            ctx.font = `${size*2}px Arial`; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.fillText('❤️', 0, 0);
        } else if (eyeType === 'HYPNO') {
            ctx.strokeStyle = 'black'; ctx.lineWidth = 1;
            for(let r=1; r<size; r+=3) { ctx.beginPath(); ctx.arc(0,0, r, 0, Math.PI*2); ctx.stroke(); }
        } else if (eyeType === 'FIRE') {
            ctx.fillStyle = '#f59e0b'; ctx.beginPath(); ctx.arc(0,0, size, 0, Math.PI*2); ctx.fill();
            ctx.fillStyle = '#ef4444'; ctx.beginPath(); ctx.arc(0,0, size*0.5, 0, Math.PI*2); ctx.fill();
        } else if (eyeType === 'CYBORG') {
             ctx.fillStyle = '#ef4444'; ctx.beginPath(); ctx.arc(0,0, size, 0, Math.PI*2); ctx.fill();
             ctx.fillStyle = 'white'; ctx.beginPath(); ctx.arc(0,0, 2, 0, Math.PI*2); ctx.fill();
        } else {
            ctx.beginPath(); ctx.arc(size*0.3, 0, size*0.4, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    };
    drawSingleEye(eyeX, -eyeY, eyeSize); 
    drawSingleEye(eyeX, eyeY, eyeSize);

    // 牙齿
    if (type !== CreatureType.PLANKTON && cosmetics && cosmetics.teeth !== 'NORMAL') {
        const toothCount = 4; const toothSize = radius * 0.15;
        ctx.save();
        ctx.fillStyle = cosmetics.teeth === 'GOLD' ? '#fbbf24' : (cosmetics.teeth === 'DIAMOND' ? '#e0f2fe' : (cosmetics.teeth === 'RAINBOW' ? `hsl(${visualTime*10%360}, 100%, 50%)` : 'white'));
        for(let i=0; i<toothCount; i++) {
            ctx.save();
            ctx.rotate(-mouthGap + 0.1 + i*0.1);
            ctx.fillRect(radius * 0.8, -toothSize/2, toothSize, toothSize);
            ctx.restore();
            ctx.save();
            ctx.rotate(mouthGap - 0.1 - i*0.1);
            ctx.fillRect(radius * 0.8, -toothSize/2, toothSize, toothSize);
            ctx.restore();
        }
        ctx.restore();
    }

    // 装饰品
    if (cosmetics && cosmetics.accessory !== 'NONE') {
        const acc = cosmetics.accessory;
        ctx.save();
        if (acc === 'SUNGLASSES') {
            ctx.fillStyle = 'rgba(0, 0, 0, 0.8)';
            ctx.fillRect(eyeX - radius*0.1, -eyeY - eyeSize, radius*0.3, eyeY*2 + eyeSize*2);
        } else if (acc === 'GOLD_CHAIN') {
            ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = radius*0.1; ctx.beginPath(); ctx.arc(0, 0, radius*1.05, -1, 1); ctx.stroke();
        } else if (acc === 'CROWN') {
            ctx.font = `${radius*0.8}px Arial`; ctx.textAlign = 'center'; ctx.fillText('👑', 0, -radius*0.8);
        } else if (acc === 'HALO') {
            ctx.strokeStyle = 'rgba(255, 255, 0, 0.6)'; ctx.lineWidth = 4; ctx.beginPath(); ctx.ellipse(0, -radius*1.1, radius*0.6, radius*0.2, 0, 0, Math.PI*2); ctx.stroke();
        } else if (acc === 'BOW_TIE') {
            ctx.font = `${radius*0.6}px Arial`; ctx.textAlign = 'center'; ctx.fillText('🎀', -radius*0.5, 0);
        } else if (acc === 'PEARL_NECKLACE') {
            ctx.fillStyle = 'white'; for(let i=0; i<5; i++) { ctx.beginPath(); ctx.arc(radius*0.9, -radius*0.3 + i*radius*0.15, 4, 0, Math.PI*2); ctx.fill(); }
        } else if (acc === 'EYEPATCH') {
            ctx.fillStyle = 'black'; ctx.beginPath(); ctx.arc(eyeX, -eyeY, eyeSize*1.2, 0, Math.PI*2); ctx.fill();
            ctx.strokeStyle = 'black'; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(eyeX, -eyeY); ctx.lineTo(-radius, -radius); ctx.stroke();
        } else if (acc === 'UNICORN_HORN') {
            ctx.fillStyle = '#fbcfe8'; ctx.beginPath(); ctx.moveTo(radius*0.5, -radius*0.5); ctx.lineTo(radius*1.5, -radius*1.0); ctx.lineTo(radius*0.8, -radius*0.2); ctx.fill();
        } else if (acc === 'JADE_PENDANT') {
             ctx.fillStyle = '#10b981'; ctx.beginPath(); ctx.arc(0, radius*1.1, 10, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    }

    ctx.restore();
};

const GameCanvas: React.FC<GameCanvasProps> = ({ gameState, onMouseMove, onMouseDown, onMouseUp }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const drawSpeechBubble = (ctx: CanvasRenderingContext2D, e: Entity | PlayerState) => {
    if (!e.speechBubble) return;
    ctx.save(); ctx.translate(e.x, e.y - e.radius - 20);
    const text = e.speechBubble.text; ctx.font = "bold 18px Arial"; const m = ctx.measureText(text); const w = m.width + 24; const h = 36;
    ctx.fillStyle = 'rgba(255, 255, 255, 0.95)'; ctx.strokeStyle = e.speechBubble.color; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.roundRect(-w/2, -h, w, h, 12); ctx.fill(); ctx.stroke(); ctx.fillStyle = 'black'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.fillText(text, 0, -h/2); ctx.restore();
  };

  const drawPortalVortex = (ctx: CanvasRenderingContext2D, p: Portal, visualTime: number) => {
    ctx.save(); ctx.translate(p.x, p.y);

    // 传送阵名称
    ctx.font = "bold 24px Arial";
    ctx.textAlign = "center";
    ctx.fillStyle = "white";
    ctx.shadowBlur = 10;
    ctx.shadowColor = "rgba(216, 180, 254, 0.8)";
    ctx.fillText(p.name, 0, -p.radius - 25);
    ctx.shadowBlur = 0;

    ctx.rotate(visualTime * 0.05);
    for(let i=0; i<3; i++) {
        ctx.strokeStyle = PORTAL_CONFIG.COLORS[i]; ctx.lineWidth = 4; ctx.beginPath(); ctx.arc(0, 0, p.radius * (1 - i*0.2), 0, Math.PI * 1.5); ctx.stroke();
    }
    ctx.restore();
  };

  const drawMapBackground = (ctx: CanvasRenderingContext2D) => {
      ctx.fillStyle = '#0f172a'; ctx.beginPath(); const steps = 180; for(let i=0; i<=steps; i++) { const angle = (Math.PI * 2 * i) / steps; const r = getMapBoundaryRadius(angle); const x = MAP_SHAPE_CONFIG.CENTER_X + Math.cos(angle) * r; const y = MAP_SHAPE_CONFIG.CENTER_Y + Math.sin(angle) * r; if (i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y); } ctx.closePath(); ctx.fill(); ctx.save(); ctx.clip();
      Object.values(BIOME_CONFIGS).forEach(biome => {
             ctx.fillStyle = biome.color; ctx.fillRect(biome.xRange[0], biome.yRange[0], biome.xRange[1] - biome.xRange[0], biome.yRange[1] - biome.yRange[0]);
      });
      ctx.restore(); ctx.strokeStyle = '#38bdf8'; ctx.lineWidth = 8; ctx.stroke();
