    ctx.scale(safeScale, safeScale);

    if (isPlayer) {
        ctx.save();
        ctx.beginPath();
        ctx.strokeStyle = `rgba(34, 211, 238, ${0.4 + Math.sin(visualTime * 0.1) * 0.3})`;
        ctx.lineWidth = 4;
        ctx.shadowBlur = 15;
