        };

        if (mType === 'TRIANGLE' || mType === 'SQUARE') {
            const gap = mouthGap;
            if (tType === 'SABER') {
                drawTooth(-gap + 0.1, true); // 只有上颚有长牙
            } else if (tType === 'BUGS') {
