  const drawSpeechBubble = (ctx: CanvasRenderingContext2D, e: Entity | PlayerState) => {
    if (!e.speechBubble) return;
    ctx.save(); ctx.translate(e.x, e.y - e.radius - 20);
    const text = e.speechBubble.text; ctx.font = "bold 18px Arial"; const m = ctx.measureText(text); const w = m.width + 24; const h = 36;
    ctx.fillStyle = 'rgba(255, 255, 255, 0.95)'; ctx.strokeStyle = e.speechBubble.color; ctx.lineWidth = 3;
