        const { player, entities, particles, labels, camera, status } = gameState;
        const visualTime = performance.now() / 16;
        ctx.setTransform(1, 0, 0, 1, 0, 0); ctx.fillStyle = '#0f172a'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.translate(canvas.width / 2, canvas.height / 2); ctx.scale(camera.zoom, camera.zoom); ctx.translate(-camera.x, -camera.y);

