import { CREATURES, WORLD_SIZE, MAX_ENTITIES, BOOST_CONFIG, MAX_OBSTACLES, GAME_MECHANICS, MAX_POWERUPS, METEOR_CONFIG, EVOLUTION_THRESHOLDS, SKINNY_PHRASES, REVERSAL_PHRASE, PORTAL_CONFIG, BIOME_CONFIGS, BUILDING_CONFIGS, MAP_SHAPE_CONFIG, TREASURE_CONFIG } from './constants';
import { CreatureType, Entity, GameState, GameStatus, Obstacle, Particle, PlayerState, PowerUp, Hazard, Projectile, Portal, BiomeType, Building, BuildingType, Treasure, Cosmetics, Label } from './types';

const uuid = () => Math.random().toString(36).substr(2, 9);

const dist = (e1: {x: number, y: number}, e2: {x: number, y: number}) => 
  Math.hypot(e1.x - e2.x, e1.y - e2.y);

export const createParticle = (x: number, y: number, color: string): Particle => ({
  id: uuid(),
  x,
  y,
  vx: (Math.random() - 0.5) * 8,
  vy: (Math.random() - 0.5) * 8,
  life: 1.0,
  maxLife: 1.0,
  color,
  size: Math.random() * 4 + 2
});

export const createLabel = (x: number, y: number, text: string, color: string): Label => ({
    x, y, text, color, life: 60
});

export const getMapBoundaryRadius = (angle: number): number => {
    const variance = MAP_SHAPE_CONFIG.PETAL_VARIANCE * Math.abs(Math.sin(2 * angle));
    return MAP_SHAPE_CONFIG.BASE_RADIUS + variance;
};

const clampToMap = (entity: {x: number, y: number, radius: number, angle: number, vx?: number, vy?: number}, isBattleTest?: boolean) => {
    const cx = MAP_SHAPE_CONFIG.CENTER_X;
    const cy = MAP_SHAPE_CONFIG.CENTER_Y;
    const dx = entity.x - cx;
    const dy = entity.y - cy;
    const currentDist = Math.hypot(dx, dy);
    const angle = Math.atan2(dy, dx);
    const maxR = isBattleTest ? 800 : getMapBoundaryRadius(angle);
    const limit = maxR - entity.radius;

    if (currentDist > limit) {
        const correctedDist = limit - 20;
        entity.x = cx + Math.cos(angle) * correctedDist;
        entity.y = cy + Math.sin(angle) * correctedDist;
        if (entity.vx !== undefined && entity.vy !== undefined) {
             entity.vx *= -0.2; 
             entity.vy *= -0.2;
        }
    }
};

export const createEntity = (type: CreatureType, x: number, y: number): Entity => {
  const config = CREATURES[type];
  return {
    id: uuid(),
    type, x, y, vx: 0, vy: 0,
    radius: config.baseRadius,
    angle: Math.random() * Math.PI * 2,
    health: config.health, maxHealth: config.health,
    speed: config.speed, config, mouthOpenValue: 0,
    isHidden: false, isIdle: false, lureActive: false, camoActive: false, ambushTimer: 0,
    animOffset: Math.random() * 100, renderScale: 1.0,
    combat: { alertness: 0, isStealth: false, stealthTimer: 0, markTargetId: null, comboCount: 0, lastBiteTime: 0 },
    cosmetics: {
        teeth: 'NORMAL', skinColor: 'DEFAULT', pattern: 'NONE', scaleType: 'NONE', accessory: 'NONE',
        tailType: 'DEFAULT', bodyType: 'DEFAULT', mouthType: 'TRIANGLE', eyeType: 'NORMAL', eyebrowType: 'NONE', trailType: 'NONE'
    }
  };
};

const isBackstab = (attacker: {x: number, y: number, angle: number}, victim: {x: number, y: number, angle: number}): boolean => {
    const dx = attacker.x - victim.x;
    const dy = attacker.y - victim.y;
    const angleToAttacker = Math.atan2(dy, dx);
    let diff = angleToAttacker - victim.angle;
    while (diff > Math.PI) diff -= Math.PI * 2;
    while (diff < -Math.PI) diff += Math.PI * 2;
    return Math.abs(diff) > Math.PI * 0.65; // 在目标后方约 120 度扇区
};

const updateAICombat = (entity: Entity, state: GameState) => {
    const { player } = state;
    if (entity.type === CreatureType.MASCOT) return;

    // 1. 警觉机制：如果玩家在前方且距离近，警觉上升；在后方或隐身，警觉下降
    const d = dist(entity, player);
    const canSeePlayer = !player.combat.isStealth || d < 150;
    const playerInFront = !isBackstab(player, entity);

    let alertChange = -0.5; // 默认平复
    if (canSeePlayer && d < 600) {
        alertChange = playerInFront ? 1.5 : 0.2; 
        if (player.combat.isStealth) alertChange *= 0.1; // 隐身大幅降低警觉增长
    }

    entity.combat.alertness = Math.max(0, Math.min(100, entity.combat.alertness + alertChange));

    // 2. 行为分支
    const isAlert = entity.combat.alertness > 50;
    const isCritical = entity.combat.alertness === 100;

    let targetAngle = entity.angle;
    if (isAlert) {
        // 发现目标：追逐玩家
        const dx = player.x - entity.x;
        const dy = player.y - entity.y;
        targetAngle = Math.atan2(dy, dx);

        // 反制：如果玩家在背后且警觉满，释放【尾浪震荡】
        if (isCritical && isBackstab(player, entity)) {
            state.labels.push(createLabel(entity.x, entity.y, "尾浪震荡!", "#ef4444"));
            player.health -= 15;
            const pushAngle = Math.atan2(player.y - entity.y, player.x - entity.x);
            player.vx += Math.cos(pushAngle) * 20;
            player.vy += Math.sin(pushAngle) * 20;
            entity.combat.alertness = 30; // 消耗警觉
            for(let i=0; i<10; i++) state.particles.push(createParticle(player.x, player.y, "#38bdf8"));
        }
    } else {
        // 巡逻：随机游动
        targetAngle += Math.sin(state.time * 0.05) * 0.1;
    }

    let diff = targetAngle - entity.angle;
    while (diff > Math.PI) diff -= Math.PI * 2;
    while (diff < -Math.PI) diff += Math.PI * 2;
    entity.angle += diff * 0.06;

    const currentSpeed = isAlert ? entity.speed * 1.2 : entity.speed * 0.5;
    entity.vx = Math.cos(entity.angle) * currentSpeed;
    entity.vy = Math.sin(entity.angle) * currentSpeed;
    entity.x += entity.vx;
    entity.y += entity.vy;

    clampToMap(entity, state.status === GameStatus.BATTLE_TEST);
};

const triggerPlayerSkill = (state: GameState, skillIndex: number) => {
    const { player, entities } = state;
    const skill = player.skills[skillIndex];
    if (!skill || skill.cooldown > 0) return;

    if (skill.id === 'shadow_dash') {
        const target = entities.find(e => dist(player, e) < 500);
        if (target) {
            // 影冲：位移到目标尾部
            const backX = target.x - Math.cos(target.angle) * (target.radius + player.radius + 30);
            const backY = target.y - Math.sin(target.angle) * (target.radius + player.radius + 30);
            player.x = backX; player.y = backY;
            player.angle = target.angle; // 自动对准
            state.labels.push(createLabel(player.x, player.y, "影冲!", "#8b5cf6"));
            for(let i=0; i<15; i++) state.particles.push(createParticle(player.x, player.y, "#c084fc"));
            skill.cooldown = skill.maxCooldown;
        }
    } else if (skill.id === 'deep_mist') {
        player.combat.isStealth = true;
        player.combat.stealthTimer = 360; // 6秒
        state.labels.push(createLabel(player.x, player.y, "隐身...", "#94a3b8"));
        skill.cooldown = skill.maxCooldown;
    } else if (skill.id === 'fatal_rip') {
        skill.activeTimer = 180;
        state.labels.push(createLabel(player.x, player.y, "致命准备!", "#ef4444"));
        skill.cooldown = skill.maxCooldown;
    } else if (skill.id === 'weakness_mark') {
        const target = entities.find(e => dist(player, e) < 600);
        if (target) {
            target.combat.isWeakened = true;
            state.labels.push(createLabel(target.x, target.y, "已标记弱点!", "#facc15"));
            skill.cooldown = skill.maxCooldown;
        }
    }
};

export const updateGame = (state: GameState, mouse: {x: number, y: number}, isSpacePressed: boolean, isMouseDown: boolean, screenWidth: number, screenHeight: number, keys?: Record<string, boolean>): GameState => {
  if (state.status === GameStatus.MENU || state.status === GameStatus.SHOP) return state;
  state.time++;

  const { player, entities, particles, labels } = state;

  // 技能输入检测
  if (keys) {
      if (keys['KeyQ']) triggerPlayerSkill(state, 0);
      if (keys['KeyW']) triggerPlayerSkill(state, 1);
      if (keys['KeyE']) triggerPlayerSkill(state, 2);
      if (keys['KeyR']) triggerPlayerSkill(state, 3);
  }

  // 1. 玩家移动逻辑
  let targetAngle = Math.atan2(mouse.y - screenHeight / 2, mouse.x - screenWidth / 2);
  let angleDiff = targetAngle - player.angle;
  while (angleDiff > Math.PI) angleDiff -= Math.PI * 2;
  while (angleDiff < -Math.PI) angleDiff += Math.PI * 2;
  player.angle += angleDiff * 0.12;

  const moveSpeed = isSpacePressed ? player.speed * 2 : player.speed;
  player.vx = Math.cos(player.angle) * moveSpeed; 
  player.vy = Math.sin(player.angle) * moveSpeed;
  player.x += player.vx; player.y += player.vy;
  clampToMap(player, state.status === GameStatus.BATTLE_TEST);

  // 更新玩家状态
  if (player.combat.isStealth) {
