      l.y -= 1; l.life--; return l.life > 0; 
  });

  if (player.health <= 0) state.status = GameStatus.GAME_OVER;

  state.camera.x += (player.x - state.camera.x) * 0.1;
  state.camera.y += (player.y - state.camera.y) * 0.1;

  return state;
};

