import React, { useRef, useEffect } from 'react';
import { GameState, GameStatus, Entity, CreatureType } from '../types';
import { MAP_SHAPE_CONFIG } from '../constants';

interface GameCanvasProps {
  gameState: GameState;
  onMouseMove: (x: number, y: number) => void;
  onMouseDown: () => void;
  onMouseUp: () => void;
}

export const drawCuteFish = (ctx: CanvasRenderingContext2D, entity: Entity, visualTime: number, isPlayer: boolean) => {
    const { radius, animOffset, renderScale, cosmetics, combat } = entity;
    if (!Number.isFinite(radius) || radius <= 0) return;

    ctx.save();
    ctx.translate(entity.x, entity.y);

    // 潜行效果
    if (combat.isStealth) ctx.globalAlpha = 0.3;

    ctx.scale(renderScale, renderScale);

    // 弱点标记视觉
    if (combat.isWeakened) {
        ctx.strokeStyle = `rgba(250, 204, 21, ${0.5 + Math.sin(visualTime * 0.1) * 0.3})`;
        ctx.lineWidth = 4;
        ctx.beginPath();
        ctx.arc(0, 0, radius * 1.3, 0, Math.PI * 2);
        ctx.stroke();
    }

    // 非玩家生物显示警觉条
    if (!isPlayer && combat.alertness > 0) {
        ctx.save();
        ctx.translate(0, -radius - 30);
        ctx.fillStyle = 'rgba(15, 23, 42, 0.8)';
        ctx.fillRect(-25, 0, 50, 6);
        ctx.fillStyle = combat.alertness > 80 ? '#ef4444' : '#facc15';
        ctx.fillRect(-25, 0, 50 * (combat.alertness / 100), 6);
        if (combat.alertness === 100) {
             ctx.fillStyle = 'white'; ctx.font = 'bold 16px Arial'; ctx.textAlign='center'; ctx.fillText('!', 0, -5);
        }
        ctx.restore();
    }

    ctx.rotate(entity.angle);
    const bodyFill = cosmetics?.skinColor === 'DEFAULT' ? entity.config.color : cosmetics?.skinColor || entity.config.color;
    const mouthGap = 0.1 + Math.abs(Math.sin(visualTime * 0.15 + animOffset)) * 0.5;

    // 身体
    ctx.fillStyle = bodyFill;
    ctx.beginPath(); ctx.moveTo(0,0); ctx.arc(0,0, radius, mouthGap, -mouthGap); ctx.fill();

    // 眼睛
    ctx.fillStyle = 'white'; ctx.beginPath(); ctx.arc(radius*0.4, -radius*0.4, radius*0.2, 0, Math.PI*2); ctx.fill();
    ctx.beginPath(); ctx.arc(radius*0.4, radius*0.4, radius*0.2, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle = 'black'; ctx.beginPath(); ctx.arc(radius*0.45, -radius*0.4, radius*0.1, 0, Math.PI*2); ctx.fill();
    ctx.beginPath(); ctx.arc(radius*0.45, radius*0.4, radius*0.1, 0, Math.PI*2); ctx.fill();

    ctx.restore();
};

const GameCanvas: React.FC<GameCanvasProps> = ({ gameState, onMouseMove, onMouseDown, onMouseUp }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current; if (!canvas) return; const ctx = canvas.getContext('2d'); if (!ctx) return;
    const resize = () => { canvas.width = window.innerWidth; canvas.height = window.innerHeight; };
    window.addEventListener('resize', resize); resize();
    let frameId: number;

    const render = () => {
        const { player, entities, particles, labels, camera, status } = gameState;
        const visualTime = performance.now() / 16;
        ctx.setTransform(1, 0, 0, 1, 0, 0); ctx.fillStyle = '#020617'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.translate(canvas.width / 2, canvas.height / 2); ctx.scale(camera.zoom, camera.zoom); ctx.translate(-camera.x, -camera.y);

        // 竞技场光圈
        if (status === GameStatus.BATTLE_TEST) {
            ctx.beginPath(); ctx.strokeStyle = 'rgba(239, 68, 68, 0.2)'; ctx.lineWidth = 15;
            ctx.setLineDash([30, 20]); ctx.arc(MAP_SHAPE_CONFIG.CENTER_X, MAP_SHAPE_CONFIG.CENTER_Y, 800, 0, Math.PI*2); ctx.stroke(); ctx.setLineDash([]);
        }

        particles.forEach(p => { 
            ctx.globalAlpha = p.life; ctx.fillStyle = p.color; ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, Math.PI*2); ctx.fill(); 
        });
        ctx.globalAlpha = 1;
        entities.forEach(e => drawCuteFish(ctx, e, visualTime, false));
        drawCuteFish(ctx, player, visualTime, true);

        labels.forEach(l => {
            ctx.save(); ctx.fillStyle = l.color; ctx.font = 'bold 24px Arial'; ctx.textAlign = 'center';
            ctx.shadowBlur = 10; ctx.shadowColor = 'black'; ctx.fillText(l.text, l.x, l.y); ctx.restore();
        });

        frameId = requestAnimationFrame(render);
    };
    render();
    return () => cancelAnimationFrame(frameId);
  }, [gameState]);

  return <canvas ref={canvasRef} onMouseMove={(e) => onMouseMove(e.clientX, e.clientY)} onMouseDown={onMouseDown} onMouseUp={onMouseUp} />;
};

export default GameCanvas;
